_현가정 = {}      # 검사 한 벌을 도는 동안 걸어 두는 현재 가정 (아래 _금액 이 되짚는다)


def _금액(x, 가정=None):
    """큰 금액을 읽기 좋게. **통화를 본다** — 원이면 억·조, 아니면 m·bn.

    옛 판은 무조건 1e8 로 나눠 「억」을 붙였다. 미국 회차(USD 천)에서는
    17,386,254 천USD 가 「0억」으로 찍혀 **금액이 통째로 안 읽혔다.**

    **가정을 안 넘긴 호출이 열댓 군데 있다.** 그래서 통화 판정을 넣은 뒤에도
    ⑳ 가치 브리지가 「EV 비관 0억 → 낙관 0억」으로 찍혔다(MO 회차, 120bn USD).
    호출부를 다 고치는 대신 **모듈에 걸린 `_현가정` 을 되짚는다** —
    앞으로 새로 쓰는 `_금액(x)` 도 저절로 옳게 나온다.
    """
    if x is None:
        return "-"
    if not isinstance(가정, dict):
        가정 = _현가정
    통화 = "KRW"
    if isinstance(가정, dict):
        통화 = ("%s" % ((가정.get("메타") or {}).get("표시통화") or "KRW")).upper()
    if 통화 != "KRW":
        단위 = ("%s" % ((가정.get("메타") or {}).get("금액단위") or "")).strip()
        곱 = {"천": 1e3, "백만": 1e6, "십억": 1e9}.get(단위, 1.0)
        v = x * 곱
        if abs(v) >= 1e9:
            return "%.2fbn %s" % (v / 1e9, 통화)
        if abs(v) >= 1e6:
            return "%.1fm %s" % (v / 1e6, 통화)
        return "{:,.0f} {}".format(v, 통화)
    # KRW 도 단위를 본다 — 십억원 회차(LG엔솔, 환산배율 1e9)에서 84,708 이 「0억」으로 찍혔다.
    배율 = _수((가정.get("메타") or {}).get("환산배율")) if isinstance(가정, dict) else None
    if not 배율:
        # 환산배율이 안 걸려 있어도 금액단위로 되짚는다 — 레터 경로에서 _현가정 이 비면
        # 9.47조가 「0억」으로 나가던 자리다(SK하이닉스 실측)
        단위 = ("%s" % ((가정.get("메타") or {}).get("금액단위") or "")).strip() if isinstance(가정, dict) else ""
        배율 = {"원": 1.0, "천원": 1e3, "백만원": 1e6, "십억원": 1e9}.get(단위)
    억 = x * (배율 if 배율 else 1.0) / 1e8
    if abs(억) >= 10000:
        return "%.2f조" % (억 / 10000)
    return "{:,.0f}억".format(억)


def 운전자본경계값(가정, R):
    """㉑ ① 의 셈 — 기준일 열(마지막 실적) → 첫 예측 열의 순운전자본(9번 14) 낙차와 그 낙차 ÷ 첫 예측 열 연환산 매출(4번 55).
    자체검사 ㉑ 과 레터 장부 키 「가:대조:운전자본:경계:<시>:<칸>」 이 이 한 함수를 쓴다(레터 v27 6단계 A). 재료가 없으면 None.
    → {"앞열", "뒤열", "앞", "뒤", "낙차", "몫", "연환산매출"}"""
    p = _판(가정)
    W = _줄(R, "9.WC", "14")
    S = _줄(R, "4.Sales", "55")              # 연환산 매출 — 첫 예측 열이 잔여(반기) 기간이어도 같은 자로 잰다
    앞, 뒤 = W[p.기준일], W[p.첫]
    매출 = S[p.첫]
    if None in (앞, 뒤) or not 매출:
        return None
    return {"앞열": p.ID[p.기준일], "뒤열": p.ID[p.첫], "앞": 앞, "뒤": 뒤, "낙차": 뒤 - 앞, "몫": abs(뒤 - 앞) / 매출, "연환산매출": 매출}


def 운전자본검사(가정, 라벨):
    """㉑ — **실적에서 예측으로 넘어가는 이음매에서 운전자본이 튀지 않나.**

    운전자본은 **차이만 현금흐름이 된다.** 그래서 수준이 조금 틀려도 티가 안 나다가,
    **실적 마지막 열과 첫 예측 열 사이가 벌어지면 그 낙차가 통째로 한 번의 현금**이 된다.
    없던 현금이 생기거나 사라지는데 손익에는 아무 자국이 없다.

    실측(SGC에너지) — 회전일수 행 가운데 **재고(182)와 매입채무(186)가 가정에 아예 없어서**
    예측 열에서 0 이 됐다. 실적에는 재고 2,170억 · 매입채무 2,947억이 있었다.
    순운전자본이 3,759억 → 1,857억으로 떨어지고 그 차이 **1,902억이 첫 예측 열에 현금
    유입**으로 섰다. 어느 검사도 안 봤다.

    보는 것 셋
      ① **이음매 낙차** — 실적 마지막 열과 첫 예측 열의 순운전자본 차이가 매출 대비 큰가.
         문턱을 넘으면 경보. 정당할 수도 있다(계절성·구조 변화) — 그러면 적으라는 뜻이다
      ② **빈 회전일수** — 실적 잔액은 있는데 그 항목의 회전일수 행이 비었나.
         비면 예측에서 0 이 되고 ①의 낙차를 만든다
      ③ **회전일수 부호** — 매출채권·재고 회전일수가 음수면 오류
    """
    오류, 경보, 목록 = [], [], []
    R들, 사유 = _세시나리오요약(가정)
    if R들 is None:
        목록.append("  엔진을 못 돌려 운전자본을 못 읽었습니다 — %s" % 사유)
        return 오류, 경보, 목록
    R = R들.get("기준") or list(R들.values())[0]
    p = _판(가정)
    순WC = _줄(R, "9.WC", "14")
    매출줄 = _줄(R, "4.Sales", "54")
    if not any(x is not None for x in 순WC) or not any(x is not None for x in 매출줄):
        목록.append("  재료 없음 — 9번 순운전자본 또는 4번 매출을 못 읽었습니다")
        return 오류, 경보, 목록

    예측첫, 실적끝 = p.첫, p.기준일
    적용 = _적용시나리오(가정)

    # ③ 회전일수 부호
    for r, 이름 in (("178", "매출채권 회전일수"), ("182", "재고 회전일수"),
                   ("186", "매입채무 회전일수")):
        if p.벌(r) is None:
            continue
        for 시 in 시나리오목록:
            줄 = p.A(r, 시)
            음 = [p.열글(i) for i in p.예측영구 if 줄[i] is not None and 줄[i] < 0]
            if 음:
                글 = "  %s(%s행) %s 가 음수입니다: %s열" % (이름, r, 시, "·".join(음))
                if 시 == 적용 or p.A공통(r):          # 15번 R-21 은 적용 시나리오의 9번 회전일수를 센다
                    목록.append(_넘김(글, "R-21"))
                else:
                    오류.append(글)
            if p.A공통(r):
                break                                 # 공통 벌 — 한 번만 본다

    # ② 빈 회전일수 — 실적 잔액이 있는데 행이 없다
    # 190행(기타 WC — 매출 대비 비율)도 같은 함정을 만든다 — 실측(신규 5곳 라운드,
    # 2026-09-09): 실적 w13(미지급·계약부채, −0.97~+0.09)이 있는데 190 을 0 으로 두면
    # 첫 예측에서 그만큼이 한 번의 가짜 현금으로 선다. 다섯 곳 전부 실측 비율을
    # 채워야 했다 — 되풀이 함정 5. (구조.운전자본.기타 = 미사용이면 9번 13 이 서지 않는다 — 190 을 묻지 않는다)
    항목 = [("11", "182", "재고자산"), ("12", "186", "매입채무"), ("10", "178", "매출채권")]
    if p.구["운전자본"]["기타"] == "사용":
        항목.append(("13", "190", "기타 운전자본(미지급·계약부채 등)"))
    빈것 = []
    for wc행, 가정행, 이름 in 항목:
        줄 = _줄(R, "9.WC", wc행)
        실적있음 = any(줄[i] not in (None, 0.0) for i in p.실적)
        채움 = any(p.A(가정행, 시)[i] not in (None, 0.0) for 시 in 시나리오목록 for i in p.예측영구)
        if 실적있음 and not 채움:
            잔액 = next((줄[i] for i in reversed(p.실적) if 줄[i] not in (None, 0.0)), 0.0)
            빈것.append("%s — 실적 %s 인데 %s행이 비어 예측에서 0 이 됩니다"
                       % (이름, _금액(abs(잔액)), 가정행))
    if 빈것:
        목록.append(_넘김("  **회전일수가 빈 항목 %d개** — 실적에는 잔액이 있는데 예측에서 0 이 됩니다\n"
                    "%s\n"
                    "    그 낙차가 첫 예측 열에 **한 번의 현금**으로 섭니다. 정말 0 이면 그렇게\n"
                    "    적고, 아니면 회전일수를 채우십시오"
                    % (len(빈것), "\n".join("      · " + x for x in 빈것)), "C-02"))

    # ① 이음매 낙차
    for 시, Rz in R들.items():
        경 = 운전자본경계값(가정, Rz)                         # 레터 v27 6단계 A — 셈은 이 함수 하나(레터 장부 키 「가:대조:운전자본:경계:…」)
        if 경 is None:
            continue
        앞, 뒤, 매출, 낙차, 비 = 경["앞"], 경["뒤"], 경["연환산매출"], 경["낙차"], 경["몫"]
        if 비 >= 0.05:
            # 2026-10-22 — 첫 예측 열의 연환산 매출이 실적 열의 연환산과 크게 다르면(매출 급증 · 급감 국면) 실적 자의 회전일수를 그대로 곱해도
            # 잔액이 매출 변화만큼 뛴다(하이닉스 실측: 국면 규칙의 중앙값을 첫 열에 걸자 낙차 8.73조 → 23.89조). 이음을 지키는 일수를 함께 낸다
            실매 = _줄(Rz, "4.Sales", "55")[실적끝]
            안내 = ""
            if 실매 and abs(매출 / 실매 - 1) > 0.2:
                채권 = _줄(Rz, "9.WC", "10")[실적끝]
                안내 = ("\n    첫 추정 열 연환산 매출이 실적 열 연환산의 %.2f배다 — 실적 자의 회전일수를 첫 열에 그대로 두면 잔액이 매출 변화만큼 뛴다. "
                        "첫 열은 기준일 잔액과 잇는 일수(매출채권이면 기준일 잔액 ÷ 첫 열 연환산 매출 × 365 = %.1f일 — 최근 분기 연환산으로 잰 값이 대개 그 근처다)로 두고 "
                        "국면 · 중앙값 규칙은 다음 열부터 건다(「첫 예측 열은 기준일 잔액과 잇는다」)"
                        % (매출 / 실매, (채권 or 0.0) / 매출 * 365))
            # 적용 시나리오 줄은 15번 R-22 로 넘기고, 비관 · 낙관 줄에도 같은 번호를 단다 — 같은 계절성 낙차를 한 의견(`검토의견.R-22`)으로
            # 세 시나리오 모두 닫는다(2026-10-23 실측: 기준만 닫히고 비관 · 낙관 경보는 닫을 길이 없었다 · 검토번호 ㉑ = R-22*)
            (목록 if 시 == 적용 else 경보).append((lambda x: _넘김(x, "R-22") if 시 == 적용 else _검토(x, "R-22"))(
                       "  **%s — 실적과 추정치의 경계에서 순운전자본이 %s 변동합니다** "
                       "(실적 %s → 추정 %s,\n"
                       "    첫 추정 열 연환산 매출의 %.0f%%). 이 변동분은 전액 **일시적 현금 유출입**"
                       "으로 계상되고\n"
                       "    손익계산서에는 반영되지 않습니다. 운전자본의 계절성이나 구조 변화가"
                       " 원인이면 그 사실을 적고,\n"
                       "    아니면 회전기간을 실적과 연속하도록 조정하십시오%s"
                       % (시, _금액(낙차), _금액(앞), _금액(뒤), 비 * 100, 안내)))
        else:
            목록.append("  %s 경계 낙차 %s (첫 추정 열 연환산 매출의 %.1f%%)"
                        % (시, _금액(낙차), 비 * 100))
    # 미지급 항목(9번 2m* — 구조.운전자본.미지급항목)은 순운전자본(9번 14) 밖에서 2번 111 로 FCFF 에 든다 — 경계의 크기를 적는다
    if _있는줄(R, "2.DCF", "111"):
        _미 = _줄(R, "2.DCF", "111")[예측첫]
        _잔 = _줄(R, "9.WC", "293")
        목록.append("  미지급 항목 — 첫 예측 열 증감(2번 111) %s · 잔액(9번 293) %s → %s"
                    % (_금액(_미), _금액(_잔[실적끝]), _금액(_잔[예측첫])))
    # ④ 경계(S6-05) — 13번 기타 운전자본 행(14 · 15 · 35 · 36 · 40 · 43)은 순운전자본(9번 13) · 이자부부채 · 부채성 브리지(218) · 명시적 제외
    #    가운데 한 곳에만 선다(운전자본 경계 표). 기타 = 미사용이면 기준일 잔액이 9번에 안 선다 — 218 근거가 그 처리를 적었는지 본다.
    #    기타 = 사용이면 190 실적 자에 든 행(충당부채 40 · 미지급금 36 …)을 218 이 또 더하고 빼는지(이중) 본다(X9 의 넓힘 — 근거 글로)
    목록.append("")
    기타행 = (("14", 1, "기타수취채권"), ("15", 1, "기타유동자산"), ("35", -1, "기타지급채무"), ("36", -1, "미지급금"), ("40", -1, "충당부채"),
            ("43", -1, "기타유동부채(계약부채 포함)"))
    기준 = p.기준일
    잔 = {번: p.H(번)[기준] for 번, _부, _이 in 기타행}
    if any(v not in (None, 0.0) for v in 잔.values()):
        순 = sum((잔[번] or 0.0) * 부 for 번, 부, _이 in 기타행)
        미지급 = 0.0
        for 항 in p.구["운전자본"]["미지급항목"]:                        # 미지급 항목 가운데 성과급 — 그 잔액은 기타지급채무 · 미지급비용 안에 있다(9번 2m7 기준일)
            if 항.get("발생") == "성과급" and _있는줄(R, "9.WC", "2%d7" % 항["번호"]):
                v = _줄(R, "9.WC", "2%d7" % 항["번호"])[기준]
                미지급 += v if isinstance(v, (int, float)) else 0.0
        S기 = _줄(R, "4.Sales", "55")[기준] or _줄(R, "4.Sales", "55")[예측첫]
        근218 = (가정.get("근거") or {}).get("218")
        근218 = " ".join("%s" % x for x in 근218) if isinstance(근218, (list, tuple)) else "%s" % (근218 or "")
        행글 = " · ".join("%s %s %s" % (번, 이, _금액(잔[번])) for 번, _부, 이 in 기타행 if 잔[번] not in (None, 0.0))
        if p.구["운전자본"]["기타"] == "미사용":
            남는 = 순 + 미지급                                         # 성과급 · 법인세는 미지급 항목이 받는다(부채 = 음수 몫을 되돌린다)
            언급번 = [번 for 번, _부, 이 in 기타행 if 잔[번] not in (None, 0.0) and _행언급(근218, 번, 이)]
            언급 = [이 for 번, _부, 이 in 기타행 if 번 in 언급번]
            안다룬 = sum((잔[번] or 0.0) * 부 for 번, 부, _이 in 기타행 if 번 not in 언급번) + (미지급 if "35" not in 언급번 else 0.0)
            글 = ("  기타 = 미사용 — 기준일 기타 운전자본 %s(%s · 미지급 항목(성과급)이 받는 몫 %s 를 뺀 순 %s · 연환산 매출의 %.1f%%)은 9번 순운전자본에 서지 않는다.\n"
                 "    운전자본 경계 표: 영업 순환에서 매기 생기는 몫이면 운전자본(기타 = 사용 · 190), 설비 미지급금 · 장기 부채성이면 브리지(218) · 이자부부채, 영업과 무관하면 제외 + 까닭"
                 % (_금액(순), 행글, _금액(-미지급), _금액(남는), (abs(남는) / S기 * 100) if S기 else 0.0))
            if S기 and abs(안다룬) / S기 >= 0.01:
                경보.append(글 + "\n    218 근거가 다루지 않은 행 %s(순 %s · 연환산 매출의 %.1f%%) — 그 처리(브리지 · 이자부부채 · 제외 + 까닭)가 없다. "
                            "기준일 잔액이 아무 데도 없이 사라진다(S6-05)%s" % (
                                " · ".join(이 for 번, _부, 이 in 기타행 if 잔[번] not in (None, 0.0) and 번 not in 언급번), _금액(안다룬),
                                abs(안다룬) / S기 * 100, (" · 다룬 행: " + " · ".join(언급)) if 언급 else ""))
            else:
                목록.append(글 + ("\n    218 근거가 다룬 행: %s" % " · ".join(언급) if 언급 else ""))
        else:
            겹 = [이 for 번, _부, 이 in 기타행 if 잔[번] not in (None, 0.0) and _행언급(근218, 번, 이)]
            if 겹:
                경보.append("  기타 = 사용 — 190 의 실적 자(13번 14 + 15 − 35 − 36 − 40 − 43)에 든 %s 을(를) 218 근거도 더하고 뺀다 — 같은 잔액이 운전자본과 "
                           "브리지에 두 번 설 수 있다(운전자본 경계 표 · X9 넓힘). 218 에서 빼거나 190 실적 자에서 그 행을 뺀 까닭을 적는다" % " · ".join(겹))
            else:
                목록.append("  기타 = 사용 — 기준일 기타 운전자본 %s(%s)은 9번 13 으로 선다" % (_금액(순), 행글))
    if not 오류 and not 경보 and not any("15번" in x for x in 목록):
        목록.append("  순운전자본이 실적에서 추정으로 연속합니다")
    return 오류, 경보, [x for x in 목록 if x != ""]


def _행언급(글, 번, 이름):
    """근거 글이 13번 그 행을 다뤘나 — 「13번 40」 꼴 번호(뒤에 숫자가 붙지 않게)나 이름(「장기 · 비유동」이 붙은 같은 이름은 다른 행)."""
    import re as _re
    if _re.search(r"13번\s*%s(?!\d)" % 번, 글):
        return True
    핵 = 이름.split("(")[0]
    return bool(_re.search(r"(?<!장기)(?<!비유동)%s(?!\s*\(비유동)" % _re.escape(핵), 글))


def 영구쏠림보고(가정, 라벨):
    """㉒ — **영구가치 비중이 높을 때 규칙이 요구하는 네 줄 보고를 실제로 만든다.**

    예측기간 규칙은 「영구가치 비중이 문턱을 넘으면 **FCFF 합 부호 → 원인 → 트리거 → 처방**
    네 줄을 낸다」고 적어 두었다. **그 조문의 집행기가 없었다** — 검사 ⑦ 이 비중 숫자만
    찍고 지나갔고, 네 줄은 아무도 안 만들었다. 「규칙은 있는데 집행기가 없다」의 세 번째다.

    **비중이 100%를 넘는다는 것은 예측기간 FCFF 현가 합이 음수라는 뜻**이다. 그 자체가
    잘못은 아니다 — 대형 투자 한가운데인 회사는 그렇게 된다. 잘못은 **왜 그런지 안 적는
    것**이다. 그러면 읽는 사람은 「예측을 열 해나 세워 놓고 답은 전부 영구에서 나오네」로
    읽는다.

    네 줄
      ① **부호** — 예측기간 FCFF 현가 합이 음수인가, 얼마인가
      ② **원인** — 어느 열이 음수를 만드나. 그 열에서 CapEx·운전자본·영업 중 무엇이 큰가
      ③ **트리거** — 회수가 예측기간 안에 다 들어왔나. 마지막 예측 열의 FCFF 가 아직
                    오르는 중이면 기간이 짧다는 신호다
      ④ **처방 후보** — 고르지 않는다. 후보와 근거만 낸다(예측기간 연장 / 투자 시점
                      재배치 / 그대로 두고 왜 그런지 적기)

    **막지 않는다.** 비중이 높다고 오류를 내지 않는다 — 신호로 내고 네 줄을 적어 준다.
    """
    # **219 = 0 선언 감지 (2026-09-08 외부 리뷰 수용)** — 0 을 채우면 폴백(ROIC=WACC)이
    # 죽어 재투자율이 0 이 되고, g > 0 과 모순인 채 영구가치가 과대계상된다.
    # **0 과 빈칸을 가른다** (2026-09-08 TSLA 회차 실측) — 예전 조건 `(x or 0) == 0` 은
    # `None or 0 == 0` 이라 **제대로 비운 219 를 0 선언으로 잘못 읽었다.** 폴백이 살아 있는데도
    # 오류가 떴다. `x == 0` 은 None 에 대해 False 라 빈칸을 그냥 지나간다.
    _오류219 = []
    p = _판(가정)
    v219 = [p.S(219, s) for s in 시나리오목록]
    if all(x == 0 for x in v219) and any((p.S(212, s) or 0) > 0 for s in 시나리오목록):
        _오류219.append(
            "  **219행(영구 ROIC)에 0 이 선언돼 있습니다 — 재투자 없이 영구 성장(g>0)하는"
            " 모순.**" + chr(10) +
            "    0 을 지워 비우십시오 — 폴백(ROIC=영구 WACC, 재투자율=g÷ROIC)이 되살아나"
            " 영구 FCF 에서" + chr(10) +
            "    재투자가 정상 차감됩니다. `g = ROIC × 재투자율`")
    오류, 경보, 목록 = [], [], []
    목록.extend(_넘김(x, "I-27") for x in _오류219)
    R들, 사유 = _세시나리오요약(가정)
    if R들 is None:
        목록.append("  엔진을 못 돌려 보고를 못 만들었습니다 — %s" % 사유)
        return 오류, 경보, 목록
    예측 = list(p.예측)
    문턱 = importlib.import_module("엔진.부수").영구비중문턱(sum(p.년[i] for i in p.예측))      # S8-12 — 엔진 · ㉒ · 레터가 한 문턱(예측 5~6년 85% · 7년 이상 80%)

    낸것 = False
    for 시 in 시나리오목록:
        Rz = R들.get(시)
        if not Rz:
            continue
        S = Rz["요약"]
        비중 = _수(S.get("영구가치비중"))
        if 비중 is None or 비중 <= 문턱:
            continue
        낸것 = True
        FCFF = _줄(Rz, "2.DCF", "23")
        합 = _수(S.get("예측기간FCFF현가합"))
        줄들 = []
        # ① 부호
        줄들.append("① 부호 — 예측기간 FCFF 현가 합 %s%s"
                    % (_금액(합) if 합 is not None else "-",
                       " **(음수)**" if (합 or 0) < 0 else ""))
        # ② 원인
        음열 = [i for i in 예측 if FCFF[i] is not None and FCFF[i] < 0]
        if 음열:
            조각 = []
            capex줄, dwc줄, nopat줄 = _줄(Rz, "2.DCF", "21"), _줄(Rz, "2.DCF", "22"), _줄(Rz, "2.DCF", "19")
            for i in 음열:
                # 2번 21(CAPEX) · 22(순운전자본 증감)는 차감 줄이라 양수다(증가가 양수)
                조각.append("%s열 FCFF %s (NOPLAT %s · (−) CapEx %s · (−) ΔWC %s)"
                            % (p.열글(i), _금액(FCFF[i]), _금액(nopat줄[i]),
                               _금액(capex줄[i]), _금액(dwc줄[i])))
            줄들.append("② 원인 — 음수 열 %d개: %s" % (len(음열), " / ".join(조각[:3])
                                                 + (" …" if len(조각) > 3 else "")))
        else:
            줄들.append("② 원인 — 음수 열은 없습니다. 예측기간 FCFF 가 작아서 비중이 큽니다")
        # ③ 트리거
        마지막 = 예측[-1] if 예측 else None
        추세 = ""
        if 마지막 is not None and 마지막 - 1 in 예측:
            앞, 뒤 = FCFF[마지막 - 1], FCFF[마지막]
            if 앞 is not None and 뒤 is not None and 앞 != 0:
                증 = (뒤 - 앞) / abs(앞)
                추세 = ("마지막 두 열 FCFF %s → %s (%+.1f%%)"
                        % (_금액(앞), _금액(뒤), 증 * 100))
                if 증 > 0.03:
                    추세 += " — **아직 오르는 중입니다. 기간이 짧다는 신호입니다**"
        기 = 가정.get("기간") or {}
        줄들.append("③ 트리거 — 예측기간 상세 %s년 · 수렴 %s년 · %s"
                    % (기.get("상세추정연수", "?"), 기.get("수렴연수", 0), 추세 or "추세를 못 읽었습니다"))
        # ④ 처방
        줄들.append("④ 처방 후보(고르지 않습니다) — ㉮ 예측기간을 더 늘려 회수를 담는다 "
                    "㉯ 투자 시점을 재배치한다 ㉰ **그대로 두고 왜 그런지 적는다** — "
                    "대형 투자 한가운데인 회사는 이 모양이 정상입니다")
        글 = ("  **%s 영구가치 비중 %.1f%% (문턱 %.0f%%) — 네 줄 보고**\n%s"
              % (시, 비중 * 100, 문턱 * 100, "\n".join("      " + x for x in 줄들)))
        if 시 == _적용시나리오(가정):                       # 15번 R-01 이 적용 시나리오의 비중을 판정한다 — 네 줄은 그대로 싣는다
            목록.append(_넘김(글, "R-01"))
        else:                                             # 비관 · 낙관도 같은 R-01 의견으로 닫는다(2026-10-23 실측 — 닫을 길이 없었다 · 검토번호 ㉒ = R-01*)
            경보.append(_검토(글, "R-01"))
    if not 낸것:
        목록.append("  세 시나리오 모두 영구가치 비중이 문턱 %.0f%% 아래입니다" % (문턱 * 100))
    return 오류, 경보, 목록


매출줄행 = ("47", "48", "49", "50", "51", "52")     # 4번 매출액 — 매출 구분 1~5 + 기타(6)


def 매출무게검사(가정, 라벨):
    """㉓ — **무게가 몰린 스트림을 안 쪼갰나. 그리고 그 안에 반대 방향이 숨었나.**

    검사 ⑮ 는 **갈래 수만 센다**(공시 3 vs 모델 3). 무게는 안 본다. 그래서
    「시약 77% · 장비 16% · 용역 5%」를 셋으로 쪼갠 모델이 ⑮ 를 통과했다 —
    **디테일이 값을 안 움직이는 데 붙어 있었는데 아무도 안 물었다.**

    보는 것 둘. **무게는 「어디를 볼지」만 정하고, 쪼갤지는 방향 어긋남이 정한다.**

    ① **1위가 나머지 전부의 합보다 큰가**
       고정 %를 안 쓴다 — 이 프로젝트에서 고정 문턱은 이미 한 번 실패했다
       (구조 블록의 「한 해에 3배」가 두 해에 걸친 붕괴를 못 잡았다).
       실측: 씨젠 시약 77~81% > 나머지 19~23% → 걸림 / SGC 건설 48% < 나머지 52% → 안 걸림

    ② **부분 성장률이 뭉친 성장률과 어긋나나** ← **이쪽이 진짜 방아쇠다**
       회사나 애널리스트가 말한 부분 성장률(웹조사의 `관측치`)이 모델의 스트림 성장률과
       크게 다르면 **그 안에 반대 방향이 숨어 있다.**
       실측(씨젠): 회사가 「비호흡기 +22.9%」라 했는데 우리 시약 전체는 +9.1% 였다.
       그 13.8%p 어긋남을 열어 보니 호흡기가 **−4.7%** 였다 —
       한쪽이 빠지고 한쪽이 크는 구조가 한 칸에 가려져 있었다.

    **크기만 크고 안이 균질하면 쪼개도 값이 안 움직인다.** 그래서 ①만으로는 경보를 내지 않고
    ②가 함께 걸릴 때 크게 알린다. ①만 걸리면 목록으로 「여기를 봐라」만 남긴다.

    막지 않는다 — 쪼갤 재료가 없어서 뭉친 것일 수도 있다. 그때는 「못 쪼갰다」고 적으면 된다.
    """
    오류, 경보, 목록 = [], [], []
    R들, 사유 = _세시나리오요약(가정)
    if R들 is None:
        목록.append("  엔진을 못 돌려 매출 무게를 못 읽었습니다 — %s" % 사유)
        return 오류, 경보, 목록
    부분성장문턱 = 0.05
    R = R들.get("기준") or list(R들.values())[0]
    첫 = _판(가정).첫
    # 모델 갈래 — 합계 경로를 빼고 하위 구분을 따로 센다(S2-07). 이름은 구조의 매출 구분 이름
    무게 = [(s, 이름, v) for s, 이름, v in _모델갈래(가정, R, 첫)]
    if not 무게:
        목록.append("  재료 없음 — 4번 합계 블록에서 스트림별 매출을 못 읽었습니다")
        return 오류, 경보, 목록
    무게.sort(key=lambda x: -x[2])
    합 = sum(v for _, _, v in 무게)
    목록.append("  스트림 %d갈래 — %s"
                % (len(무게), " · ".join("%s %.1f%%" % (n, v / 합 * 100)
                                        for _, n, v in 무게)))

    일위 = 무게[0]
    나머지 = 합 - 일위[2]
    몰림 = 일위[2] > 나머지
    if 몰림:
        목록.append("  **1위 「%s」가 %.1f%% 로 나머지 전부(%.1f%%)보다 큽니다** — "
                    "그 안을 볼 자리입니다" % (일위[1], 일위[2] / 합 * 100, 나머지 / 합 * 100))

    # ② 부분 성장률 어긋남 — **숫자로 잰다**(S2-09). 관측치 `값` 에서 성장률(「+22.9%」 · 「−4.7%」 · 「YoY 13%」)을 읽고, 1위 갈래의
    #    같은 기간 실적 성장률(13번 원천 85+s — 하위 구분이면 상위의 실적)과 견준다. 5%p 넘게 어긋나면 그 안에 반대 방향이 숨었다는 신호다.
    #    숫자를 못 읽은 관측치는 나열만 한다
    import re as _re
    j = _웹조사읽기()
    부분, 부분수 = [], []
    if isinstance(j, dict):
        for x in (j.get("관측치") or []):
            if not isinstance(x, dict):
                continue
            글자 = "%s %s" % (x.get("항목", ""), x.get("값", ""))
            if "성장" not in 글자 and "%" not in str(x.get("값", "")):
                continue
            부분.append(글자[:90])
            if _re.search(r"성장|증가|감소|YoY|yoy|전년|growth|Growth|증감", 글자):
                m = _re.search(r"([+\-−–]?)\s*(\d+(?:\.\d+)?)\s*%", "%s" % x.get("값", ""))
                if m:
                    v = float(m.group(2)) / 100.0
                    if m.group(1) in ("-", "−", "–") or _re.search(r"감소", 글자):
                        v = -abs(v)
                    연 = _re.search(r"(20\d\d)", "%s %s" % (x.get("기간", ""), 글자))
                    부분수.append((글자[:60], v, int(연.group(1)) if 연 else None))
    # **이미 쪼갰는지**를 본다 — 공시 갈래 수보다 모델 갈래가 많으면 쪼갠 것이다.
    관 = (가정.get("관측") or {}).get("매출스트림") or {}
    관, _안내 = _블록꼴(관, "근거", "관측.매출스트림")
    if _안내:
        목록.append(_안내)
    공시갈래 = _수(관.get("공시갈래수"))
    모델갈래 = len([1 for _, _, v in 무게 if v])
    쪼갬 = 공시갈래 is not None and 모델갈래 > 공시갈래
    if 쪼갬:
        목록.append("  **공시 %d갈래를 모델에서 %d갈래로 쪼갰습니다** — 무게가 몰린 스트림의 "
                    "안을 이미 열어 본 것입니다" % (int(공시갈래), 모델갈래))

    # 1위 갈래의 실적 성장률(회계연도 끝 두 해) — 하위 구분이면 상위의 실적 한 줄로 잰다(하위는 실적이 없다)
    p = _판(가정)
    s1 = 일위[0]
    y1 = p.구.매출구분(s1) or {}
    실s = int(y1.get("상위") or 0) or s1
    실 = {p.회계연도[i]: v for i, v in zip(range(p.n), p.H(85 + 실s)) if i in p.FY실적 and v}
    어긋, 견줌 = [], []
    for 글, v, 연 in 부분수:
        해 = 연 if (연 and 연 in 실 and (연 - 1) in 실) else (max(실) if 실 and (max(실) - 1) in 실 else None)
        if 해 is None:
            continue
        모 = 실[해] / 실[해 - 1] - 1
        견줌.append("%s: 관측 %+.1f%% · 「%s」 %d년 실적 %+.1f%% · 차 %.1f%%p" % (글[:40], v * 100, 일위[1], 해, 모 * 100, abs(v - 모) * 100))
        if abs(v - 모) >= 부분성장문턱:
            어긋.append(견줌[-1])
    if 견줌:
        목록.append("  부분 성장률 숫자 대조(문턱 %.0f%%p) — %s" % (부분성장문턱 * 100, " / ".join(견줌[:4])))
    if 부분:
        목록.append("  조사가 물어온 **부분 성장률 관측 %d건** — 모델의 스트림 성장률과 "
                    "맞대 보십시오:" % len(부분))
        for x in 부분[:4]:
            목록.append("      · %s" % x)
        if 몰림 and not 쪼갬 and 견줌 and not 어긋:
            목록.append("  무게가 「%s」에 몰렸지만 숫자로 읽은 부분 성장률이 실적 성장률과 %.0f%%p 안에서 맞습니다 — 안이 갈렸다는 신호가 없습니다"
                        % (일위[1], 부분성장문턱 * 100))
        elif 몰림 and not 쪼갬 and 견줌 and 어긋:
            경보.append("  **부분 성장률이 「%s」의 실적 성장률과 %.0f%%p 넘게 어긋납니다** — %s.\n"
                        "    그 안에 반대 방향이 숨어 있다는 신호입니다(씨젠: 「비호흡기 +22.9%%」 ↔ 시약 전체 +9.1%%, 열어 보니 호흡기 −4.7%%).\n"
                        "    쪼갤 재료가 없으면 뭉치되 「못 쪼갰다」고 적고 밴드로 감도를 내십시오" % (일위[1], 부분성장문턱 * 100, " / ".join(어긋[:3])))
        elif 몰림 and not 쪼갬:
            경보.append(
                "  **무게가 「%s」(%.1f%%)에 몰려 있는데 부분 성장률 관측이 %d건 있습니다.**\n"
                "    그 부분 성장률이 이 스트림에 세운 성장률과 **크게 어긋나면 안에 반대 방향이\n"
                "    숨어 있다는 신호입니다.** 실측(씨젠): 회사가 「비호흡기 +22.9%%」라 했는데\n"
                "    시약 전체는 +9.1%% 였고, 열어 보니 호흡기가 −4.7%% 였습니다 —\n"
                "    한쪽이 빠지고 한쪽이 크는 구조가 한 칸에 가려져 있었습니다.\n"
                "    **쪼갤 재료가 없으면 뭉치되 「못 쪼갰다」고 적고 밴드로 감도를 내십시오** —\n"
                "    비중을 지어내면 쪼갠 것이 오히려 더 틀린 값을 만듭니다"
                % (일위[1], 일위[2] / 합 * 100, len(부분)))
        elif 몰림 and 쪼갬:
            목록.append("  무게가 「%s」(%.1f%%)에 몰려 있지만 **이미 쪼갠 뒤라 안 알립니다** — "
                        "부분 성장률 관측 %d건이 그 안으로 들어갔는지 근거 칸에서 보십시오"
                        % (일위[1], 일위[2] / 합 * 100, len(부분)))
    elif 몰림:
        목록.append("  부분 성장률 관측이 없어 **안이 갈렸는지 판정하지 못했습니다** — "
                    "무게만으로는 쪼갤지 정하지 않습니다(크기만 크고 균질하면 쪼개도 "
                    "값이 안 움직입니다)")
    if not 몰림:
        목록.append("  무게가 한 갈래에 몰리지 않았습니다 — 부문별로 나란히 세우는 것이 맞고, "
                    "**새 성장이 붙는 데만 따로** 보십시오(라인 생산능력 · 투자 프로젝트)")
    return 오류, 경보, 목록


# ── 5 · 6번 원가 (v13 — 설계서 5-2 · 5-3) ──────────────────────────────────────
# 원가 줄 k(구조.원가줄)의 금액 줄 — 1~4 → 5번 10 · 13 · 14 · 15, 5~7 → 6번 12 · 14 · 15(엔진 `원가.본줄`).
# 줄의 이름은 구조에 적힌 이름(없으면 「경비 k」), 동인은 그 줄의 산식(매출액비율 · 물가연동 · 물량단위원가 · 설비계수)이다.
원가본줄 = {1: ("5.COGS", "10"), 2: ("5.COGS", "13"), 3: ("5.COGS", "14"), 4: ("5.COGS", "15"),
          5: ("6.SG&A", "12"), 6: ("6.SG&A", "14"), 7: ("6.SG&A", "15")}
원가비율가정 = {1: "80", 2: "84", 3: "88", 4: "92", 5: "112", 6: "116", 7: "120"}   # 매출액비율 줄의 비율(옛 번호)
가격지수가정 = {"원재료": ("98", "원재료 가격 변동률"), "공공요금": ("102", "공공요금 변동률"),
           "소비자물가": ("106", "소비자물가 변동률")}
산식동인 = {"매출액비율": "매출액(또는 불변가격 매출액) × 비율", "물가연동": "기준 금액 × 물가",
         "물량단위원가": "단위원가 × 전사 판매량 지수", "설비계수": "설비 계수 × 취득원가",
         "지표계수": "지표 계수 × 지표(매출 구분 판매량 · 평균 인원 · 기초 유형자산)"}


def _고정몫(x, 인구=None, e521=None):
    """원가 줄 산식 하나가 매출 · 물량에 비례하지 않는 몫(0 · 1) — 물가연동 · 설비계수 · 지표계수(순장부)는 매출이 움직여도
    따라 움직이지 않는다(물가 · 설비를 따른다). 매출액비율 · 물량단위원가 · 지표계수(구분 판매량)는 따라 움직인다.
    **지표계수(인원)는 인건비의 인원경로를 따른다**(S3R1-N4) — 인원이 물량연동이면 1 − A-521, 증가율 · 수준이면 고정 1. 인건비 자신과 같은 셈이다."""
    def 한(식):
        if 식 in ("물가연동", "설비계수"):
            return 1.0
        if 식 == "지표계수":
            if x.get("지표") == "구분":
                return 0.0
            if x.get("지표") == "인원" and 인구 and 인구.get("산정방식") == "인원" and 인구.get("인원경로") == "물량연동":
                return max(0.0, 1 - (e521 if e521 is not None else 0.0))
            return 1.0
        return 0.0
    return 한


def 영업레버리지값(가정, R=None):
    """㉔ ⑥ (S3-05)의 셈 — 고정비 비중 · 판매량 +10% 판 영업이익 탄력성(DOL) · 실적 DOL 중앙값. 자체검사 ㉔ 와 레터 장부 키
    「가:레버리지:<몫 | DOL | 실적DOL>」 이 이 한 함수를 쓴다(원고가 엔진 숫자를 손으로 적으면 가정이 바뀐 뒤 낡는다 — 2026-10-22 실측).
    R 은 기준 시나리오의 엔진 결과(없으면 돌린다).

    → {"몫", "조각", "DOL", "실적DOL", "실적쌍", "DOL까닭"} — 영업비용이 없으면 몫 None(DOL 도 재지 않는다), 재지 못한 DOL 은 None 과 까닭."""
    p = _판(가정)
    첫 = p.첫
    구 = p.구
    R = R if R is not None else _결과(가정, "기준")

    def 금(시트, 번호, i=첫):
        return _줄(R, 시트, 번호)[i] or 0.0
    줄들 = _원가줄들(가정)
    합, 고정 = 0.0, 0.0
    조각 = []
    e521 = p.S(521, "기준")
    for k, x, 시트, 줄, 이름 in 줄들:
        v = 금(시트, 줄)
        if v <= 0:
            continue
        f = _고정몫(x, 구["인건비"], e521)
        주, 보 = x.get("산식"), x.get("보조산식") or "없음"
        if 보 != "없음":
            w = p.S(700 + 10 * k + 4, "기준")
            w = w if w is not None else 0.0
            몫 = (1 - w) * f(주) + w * f(보)
        else:
            몫 = f(주)
        합 += v
        고정 += v * 몫
        조각.append("%s %s %.0f%%" % (이름, 주 + ("+" + 보 if 보 != "없음" else ""), 몫 * 100))
    인 = 구["인건비"]
    인합 = 금("7.Payroll", "14")
    if 인["산정방식"] != "미분리" and 인합 > 0:
        if 인["산정방식"] == "매출액비율":
            인몫 = 0.0
        elif 인["인원경로"] == "물량연동":
            인몫 = max(0.0, 1 - (e521 if e521 is not None else 0.0))
        else:
            인몫 = 1.0
        # S4-09 — 이익 연동 성과급(7번 43)은 고정이 아니다(영업이익을 따른다 — 탄성 1 위). 고정 몫은 성과급 차감 전 인건비(7번 34)로만 잰다
        성과 = 금("7.Payroll", "43") if 인["산정방식"] == "인원" else 0.0
        바탕 = 금("7.Payroll", "34") if (인["산정방식"] == "인원" and 성과 > 0) else 인합
        합 += 인합
        고정 += 바탕 * 인몫
        조각.append("인건비(%s · %s) %.0f%%%s" % (인["산정방식"], 인["인원경로"], 인몫 * 100,
                                            (" — 성과급 %s 은 변동으로 셈" % _금액(성과)) if 성과 > 0 else ""))
    낸 = {"몫": None, "조각": 조각, "DOL": None, "실적DOL": None, "실적쌍": 0, "DOL까닭": None}
    if 합 <= 0:
        return 낸
    낸["몫"] = 고정 / 합
    # DOL — 판매량 +10% 판(적용 시나리오 · 예측 열 합) · 실적 DOL(13번 62 · 66 의 이어진 해 중앙값)
    try:
        시 = _적용시나리오(가정)
        a, 흔든 = _판매량흔들기(가정, 시, 1.1)
        if 흔든:
            R0, R1 = _결과(가정, 시), _엔진().계산(a, 시)
            e0 = sum((_줄(R0, "6.SG&A", "22")[i] or 0.0) for i in p.예측)
            e1 = sum((_줄(R1, "6.SG&A", "22")[i] or 0.0) for i in p.예측)
            s0 = sum((_줄(R0, "4.Sales", "54")[i] or 0.0) for i in p.예측)
            s1 = sum((_줄(R1, "4.Sales", "54")[i] or 0.0) for i in p.예측)
            if e0 <= 0:
                낸["DOL까닭"] = "예측 열 영업이익 합이 0 이하라 재지 않는다"
            elif s0 and s1 != s0:
                m, o = p.H(62), p.H(66)
                실 = []
                for i0, i1 in zip(p.FY실적, p.FY실적[1:]):
                    if m[i0] and m[i1] and o[i0] and o[i0] > 0 and o[i1] is not None and abs(m[i1] / m[i0] - 1) > 0.02:
                        실.append(((o[i1] - o[i0]) / o[i0]) / (m[i1] / m[i0] - 1))
                낸["DOL"] = ((e1 - e0) / abs(e0)) / ((s1 - s0) / s0)
                if 실:
                    정 = sorted(실)                     # 짝수 개면 가운데 둘의 평균(종전 위쪽 값 — 두 쌍이면 큰 값이 「중앙값」 으로 나갔다 · 회차 20261023 NAVER)
                    낸["실적DOL"], 낸["실적쌍"] = (정[len(정) // 2] if len(정) % 2 else (정[len(정) // 2 - 1] + 정[len(정) // 2]) / 2), len(정)
    except Exception as e:                                   # noqa: BLE001
        낸["DOL"], 낸["DOL까닭"] = None, "잴 수 없다: %s" % ("%s" % e)[:120]
    return 낸


def _영업레버리지(가정, R, 오류, 경보, 목록):
    """㉔ ⑥ · ⑦ (S3-05 · S3-10) — 고정비 비중 · 영업이익 탄력성(DOL) · 물가연동 줄의 매출 대비 표류 · 능력 증분 해의 고정비 계단.

    고정비 비중 = 첫 예측 열 영업비용(원가 줄 + 인건비 — 상각 · 배분 · 재고 변동 뺀) 가운데 매출 · 물량에 비례하지 않는 몫(`_고정몫`, 보조 산식은
    비중 A-7k4 로 가중, 인건비는 인원경로 증가율 · 수준 = 고정 · 물량연동 = 1 − A-521 · 매출액비율 = 0). **0 이면 오류**(영업 레버리지 0 —
    「판관비를 전부 매출액비율 한 줄에 넣으면 영업레버리지가 0」 · 집대성 「있는 회사에서 뭉치는 것은 경보가 아니라 오류」). 검토 의견
    R-61 에 근거(그 회사의 비용이 정말 전부 매출을 따른다)를 적으면 경보로 내린다. 회차 곁 `_raw/동인진단.json` 의 `고정비몫`(성격 사전 —
    성격별 실적에서 잰 고정 몫)이 있으면 모형 몫이 그 절반 아래일 때 경보.
    DOL = 판매량을 10% 올린 판의 영업이익 변화율 ÷ 매출 변화율(적용 시나리오 · 예측 열 합) — 실적 DOL(13번 62 · 66 의 이어진 해 중앙값)과 나란히. 셈은 `영업레버리지값`(레터 장부 키 「가:레버리지」 와 같은 함수)."""
    p = _판(가정)
    구 = p.구
    줄들 = _원가줄들(가정)
    값 = 영업레버리지값(가정, R)
    몫 = 값["몫"]
    if 몫 is None:
        return
    목록.append("  고정비 비중(S3-05) — 첫 예측 열 영업비용(상각 뺀) 가운데 매출 · 물량에 비례하지 않는 몫 %.1f%% (%s)" % (몫 * 100, " · ".join(값["조각"])))
    의견, 의견글 = _지문의견(가정, "R-61")
    if 의견글:
        목록.append("  " + 의견글)
    진 = _동인진단읽기(가정)
    e몫 = _수((진 or {}).get("고정비몫"))
    # 성격별 실적이 있는 회사(원가 줄 둘 이상을 공시 실적으로 세웠거나 E 의 고정비몫이 있다)에서 뭉친 것은 오류, 없는 회사(기능별 표시 · 주석 미수령)는 경보
    공시줄 = [k for k, x, *_ in 줄들 if x.get("실적") == "공시" and any(v for v in p.H(570 + k) if v)]
    성격있음 = (e몫 is not None and e몫 > 0.05) or len(공시줄) >= 2
    if 몫 < 0.005:
        글 = ("  **고정비 비중이 0 입니다 — 영업 레버리지가 없는 모형입니다(S3-05).** 원가 줄 · 인건비가 전부 매출액비율 · 물량 연동이라\n"
             "    매출이 15% 빠지면 비용도 정확히 15% 빠집니다. 비관이 실제보다 덜 나쁘고 낙관이 덜 좋습니다.\n"
             "    고정 성격(임차 · 관리 · 연구개발 · 인건비)은 물가연동 · 설비계수 · 지표계수(인원 · 순장부) · 인원 × 단가로 세웁니다 —\n"
             "    E(동인진단)의 성격 판정이 그 재료입니다. 정말 전부 매출을 따르는 회사면 근거를 검토 의견 R-61 에 적습니다")
        if 성격있음 and not 의견:
            오류.append(글)
        else:
            경보.append(글 + ("  (R-61 의견이 있어 경보로 — 「%s」)" % 의견[:80] if 의견 else
                            "  (성격별 실적이 없는 서식이라 경보 — 기능별 비용 · 동종으로 고정 몫을 잡고 R-61 로 닫는다)"))
    else:
        if e몫 and 몫 < 0.5 * e몫:
            경보.append("  **고정비 비중 %.1f%% 가 성격별 실적의 고정 몫 %.1f%%(동인진단 `고정비몫` — 성격 사전)의 절반 아래입니다(R-61).**\n"
                        "    고정비가 모형에서 사라져 영업 레버리지가 줄었습니다 — 고정 성격 줄을 매출액비율로 건 것이 아닌지 E 의 줄별 판정과 대 봅니다"
                        % (몫 * 100, e몫 * 100))
        elif e몫:
            목록.append("  고정비 비중 — 성격별 실적의 고정 몫 %.1f%%(동인진단) 대비 %.1f%% — 절반 위" % (e몫 * 100, 몫 * 100))
    # DOL — 판매량 +10% 판(셈은 `영업레버리지값`)
    dol = 값["DOL"]
    if 값["DOL까닭"]:
        목록.append("  영업이익 탄력성(DOL) — %s" % 값["DOL까닭"])
    elif dol is not None:
        목록.append("  영업이익 탄력성(DOL) — 판매량 +10%% 판 %.2f배%s" % (
            dol, (" · 실적 DOL 중앙값 %.2f배(%d쌍 — 단가 · 믹스가 섞인 값)" % (값["실적DOL"], 값["실적쌍"])) if 값["실적쌍"] else " · 실적 DOL 잴 쌍 없음"))
        if dol < 0:
            목록.append("  영업이익 탄력성이 음수 — 판매량을 올리면 영업이익이 준다(공헌이익이 음수인 구간 · 물량에 붙은 비용이 매출보다 크다). "
                        "물량 원가 · 단위원가 변동률을 확인한다")
        elif dol < 1.02 and 몫 >= 0.005:
            경보.append("  **판매량 +10%% 판의 영업이익 탄력성이 %.2f배 — 영업이익이 매출과 같은 비율로만 움직입니다(S3-05).** 고정비가 있으면 1 보다 커야 "
                        "합니다 — 고정 줄이 물량 · 매출을 따라 움직이게 걸리지 않았는지 봅니다(R-61)" % dol)
    # ⑦ 물가연동 줄의 매출 대비 표류(S3-10 — 관련범위) · 능력 증분 해의 고정비 계단
    매 = _줄(R, "4.Sales", "54")
    표류 = []
    for k, x, 시트, 줄, 이름 in 줄들:
        if x.get("산식") != "물가연동" or (x.get("보조산식") or "없음") != "없음":
            continue
        v = _줄(R, 시트, 줄)
        관 = [v[i] / 매[i] for i in p.FY실적 if v[i] and 매[i]]
        if len(관) < 2:
            continue
        lo, hi = min(관), max(관)
        for 시 in 시나리오목록:
            try:
                Rs = _결과(가정, 시)
            except Exception:                                # noqa: BLE001
                continue
            vs, ms = _줄(Rs, 시트, 줄), _줄(Rs, "4.Sales", "54")
            밖 = [(i, vs[i] / ms[i]) for i in p.예측 if vs[i] and ms[i] and not (0.7 * lo <= vs[i] / ms[i] <= 1.3 * hi)]
            if 밖:
                i, r = 밖[-1]
                표류.append("%s %s %s %.2f%%(관측 %.2f~%.2f%%)" % (이름, 시, p.열글(i), r * 100, lo * 100, hi * 100))
    if 표류:
        경보.append("  **물가연동 원가 줄의 매출 대비 비율이 관측 범위의 0.7~1.3배 밖으로 나갑니다(S3-10 · R-61)** — %s.\n"
                    "    물량이 크게 움직이는 시나리오에서 고정비를 물가로만 밀면 관련범위를 벗어납니다 — 보조 산식(매출액비율 · 비중 A-7k4)을 섞거나\n"
                    "    수준 조정(A-7k3)을 시나리오별로 두고, 증설 시점의 고정비 계단을 근거에 적습니다" % " · ".join(표류[:4]))
    능 = [None] * p.n
    for x in 구.목록("매출구분"):
        s = x.get("번호")
        if x.get("판매량산정") == "능력" and s and s < 6:
            v = _줄(R, "4.Sales", "1%d8" % s)
            for i in p.예측:
                if v[i] is not None:
                    능[i] = (능[i] or 0.0) + v[i]
    계단 = [p.열글(i1) for i0, i1 in zip(p.예측, p.예측[1:]) if 능[i0] and 능[i1] and 능[i1] / 능[i0] - 1 > 0.10]
    if 계단 and any(x.get("산식") == "물가연동" for _k, x, *_ in 줄들):
        목록.append("  고정비 계단(S3-10) — 생산능력이 10%% 넘게 느는 해(%s)에 물가연동 줄은 물가로만 큽니다. 증설로 고정비가 한 단 뛰면 수준 조정(A-7k3)"
                    "이나 보조 산식으로 표시하고, 표시하지 않으면 그 사실을 근거에 적습니다(816 · 823)" % " · ".join(계단[:4]))


def _총액서식(가정):
    """원가 줄 실적이 성격별이 아니라 총액(기능별 매출원가 · 판관비 — 인건비 · 주식보상 · 상각 포함)뿐인 서식인가 → (참 · 거짓, 까닭).
    E(동인진단)의 `비용표시` = 기능별이 1순위, 없으면 13번에 종업원급여(531) · 원가 줄 실적(57k)이 다 비고 매출원가(63)만 있는 꼴(미국 GAAP ·
    성격별 주석을 못 받은 회사 — 국가를 보지 않는다)."""
    진 = _동인진단읽기(가정)
    if isinstance(진, dict) and 진.get("비용표시"):
        return 진["비용표시"] == "기능별", "동인진단 비용표시 = %s" % 진["비용표시"]
    if isinstance(진, dict) and ("%s" % (진.get("노드정의") or "")).startswith("기능별"):
        return True, "동인진단 노드정의 = 기능별"
    원 = 가정.get("원천") or {}

    def 있다(r):
        v = 원.get(r)
        return isinstance(v, dict) and any(isinstance(x, (int, float)) and not isinstance(x, bool) and x for x in v.values())
    if not 있다("531") and not any(있다("57%d" % k) for k in range(1, 8)) and 있다("63"):
        return True, "13번 종업원급여(531) · 원가 줄 실적(57k)이 비고 매출원가(63)만 있다"
    return False, ""


def _총액인건비이중(가정, R, p, 줄들, 오류, 목록):
    """㉔ ②-2 (S3R1-N1) — 총액 서식(기능별 표시 등)에서 인건비를 7번에서 따로 세웠는데(산정방식 ≠ 미분리) 원가 줄만으로 이미 실적 현금 영업비용
    (매출원가 + 판관비 − 상각) 수준이면 인건비가 두 번 실린 것이다. 판정: 첫 예측 열 원가 줄 합 ÷ 매출 > 실적 마지막 회계연도 현금 영업비용 ÷ 매출 −
    인건비 ÷ 매출 × 0.5(인건비의 절반 넘게 원가 줄에 이미 있다) · 인건비가 매출의 2% 이상일 때 → 오류."""
    방식 = p.구["인건비"]["산정방식"]
    if 방식 == "미분리":
        return
    총액, 까닭 = _총액서식(가정)
    if not 총액:
        return
    첫 = p.첫
    매 = _줄(R, "4.Sales", "54")[첫] or 0.0
    끝 = next((i for i in reversed(p.FY실적) if p.H(62)[i]), None)
    if not 매 or 끝 is None:
        목록.append("  총액 서식(%s) · 인건비 %s — 첫 예측 열 매출이나 실적 회계연도 매출이 없어 인건비 이중을 재지 않는다" % (까닭, 방식))
        return
    r원 = sum((_줄(R, 시트, 줄)[첫] or 0.0) for k, x, 시트, 줄, 이름 in 줄들) / 매
    r인 = (_줄(R, "7.Payroll", "14")[첫] or 0.0) / 매
    상 = _줄(R, "8.CapEx", "34")[끝] or 0.0
    r현 = ((p.H(63)[끝] or 0.0) + (p.H(65)[끝] or 0.0) - 상) / p.H(62)[끝]
    글 = "원가 줄 %.1f%% · 인건비 %.1f%% (첫 예측 열 · 매출 대비) — 실적 %s 현금 영업비용(매출원가 + 판관비 − 상각) %.1f%%" % (
        r원 * 100, r인 * 100, p.열글(끝) if hasattr(p, "열글") else 끝, r현 * 100)
    if r인 >= 0.02 and r원 > r현 - 0.5 * r인:
        오류.append(
            "  **원가 줄이 총액(인건비 · 주식보상 포함) 수준인 채로 인건비를 「%s」로 또 세웠습니다 — 인건비가 두 번 실립니다(S3R1-N1).**\n"
            "    %s.\n"
            "    총액 서식(%s)의 원가 줄(기능별 매출원가 · R&D · S&M · G&A)에는 인건비가 이미 들어 있습니다.\n"
            "    둘 중 하나로 고칩니다 — ① `구조.인건비.산정방식 = 미분리`(사유는 `스위치사유.인건비산정방식` · R-49) ② 인원 × 단가를 살리려면 원가 줄 비율을\n"
            "    (총액 − 상각 몫 − 1인당 급여 × 인원 × 기능 배분 − 503 에 넣은 주식보상)으로 다시 잽니다 — E(동인진단) 판단 칸 「인건비 분리」"
            % (방식, 글, 까닭))
    else:
        목록.append("  총액 서식(%s) · 인건비 %s — %s · 인건비 이중 아님" % (까닭, 방식, 글))


def _인건비총액검사(가정, R, p, 오류, 경보, 목록):
    """㉔ ②-3 (S4-01) — 13번 531 은 7번이 세우는 인건비 총액(급여 · 퇴직 · 복리후생 · 주식보상 — 성격별 인건비성 줄의 합)이다. 엔진은 급여(7번 31) =
    531 − 성과급(43) − 퇴직(538 · 539) − 복리후생(540) 으로 떼므로 ① 실적 열의 급여가 0 이하면 531 이 그 내역을 품지 않은 정의(인건비 줄만)이다 → 오류.
    ② 회차 곁 `_raw/동인진단.json` 의 인건비 노드 실적(성격별 인건비성 줄의 합)과 531 이 2% 넘게 다르면 경보(복리후생 · 주식보상이 빠졌거나 두 번)."""
    인 = p.구["인건비"]
    if 인["산정방식"] != "인원" or 인["인원경로"] == "수준":
        return
    급 = _줄(R, "7.Payroll", "31")
    h531 = p.H(531)
    나쁜 = [i for i in p.실적 if h531[i] and 급[i] is not None and 급[i] <= 0]
    if 나쁜:
        오류.append("  **실적 급여(7번 31 = 531 − 성과급 − 퇴직 538 · 539 − 복리후생 540)가 0 이하입니다 — %s(S4-01).**\n"
                    "    13번 531 은 인건비 총액(급여 · 퇴직 · 복리후생 · 주식보상)이어야 합니다. 복리후생 · 퇴직을 뺀 「인건비 줄」만 531 에 두고\n"
                    "    540 · 538 을 또 빼면 급여가 사라집니다 — A3(동인원천)를 다시 돌려 531 을 인건비성 줄의 합으로 붓습니다"
                    % " · ".join(p.열글(i) if hasattr(p, "열글") else "%s" % i for i in 나쁜[:3]))
    진 = _동인진단읽기(가정)
    노 = next((x for x in ((진 or {}).get("항목") or []) if isinstance(x, dict) and x.get("노드") == "인건비"), None)
    실 = (노 or {}).get("실적") or {}
    for i in reversed(p.FY실적):
        c = p.ID[i]
        if c and isinstance(실.get(c), (int, float)) and h531[i]:
            차 = 실[c] / h531[i] - 1
            (경보 if abs(차) > 0.02 else 목록).append(
                ("  **13번 531 %s 이 성격별 인건비성 줄의 합 %s 과 %.1f%% 다릅니다(%s · S4-01).** 복리후생 · 주식보상 줄이 531 밖에 있거나 두 번 들었습니다 — "
                 "A3 를 다시 돌려 531 을 그 합으로 붓습니다" if abs(차) > 0.02 else "  531 대사 — 13번 531 %s · 성격별 인건비성 줄의 합 %s(%.1f%% · %s)")
                % (_금액(h531[i]), _금액(실[c]), 차 * 100, c))
            break


def _영구임금검사(가정, R, p, 줄들, 경보, 목록):
    """㉔ ②-4 (S4-04 · R-46 을 자체검사에도) — 영구기간 열의 1인당 급여 상승률(504[TV])은 g − 영구 열 인원 증가율이다. 엔진은 영구 열 인원을
    최종 예측 연도 말 그대로 두므로 기본값은 g(212)다. 다르게 두면 인건비율이 그 한 해에 한 계단 오른(내린) 채 영구화된다.
    문턱(S5-07 — 양쪽 · 시나리오마다 그 시나리오의 g) — |영구 열 인건비율 − 마지막 예측 열| > 1%p 또는 |504[TV] − g| > 1%p 면 경보. 504[TV] 가 비었으면(0 으로 읽힌다) 경보.
    원가 줄의 수준지수 = 임금 · 인력(S4-08)도 504[TV] 를 읽는다."""
    인 = p.구["인건비"]
    읽는 = (인["산정방식"] == "인원" and 인["인원경로"] != "수준") or any(x.get("수준지수") in ("임금", "인력") for _k, x, *_ in 줄들)
    if not 읽는:
        return
    영, 끝 = p.영구, (p.예측[-1] if p.예측 else None)
    if 영 is None or 끝 is None:
        return
    율 = None
    for 시 in 시나리오목록:
        w = p.A("504", 시)[영]
        g = p.S(212, 시)
        if w is None:
            경보.append(_넘김("  **[%s] 임금상승률(504)의 영구기간 열이 비었습니다 — 0 으로 읽혀 영구 첫해에 실질 임금이 g 만큼 깎입니다(R-46).** 기본값은 g(212)입니다" % 시, "R-46"))
            continue
        if g is None:
            continue
        try:
            율 = _줄(_결과(가정, 시), "7.Payroll", "44")
        except Exception:                                    # noqa: BLE001
            율 = None
        d율 = (율[영] - 율[끝]) if (율 and 율[영] is not None and 율[끝] is not None) else None
        글 = "[%s] 504 영구 열 %.2f%% · g %.2f%%%s" % (시, w * 100, g * 100, (" · 인건비율 영구 열 − 마지막 예측 열 %+.2f%%p" % (d율 * 100)) if d율 is not None else "")
        # S5-07 — 문턱은 양쪽이다(g 보다 1%p 넘게 낮아도 인건비율이 한 계단 내려간 채 영구화된다) · 시나리오마다 그 g 와 견준다
        if (d율 is not None and abs(d율) > 0.01) or abs(w - g) > 0.01:
            경보.append(_넘김("  **영구기간 열의 임금상승률이 g 와 1%%p 넘게 달라 인건비율이 한 계단 움직인 채 영구화됩니다(R-46).** %s.\n"
                             "    영구 열 1인당 상승률의 기본값은 g − 영구 열 인원 증가율(엔진은 인원을 평평하게 두므로 g)입니다. 다르게 두면 근거(504)에 까닭을 적습니다" % 글, "R-46"))
        elif abs(w - g) > 0.0005:
            목록.append("  영구기간 열 임금 — %s(R-46 문턱 안 — 기본값 g 와 다른 까닭을 근거에 적는다)" % 글)
        else:
            목록.append("  영구기간 열 임금 — %s(기본값 g)" % 글)


def _동인진단읽기(가정):
    """회차 곁 `_raw/동인진단.json`(E — 갈래 산출물을 찾는 자리 그대로). 없으면 None."""
    return _갈래파일("동인진단.json")[0]


def _원가줄들(가정):
    """선언된 원가 줄 — [(k, 구조의 줄, 시트 키, 금액 줄 번호, 이름)]."""
    out = []
    for x in _판(가정).구.목록("원가줄"):
        k = x.get("번호")
        if k not in 원가본줄:
            continue
        시트, 줄 = 원가본줄[k]
        out.append((k, x, 시트, 줄, ("%s" % (x.get("이름") or "")).strip() or "경비 %d" % k))
    return out


def _매출경로(가정, 시="기준"):
    """엔진이 낸 연환산 매출(4번 55) — (축 순서의 목록, 첫 예측 열의 자리). 못 부르면 None.

    잔여(반기) 열을 연간 열과 그대로 견주면 **둘째 해가 저절로 2배로 보인다.**
    연환산 줄로 같은 자를 만든 뒤에 방향을 본다."""
    try:
        R = _결과(가정, 시)
        p = _판(가정)
    except Exception:                                        # noqa: BLE001
        return None
    합 = _줄(R, "4.Sales", "55")
    if not any(합[i] for i in p.예측영구):
        return None
    return 합, p.첫


def _인원경로(가정, 시):
    """그 시나리오에서 엔진이 낸 기말 인원(7번 10) — 축 순서의 목록. 인원으로 세우지 않았으면 None 칸뿐."""
    try:
        return _줄(_결과(가정, 시), "7.Payroll", "10")
    except Exception:                                        # noqa: BLE001
        return [None] * _판(가정).n


def _물량지수(가정, 시):
    """(이름, 축 순서의 목록) — 인원 가중 판매량 지수(4번 193, 기간 평균)가 서면 그것, 아니면 전사 판매량 지수(4번 191). 없으면 None."""
    try:
        R = _결과(가정, 시)
    except Exception:                                        # noqa: BLE001
        return None
    for 번호, 이름 in (("193", "인원 가중 판매량 지수(4번 193)"), ("191", "전사 판매량 지수(4번 191)")):
        줄 = _줄(R, "4.Sales", 번호)
        if any(x for x in 줄):
            return 이름, 줄
    return None


def _payroll검사(가정, R, 목록):
    """㉔-b — **인건비를 7번에서 세웠다면(인원 · 매출액비율), 그 값이 앞뒤와 말이 되나.**

    켜기만 하고 아무 데도 안 매면 켠 값이 없다. 실측(한화오션): 인원을 매출과
    무관하게 **+5%씩 늘렸다** — 잔고 소진으로 매출이 줄어드는 구간인데 인원이
    늘어나는 판이 그대로 통과했다. 「매출이 줄어드는데 인원이 는다」는 모순을
    사람이 짚어서 드러났다. 탄성 0.4~0.6 으로 고쳐 매출에 물렸다.

    보는 것 넷
      ① **견줄 줄과 방향이 어긋나나** — 인원경로 = 물량연동이면 인원은 생산능력(물량)을 따라가게 선언한 것이라
         **물량 지수(4번 193 · 191)와** 견주고, 그 밖(증가율 · 수준)은 연환산 매출(4번 55)과 견준다
      ② **인원이 평평한가** — 견줄 줄은 크게 움직이는데 인원이 한 값으로 고정
      ③ **1인당 인건비가 안 오르나**(7번 12) — 임금은 명목이라 물가만큼은 오른다. 물가(106)의 절반에
         못 미치면 실질 임금 삭감을 가정한 것이니 근거가 있어야 한다
      ④ **인건비 배분율 합계(7번 22 = 134 + 138 + 142)가 1 인가** — 1 이 아니면 인건비의 일부가 어디로도 안 가거나 두 번 간다
      ⑤ **531 이 인건비 총액인가**(S4-01 — `_인건비총액검사`) · ⑥ **영구기간 열의 임금상승률이 g 인가**(S4-04 · R-46 — `_영구임금검사`)
    """
    경보 = []
    p = _판(가정)
    열 = list(p.예측)
    경로 = p.구["인건비"]["인원경로"]
    방식 = p.구["인건비"]["산정방식"]

    if 방식 == "인원":
        for 시 in 시나리오목록:
            인원줄 = _인원경로(가정, 시)
            인 = [(k, 인원줄[k]) for k in 열 if 인원줄[k] is not None]
            if len(인) < 2:
                continue
            if 경로 == "물량연동":
                물 = _물량지수(가정, 시)
                if not 물:
                    continue
                기준이름, 기준줄 = 물
            else:
                경 = _매출경로(가정, 시)
                if not 경:
                    continue
                기준이름, 기준줄 = "연환산 매출(4번 55)", 경[0]
            어긋 = []
            for (a, va), (b, vb) in zip(인, 인[1:]):
                if not (기준줄[a] and 기준줄[b]) or not va:
                    continue
                기증 = 기준줄[b] / 기준줄[a] - 1
                인증 = vb / va - 1
                if abs(기증) > 0.03 and abs(인증) > 0.005 and 기증 * 인증 < 0:
                    어긋.append((a, b, 기증, 인증))
            if 어긋:
                경보.append(
                    "  **[%s] %s 과 인원이 반대로 갑니다 — %d개 구간.**\n"
                    "%s\n"
                    "    그 줄이 주는데 인원이 늘면 **인건비가 동인과 무관하게 부풀어** 마진이\n"
                    "    구조적으로 눌립니다. 반대로 그 줄이 느는데 인원이 줄면 **생산성 개선을\n"
                    "    가정한 것**이니 근거를 적으십시오.\n"
                    "    **비관에서만 어긋나는 일이 흔합니다** — 매출은 시나리오마다 다른데\n"
                    "    인원은 한 벌로 복사해 넣기 때문입니다.\n"
                    "    실측(한화오션): 잔고 소진으로 매출이 주는데 인원을 +5%%씩 늘렸습니다.\n"
                    "    **인원은 동인에 탄성으로 매십시오**(구조.인건비.인원경로 = 물량연동 · 탄력성 521)"
                    % (시, 기준이름, len(어긋), "\n".join(
                        "      · %s→%s 열 %s %+.1f%% ↔ 인원 %+.1f%%"
                        % (p.열글(a), p.열글(b), 기준이름.split("(")[0], m * 100, n * 100)
                        for a, b, m, n in 어긋[:4])))
            elif len(set(round(v, 3) for _, v in 인)) == 1:
                첫값 = next((기준줄[k] for k, _ in 인 if 기준줄[k]), None)
                끝값 = next((기준줄[k] for k, _ in reversed(인) if 기준줄[k]), None)
                if 첫값 and 끝값 and (끝값 / 첫값 > 1.3 or 끝값 / 첫값 < 0.77):
                    # 판정은 ㉖ 의 판매량 연동(R-153 — 판매량을 흔들어 인원이 안 움직이면 경보)이 한다 — 여기서는 적기만 한다
                    목록.append("  [%s] 인원이 %s명으로 평평한데 %s 은 %.0f%% 움직입니다 — 인건비를 고정비로 둔 판입니다"
                                "(판정: ㉖ 판매량 연동 R-153)"
                                % (시, "{:,.0f}".format(인[0][1]), 기준이름, (끝값 / 첫값 - 1) * 100))
        if 경로 == "물량연동":
            목록.append("  인원 — 생산능력(물량)에 탄력성으로 물렸습니다(인원경로 = 물량연동) — 매출이 아니라 "
                        "물량 지수와 방향을 견줍니다(판매단가가 움직이는 매출은 인원을 끌지 않는다)")

    # ①-2 S5-04 — 산정방식 = 미분리인데 원가 줄이 수준지수 = 인력으로 인원 증가율(501)을 읽으면 그 501 이 매출과 말이 되나(인원 ↔ 매출 정합)
    if 방식 == "미분리" and any(x.get("수준지수") == "인력" for x in p.구.목록("원가줄")):
        for 시 in 시나리오목록:
            v501 = p.A("501", 시)
            경 = _매출경로(가정, 시)
            if not 경:
                continue
            매55 = 경[0]
            어긋, 빠름 = [], []
            for a, b in zip(열, 열[1:]):
                if v501[b] is None or not (매55[a] and 매55[b]):
                    continue
                기증 = 매55[b] / 매55[a] - 1
                if abs(기증) > 0.03 and abs(v501[b]) > 0.005 and 기증 * v501[b] < 0:
                    어긋.append((b, 기증, v501[b]))
                elif v501[b] > max(기증, 0.0) + 0.05:
                    빠름.append((b, 기증, v501[b]))
            if 어긋 or 빠름:
                경보.append("  **[%s] 인원 증가율(501 — 원가 줄 수준지수 = 인력이 읽는다)이 매출과 맞지 않습니다** — %s.\n"
                            "    매출이 주는데 인원이 늘거나(반대 방향), 인원이 매출보다 5%%p 넘게 빨리 늘면 인력 비용 줄이 동인과 무관하게 부풉니다(㉔-b)"
                            % (시, " · ".join("%s 매출 %+.1f%% ↔ 인원 %+.1f%%" % (p.열글(b), m * 100, n * 100) for b, m, n in (어긋 + 빠름)[:4])))
            else:
                목록.append("  [%s] 미분리 + 수준지수 인력 — 인원 증가율(501)이 매출 방향과 맞다" % 시)

    # ③ 1인당 인건비(7번 12)
    단가줄 = _줄(R, "7.Payroll", "12")
    단 = [단가줄[i] for i in 열 if 단가줄[i] is not None]
    if len(단) >= 2 and 단[0]:
        해 = sum(p.년[i] for i in 열[1:]) or max(1, len(단) - 1)
        연 = (단[-1] / 단[0]) ** (1.0 / 해) - 1
        목록.append("  1인당 인건비(7번 12) 상승률 — 연 %+.2f%%" % (연 * 100))
        물가 = next((x for x in (p.A("106", "기준")[i] for i in 열) if x is not None), None)
        물가 = 0.02 if 물가 is None else 물가
        if 연 < 물가:                                            # 워크북 R-43 과 같은 문턱(물가 미만 — S4-11 · 2026-10-17. 종전 물가의 절반)
            (목록 if 방식 == "인원" else 경보).append((lambda x: _넘김(x, "R-43") if 방식 == "인원" else x)(
                "  **1인당 인건비가 연 %+.2f%% 입니다 — 물가(%.2f%%)에 못 미칩니다(R-43).**\n"
                "    임금은 **명목**이라 보통 물가만큼은 오릅니다. 평평하게(0%%) 두면\n"
                "    **매년 실질 임금을 깎는 회사**를 가정한 것이고, 그만큼 **인건비가 과소**\n"
                "    계상되어 마진이 저절로 좋아집니다.\n"
                "    실측(한화오션): 1인당 단가를 한 값으로 고정해 10.5년을 세웠습니다 —\n"
                "    합계는 그럴듯했지만 **인건비가 매년 실질로 줄어드는 판**이었습니다.\n"
                "    삭감·동결을 정말 가정한 것이면(구조조정·고임금 이탈·자동화 대체)\n"
                "    **그 근거를 임금상승률(504) · 1인당 평균급여 기준 수준(503) 근거 칸에 적으십시오**"
                % (연 * 100, 물가 * 100)))

    # ④ 배분율 합계(7번 22) — 시나리오마다. 적용 시나리오는 15번 I-09 가 판정한다(목록)
    적용 = _적용시나리오(가정)
    for 시 in 시나리오목록:
        try:
            합줄 = _줄(_결과(가정, 시), "7.Payroll", "22")
        except Exception:                                    # noqa: BLE001
            continue
        어긋열 = [i for i in p.예측영구 if 합줄[i] is not None and abs(합줄[i] - 1.0) > 0.005]
        if not 어긋열:
            continue
        글 = ("  **[%s] 인건비 배분율 합계(7번 22 = 134 매출원가 + 138 경상연구개발비 + 142 판매비와관리비)가\n"
              "    %s 열에서 %.1f%% 입니다 — 1 이 아닙니다(%d개 열).**\n"
              "    합이 1 보다 작으면 인건비의 일부가 **어느 시트에도 안 실리고 사라지고**,\n"
              "    크면 **두 번 실립니다.** 세 칸을 1 로 맞추십시오"
              % (시, p.열글(어긋열[0]), 합줄[어긋열[0]] * 100, len(어긋열)))
        if 시 == 적용:
            목록.append(_넘김(글, "I-09"))
        else:
            경보.append(글)
    return 경보


def 원가스택검사(가정, 라벨):
    """㉔ — **원가를 한 칸에 뭉개지 않았나. 동인별로 쌓았나.** (v13 — 원가 줄 · 인건비 · 감가상각 — 설계서 5-2 · 5-3)

    5번 매출원가는 동인별 줄로 쌓는다.
        원가 줄 k(1~4)  ← 구조.원가줄 — 산식 넷(매출액비율 · 물가연동 · 물량단위원가 · 설비계수) · 가격지수 · 연동기준 · 보조 산식
        노무비(11)       ← 7번 인건비(인원 × 급여 · 매출액비율 — 구조.인건비) × 배분율(134)
        감가상각비(12)   ← 8번(상각률 · 빈티지) × 배분율(168)
        (−) 판관비 배분(152) · (−) 재고자산 변동(153) — 선언했을 때
    6번 판매비와관리비도 원가 줄 5~7 · 인건비(10 · 11) · 감가상각비(13)로 갈린다.

    **그런데 매출액비율 원가 줄 하나에 전체 원가율을 넣어도 합계는 맞는다.** 숫자가 맞으니
    아무 검사도 안 울고, 사람도 「원가율을 넣었다」고 생각하고 넘어간다.
    실측(한화오션 회차): 원가율 81.79% 를 한 칸에 통째로 넣었다. 합계는 맞았지만
      · **환율·후판값·외주단가를 시나리오 축으로 가를 수 없었다** — 한 칸에 뭉쳐 있으니
      · **감가상각이 8번 CapEx 에서 오는데 그것과 이중 계상될 뻔했다**
      · **인건비가 인원×단가로 안 서서** 「매출은 줄고 인원은 늘어나는」 모순을 못 봤다
    원가를 재료비 · 노무비 · 제조경비로 나눠 추정하지 않은 것이
    사람 검토에서 드러났다. **검사가 봤어야 할 자리다.**

    보는 것 다섯
      ① **한 칸 쏠림** — 매출액비율 원가 줄 하나가 원가 줄 합의 70% 를 넘고 동인이 둘 이하인가 → 경보.
         그 줄의 산식이 물가연동 · 물량단위원가 · 설비계수면 동인으로 세운 것이라 목록으로만 적는다
      ② **인건비** — 미분리(구조.인건비.산정방식)면 인건비가 어디로 갔는지 묻는다 · 따로 세웠는데 인건비 합계가 0 이면 오류 ·
         ②-2 총액 서식(기능별 표시 — 원가 줄 = 인건비 · 주식보상을 품은 총액)인데 인건비를 따로 세웠고 원가 줄만으로 실적 현금 영업비용 수준이면 오류(S3R1-N1)
      ③ **감가 이중** — 이름에 상각이 든 원가 줄이 있는데 8번 감가상각비도 그 시트에 실리는가
      ④ **지수 이중** — 매출액비율 원가 줄이 연동기준 매출액인데 가격지수까지 곱하는가 — 원가가 매년 부푼다
      ⑤ **판관 쏠림 · 영업레버리지** — 판관 원가 줄이 한 칸에 몰렸거나 전부 매출액비율인가

    **막지 않는다** — 회사에 따라 한 줄로 충분할 수도 있다. 다만 **그렇게 정한 것인지
    모르고 그렇게 된 것인지**를 묻는다.
    """
    오류, 경보, 목록 = [], [], []
    try:
        R = _결과(가정, "기준")
    except Exception as e:                                   # noqa: BLE001
        목록.append("  재료 없음 — 엔진을 못 돌려 원가 스택을 못 읽었습니다: %s" % e)
        return 오류, 경보, 목록
    p = _판(가정)
    첫 = p.첫
    줄들 = _원가줄들(가정)
    사유표 = 가정.get("스위치사유") or {}

    def 금(시트, 번호):
        return _줄(R, 시트, 번호)[첫] or 0.0

    def 글(k, x, 이름, v, 합):
        return "%s(%s) %.1f%%" % (이름, x.get("산식"), v / 합 * 100)

    # ① 한 칸 쏠림 — 5번 원가 줄
    오번 = [(k, x, 이름, 금(시트, 줄)) for k, x, 시트, 줄, 이름 in 줄들 if 시트 == "5.COGS"]
    합 = sum(v for *_, v in 오번)
    인분리 = p.구["인건비"]["산정방식"] != "미분리"
    if 합 <= 0:
        목록.append("  재료 없음 — 5번 원가 줄(10 · 13 · 14 · 15)이 첫 예측 열에서 전부 0 입니다")
    else:
        목록.append("  원가 스택(5번 원가 줄 · %s) — %s · 노무비 %s · 감가상각비 %s"
                    % (p.열글(첫), " · ".join(글(k, x, 이름, v, 합) for k, x, 이름, v in 오번 if v),
                       _금액(금("5.COGS", "11")), _금액(금("5.COGS", "12"))))
        큰 = max(오번, key=lambda t: t[3])
        산칸 = len([1 for *_, v in 오번 if v > 0]) + (1 if 인분리 else 0)
        몫 = 큰[3] / 합
        if 몫 > 0.70 and 큰[1].get("산식") != "매출액비율":
            목록.append("  「%s」가 원가 줄의 %.0f%% 입니다 — 산식이 %s(%s)이라 매출에 원가율을 뭉갠 것이 "
                        "아니라 동인으로 세운 줄입니다" % (큰[2], 몫 * 100, 큰[1].get("산식"),
                                                   산식동인.get(큰[1].get("산식"), "?")))
        elif 산칸 >= 3 and 몫 > 0.70:
            목록.append("  1위 「%s」가 원가 줄의 %.0f%% 입니다 — 칸이 %d개로 갈려 있어 "
                        "덜 쪼갠 것으로 보지 않습니다(그 산업의 구조일 수 있습니다)"
                        % (큰[2], 몫 * 100, 산칸))
        elif 산칸 <= 2 and 몫 > 0.70:
            경보.append(
                "  **원가가 「%s」(원가 줄 %d — 매출액비율) 한 칸에 %.0f%% 몰려 있습니다(R-61).**\n"
                "    5번 매출원가는 **원가 동인별로** 쌓게 되어 있습니다(원가 줄 1~4 + 7번 인건비 + 8번 감가상각).\n"
                "    **한 칸에 넣어도 합계는 맞지만** 그 칸을 미는 것들을 **시나리오 축으로 가를 수 없습니다.**\n"
                "    **쌓는 축은 「재료·노무·경비」가 아니라 「이 회사의 원가를 미는 것이\n"
                "    무엇인가」입니다.** 제조업이면 재료(원자재가·환율)·외주(외주단가)·\n"
                "    인력(인원×임금)으로 갈리고, 소프트웨어·플랫폼이면 **인력 · 클라우드·호스팅\n"
                "    (트래픽) · 결제 수수료(거래액) · 콘텐츠·라이선스**로 갈립니다.\n"
                "    유통·물류면 매입원가(판매량)·운송비(중량·거리)·임차(면적)입니다.\n"
                "    **가르는 물음은 하나입니다 — 이 칸을 미는 것이 매출인가, 물량인가,\n"
                "    단가인가, 인원인가, 설비인가.** 같은 것이 미는 비용은 묶고, 다른 것이 미는 비용은\n"
                "    가릅니다(산식 — 물량단위원가 · 설비계수 · 물가연동). 갈래 수를 채우는 것이 목적이 아닙니다.\n"
                "    제조업이면 **「비용의 성격별 분류」 주석**이 그 재료입니다.\n"
                "    드라이버를 못 찾았으면 **그렇게 적으십시오** — 아는 척하지 않습니다"
                % (큰[2], 큰[0], 몫 * 100)
                # **사유가 적혀 있으면 같이 싣는다**(2026-09-08 TSLA 회차 외부 검토 수용). 등급은 안 내린다.
                + ((chr(10) + "    **적어 둔 사유** — %s" % ("%s" % 사유표.get("원가스택")).strip())
                   if ("%s" % (사유표.get("원가스택") or "")).strip() else ""))

    # ② 인건비
    방식 = p.구["인건비"]["산정방식"]
    if 방식 == "미분리":
        # **사유가 적혀 있으면 같이 싣는다.** 등급은 안 내린다 — 적었다고 사라질 사실이 아니고,
        # 사람이 한 번 보라는 뜻은 그대로다.
        _사 = ("%s" % (사유표.get("인건비산정방식") or "")).strip()
        목록.append(_넘김(
            "  **인건비를 따로 세우지 않았습니다(구조.인건비.산정방식 = 미분리)** — 5번 노무비(11)·6번 인건비(10 · 11)가 0 입니다.\n"
            "    그러면 인건비는 원가 줄 가운데 하나에 섞여 있는 것인데, **인원 × 1인당 급여로\n"
            "    안 서므로 「매출이 주는데 인원이 는다」 같은 모순을 못 봅니다.**\n"
            "    **인력이 원가의 큰 몫인 회사는 반드시 따로 세웁니다** — 소프트웨어·서비스·조선·건설.\n"
            "    그 회사는 **인원이 곧 능력**이라 인원 없이는 아무것도 안 물립니다(산정방식 = 인원)"
            + (("\n    **적어 둔 사유** — %s" % _사) if _사 else
               "\n    **사유가 안 적혀 있습니다** — 15번 R-49 의 검토 의견(가정의 `검토의견.R-49`)에 적습니다"), "R-49"))
    else:
        인합 = _줄(R, "7.Payroll", "14")
        if not any(인합[i] for i in p.예측):
            경로 = p.구["인건비"]["인원경로"]
            필요 = {("인원", "수준"): (("126", "기말 인원"), ("130", "1인당 인건비")),
                  ("인원", "증가율"): (("126", "기말 인원"), ("501", "인원 증가율"), ("503", "1인당 평균급여 기준 수준")),
                  ("인원", "물량연동"): (("503", "1인당 평균급여 기준 수준"), ("521", "인원의 판매량 탄력성")),
                  }.get((방식, 경로), (("520", "매출액 대비 인건비율"),) if 방식 == "매출액비율" else ())
            빈것 = [(r, nm) for r, nm in 필요 if not (p.A있나(r, 영도=True) or any(p.S(r, s) is not None for s in 시나리오목록))]
            # 밑 가정이 빈칸이면 15번 C-02(가정 미입력)도 센다. 값 전체를 무의미하게 하는 빈칸이라 자체검사도 오류다(S10-02 —
            # 워크북 없이도 막는다). 값을 0 으로 적었으면 자체검사만 본다(오류)
            오류.append((lambda x: _넘김오류(x, "C-02") if 빈것 else x)(
                "  **인건비를 「%s」로 따로 세워 놓고 인건비 합계(7번 14)가 예측 열에서 0 입니다 —\n"
                "    인건비가 통째로 0 으로 들어갑니다.**%s\n"
                "    5번 노무비 · 6번 인건비가 0 이 되어 **비용이 사라지고 마진이 그만큼 부풉니다.**\n"
                "    「미분리」보다 나쁩니다 — 미분리면 인건비가 원가 줄에 섞여\n"
                "    있기라도 하는데, 따로 세운 채로 비면 **어디에도 없습니다.**\n"
                "    실측(한일시멘트): 이 상태에서 첫 예측 열 영업이익률이 **17.74%%** 로 나왔다\n"
                "    (실적 11.84%%). 채우니 실적과 맞았습니다"
                % (방식, ("\n    비어 있는 가정 — %s" % " · ".join("%s행(%s)" % (r, nm) for r, nm in 빈것))
                       if 빈것 else "")))
        else:
            목록.append("  인건비 — 산정방식 %s · 인원경로 %s · 성과급 %s · 첫 예측 열 인건비 합계 %s (7번 14)"
                        % (방식, p.구["인건비"]["인원경로"], p.구["인건비"]["성과급"], _금액(인합[첫])))
            경보 += _payroll검사(가정, R, 목록)

    # ②-2 총액 서식의 인건비 이중(S3R1-N1) — 원가 줄이 기능별 총액(인건비 · 주식보상 포함) 수준인 채로 인건비를 7번에서 또 세웠나
    _총액인건비이중(가정, R, p, 줄들, 오류, 목록)
    # ②-3 531 정의(S4-01) · ②-4 영구기간 열의 임금(S4-04 · R-46)
    _인건비총액검사(가정, R, p, 오류, 경보, 목록)
    _영구임금검사(가정, R, p, 줄들, 경보, 목록)

    # ③ 감가 이중 — 이름에 상각이 든 원가 줄 + 8번 감가상각비가 같은 시트에 실린다
    상각시트 = {"5.COGS": 금("5.COGS", "12"), "6.SG&A": 금("6.SG&A", "13")}
    이중 = [(이름, 시트) for k, x, 시트, 줄, 이름 in 줄들
          if any(w in 이름 for w in ("상각", "감가")) and not any(w in 이름 for w in ("제외", "뺀", "빼고", "없"))
          and 금(시트, 줄) > 0 and 상각시트.get(시트, 0) > 0]
    if 이중:
        경보.append(
            "  **원가 줄 %s 의 이름에 상각이 들었는데 8번 감가상각비도 그 시트(%s)에 실립니다.**\n"
            "    그 줄에 상각을 넣었다면 **이중 계상입니다.** 상각이 아닌 다른 원가면\n"
            "    그렇다고 근거 칸에 적거나 이름을 고치십시오"
            % (" · ".join("「%s」" % a for a, _ in 이중), " · ".join(sorted({b for _, b in 이중}))))

    # ③-2 총액 서식(기능별 표시)의 물가연동 줄 — 기준 금액 7k5 가 실적 총액(상각 포함)과 같으면 상각이 두 번 실린다(S3R2-N2)
    총액, 총까닭 = _총액서식(가정)
    if 총액:
        상각합 = 금("5.COGS", "12") + 금("6.SG&A", "13")
        걸린 = []
        for k, x, 시트, 줄, 이름 in 줄들:
            if "물가연동" not in (x.get("산식"), x.get("보조산식")) or 금(시트, 줄) <= 0:
                continue
            v5 = p.S(700 + 10 * k + 5, "기준")
            실 = p.H(570 + k)
            끝 = next((i for i in reversed(p.FY실적) if 실[i]), None)
            if v5 and 끝 is not None and abs(v5 / 실[끝] - 1) < 0.005 and 상각합 > 0:
                걸린.append("「%s」 7%d5 %s = %s 실적 %s" % (이름, k, _금액(v5), p.열글(끝) if hasattr(p, "열글") else 끝, _금액(실[끝])))
        if 걸린:
            경보.append(
                "  **총액 서식(%s)의 물가연동 줄 기준 금액(7k5)이 실적 총액과 같습니다 — 상각이 두 번 실립니다(S3R2-N2).**\n"
                "%s\n"
                "    기능별 총액에는 상각이 들어 있고 엔진은 8번 상각을 168 · 172 로 5 · 6번에 따로 붙입니다. 7k5 = 마지막 해 총액 − 상각 몫으로 둡니다\n"
                "    (E 동인진단의 판단 칸 7k5 가 그 값을 냅니다 — 상각 각주가 있으면 그 몫으로)"
                % (총까닭, "\n".join("      · " + y for y in 걸린)))

    # ④ 지수 이중 — 매출액비율 줄의 비율은 매출액에 걸리고, 매출액에는 이미 판가 상승이 들어 있다.
    # 연동기준 = 판매량(불변가격 매출액)이면 지수가 단위당 원가 상승을 담는 유일한 자리라 이중이 아니다
    걸린지수 = []
    for k, x, 시트, 줄, 이름 in 줄들:
        지 = x.get("가격지수") or "없음"
        if x.get("산식") != "매출액비율" or x.get("연동기준") != "매출액" or 지 == "없음" or 금(시트, 줄) <= 0:
            continue
        행, 지이름 = 가격지수가정.get(지, (None, 지))
        율 = [v for v in (p.A(행, "기준")[i] for i in p.예측) if v is not None] if 행 else []
        if 율 and max(율) > 0.001:
            걸린지수.append((이름, 지이름, 행, max(율)))
    if 걸린지수:
        경보.append(
            "  **가격지수가 걸린 채 연동기준이 매출액인 매출액비율 원가 줄이 있습니다 — 원가가 매년 부풉니다.**\n"
            "%s\n"
            "    매출액비율 줄은 그 비율에 지수를 **곱합니다.** 비율이 이미 실측 수준을 담고\n"
            "    있으면 지수를 또 걸 이유가 없습니다 — 매출이 물가만큼 커지면 비율은 그대로입니다.\n"
            "    실측(한화오션): 외주비율이 14.60%% → 16.48%% 로 올라 원가율을 **1.9%%p** 밀어\n"
            "    올렸습니다. 단가가 물가보다 빠르게 오르는 국면이면 **비율 자체를 올려 잡거나,\n"
            "    연동기준을 판매량(불변가격 매출액)으로 바꾸십시오** — 그때는 지수가 단위당 원가 상승을 담는 자리입니다"
            % "\n".join("      · 「%s」 × %s(%s행) 최대 %.2f%%" % (a, b, c, d * 100) for a, b, c, d in 걸린지수))

    # ⑤ 판관 스택 — 6번 원가 줄
    육번 = [(k, x, 이름, 금(시트, 줄)) for k, x, 시트, 줄, 이름 in 줄들 if 시트 == "6.SG&A"]
    판합 = sum(v for *_, v in 육번)
    if 판합 > 0:
        목록.append("  판관 스택(6번 원가 줄) — %s · 인건비 %s · 감가상각비 %s"
                    % (" · ".join(글(k, x, 이름, v, 판합) for k, x, 이름, v in 육번 if v),
                       _금액(금("6.SG&A", "10") + 금("6.SG&A", "11")), _금액(금("6.SG&A", "13"))))
        큰판 = max(육번, key=lambda t: t[3])
        if 큰판[3] / 판합 > 0.70 and 큰판[1].get("산식") == "매출액비율" and len([1 for *_, v in 육번 if v]) <= 1:
            경보.append(
                "  **판관비가 「%s」(원가 줄 %d — 매출액비율) 한 칸에 %.0f%% 몰려 있습니다(R-61).**\n"
                "    6번 판매비와관리비도 원가와 같이 **동인별로** 쌓습니다 —\n"
                "    인건비(7번 · 142) · 감가상각(8번 · 172) · 원가 줄 5~7(연구개발 · 매출·거래 연동분 · 고정·물가분).\n"
                "    가르는 물음은 원가와 같습니다 — **이 칸을 미는 것이 매출인가, 물가인가,\n"
                "    인원인가.** 수수료·운반보관·판매수당은 **거래가 밀고**, 관리비·임차료·\n"
                "    광고선전비는 **매출과 상관없이 물가로만 큽니다**"
                % (큰판[2], 큰판[0], 큰판[3] / 판합 * 100))
        # S10-12 — 옛 「원가 줄 7 = 고정 · 물가분 자리」 규칙(줄 7 이 매출액비율이고 판관의 절반 넘으면 「레버리지 0」)은 걷었다. E 이후 줄 번호에는 뜻이 없고
        # (성격이 산식을 정한다 — 동인 지도 규칙), 보조 산식(준변동 — 7k4)을 보지 않아 E 판정을 거꾸로 읽었다(S10 실측: 줄 7 = 매출액비율 + 보조 물가연동인
        # 플랫폼 · 유통 회사가 「레버리지 0」 경보). 영업 레버리지는 아래 `_영업레버리지`(보조 산식 비중 가중 · 인건비 · 고정비 몫) 한 셈이 본다
    # ⑥ 고정비 비중 · 영업 레버리지 · ⑦ 물가연동 표류 · 계단(S3-05 · S3-10)
    _영업레버리지(가정, R, 오류, 경보, 목록)
    return 오류, 경보, 목록


def _capex합(가정, 시):
    """(유지, 성장, 총) — 예측 열의 8번 17(유형자산의 취득 — 유지) · 11(성장 CAPEX — 프로젝트) · 31(CAPEX 합계) 합. 못 부르면 None.

    **12번 148행을 그대로 읽으면 안 된다** — 프로젝트 CAPEX(12번 86p · 8번 14p)는 그 행에 안 들어간다.
    실측(SGC): 성장 CapEx 를 8,700 → 5,800억으로 **줄였는데도** 148행만 보던 검사가 「CapEx 가 기준의 100%」라고 헛울었다."""
    try:
        R = _결과(가정, 시)
    except Exception:                                        # noqa: BLE001
        return None
    p = _판(가정)

    def 합(행):
        줄 = _줄(R, "8.CapEx", 행)
        return sum(줄[i] or 0.0 for i in p.예측)

    return 합("17"), 합("11"), 합("31")


# 시나리오 이야기의 driver 를 셀 때 한 덩어리로 묶는 줄 — 행 수가 아니라 이야기 수를 센다
_물량묶음줄 = ({30, 38, 46, 54, 62, 70}
           | {600 + 10 * s + j for s in range(1, 6) for j in (0, 1, 2)}              # 수준 경로 판매량 · 단위 산출량
           | set(range(670, 700))                                                     # 라인 생산능력
           | {b + 25 * (s - 1) for s in range(1, 6) for b in (273, 277, 281, 285)})    # 가동률 · 수율 · 시장 · 점유율
_단가묶음줄 = ({34, 42, 50, 58, 66}
           | {600 + 10 * s + j for s in range(1, 6) for j in (3, 6, 8, 9)})            # 판매단가 변동률 · 정상 수준 · 유지 · 도달 연도


def _드라이버묶음(행):
    try:
        r = int(행)
    except (TypeError, ValueError):
        return "%s" % 행
    if r in _물량묶음줄:
        return "매출"
    if r in _단가묶음줄:
        return "단가"
    return "%s" % 행


def 시나리오정합검사(가정, 라벨):
    """㉕ — **비관이 「하나의 이야기」인가, 「모든 다이얼을 동시에 최악으로」인가.**

    비관을 짓는 흔한 방법은 **다이얼을 전부 나쁜 쪽으로 한 칸씩 미는 것**이다.
    각 칸은 다 그럴듯하다. 그런데 **동시에 다 일어날 확률**은 아무도 안 센다.
    그렇게 지으면 비관은 시나리오가 아니라 **전멸**이 되고, 주당가치가 음수로
    떨어진다. 그러면 사람은 「비관이 이상하다」고 판단해 **비관을 빼려 한다** —
    잘못 지은 것이 도구를 버리게 만든다.

    실측(한화오션): 비관 −12,137원. 원인은 셋이었다.
      · **CapEx 7,000억을 기준과 똑같이** 썼다 — 매출이 줄고 FCF 가 마이너스인데
        투자를 그대로 한다는 뜻이다
      · **외주단가를 기준 +8%** 로 올렸다 — 물량이 없는데 외주가 비싸진다
      · **임금을 기준 +1.5%** 로 올렸다 — 불황인데 임금이 더 오른다
    셋을 정합성 있게 맞추니 **−12,137 → +10,854원**. 종착 마진 4.65% 는 이 회사의
    2019·2020 실측(3.50% · 2.18%) 바로 위다 — **읽을 수 있는 이야기**가 됐다.

    보는 것 셋(v13 줄로)
      ① **CapEx 가 매출을 안 따라간다** — 비관 연환산 매출(4번 55)이 기준보다 작은데 총 CapEx(8번 31)가
         기준 이상이다. 성장 CAPEX(8번 11 — 프로젝트)는 그대로이고 유지만 줄였으면 「프로젝트는 했는데 안 찬다」로 읽는다
      ② **투입단가가 물량과 반대로 간다** — 물량(매출)이 주는데 임금(504 · 130) · 물가(106) · 원재료(98) ·
         공공요금(102) · 단위원가(7k2)를 기준보다 올렸다. 불황에는 투입단가도 눌린다
      ③ **다이얼 쏠림** — 비관에서 기준보다 불리한 쪽으로 민 driver 의 수(방향선언 · 시나리오이야기).
         매출 · 판매량 · 라인 생산능력은 「매출」, 판매단가 · 정상 수준은 「단가」 한 덩어리로 센다

    **막지 않는다.** 정말 전멸을 그리려는 회차도 있다(부도 직전 기업). 다만
    **그렇게 정한 것인지 모르고 그렇게 된 것인지**를 묻는다.
    """
    오류, 경보, 목록 = [], [], []
    p = _판(가정)
    열 = list(p.예측)
    if not 열:
        목록.append("  재료 없음 — 쓰는 예측 열이 없습니다")
        return 오류, 경보, 목록
    시점 = 가정.get("시점가정") or {}

    def 줄값(행, 시):
        """그 행의 그 시나리오 값 — 열별 가정이면 예측 열 평균, 한 값 가정(시점가정 — 213 · 616 …)이면 그 값.

        **시점 가정도 본다.** 종전에는 열별 가정만 읽어서 213 같은 한 값 가정을 아무리 밀어도
        「안 민 칸」으로 잡혔다(실측 기아 2026-06-30 — 213 이 진폭 1순위 축이었다)."""
        if p.벌(행) is not None:
            났 = [x for x in (p.A(행, 시)[i] for i in 열) if x is not None]
            return (sum(났) / len(났)) if 났 else None
        if str(행) in 시점:
            return p.S(행, 시)
        return None

    경비 = _매출경로(가정, "비관")
    경기 = _매출경로(가정, "기준")
    if not (경비 and 경기):
        목록.append("  재료 없음 — 엔진을 못 불러 매출 경로를 견주지 못했습니다")
        return 오류, 경보, 목록
    매비, _ = 경비
    매기, _ = 경기
    비합 = sum(매비[i] for i in 열 if 매비[i])
    기합 = sum(매기[i] for i in 열 if 매기[i])
    if not 기합:
        목록.append("  재료 없음 — 기준 매출이 0 입니다")
        return 오류, 경보, 목록
    작다 = 비합 < 기합 * 0.98
    목록.append("  비관 매출이 기준의 %.0f%% 입니다(연환산 매출 · 예측 열 합)" % (비합 / 기합 * 100))
    if not 작다:
        목록.append("  비관 매출이 기준보다 작지 않아 ①②를 보지 않았습니다")

    # ① 총 CapEx 가 매출을 안 따라간다 — **유지 + 성장(프로젝트)** 을 함께 본다
    비C = _capex합(가정, "비관")
    기C = _capex합(가정, "기준")
    이야기나 = False          # 「프로젝트는 했는데 안 찬다」 판인가
    if 비C and 기C:
        유비, 성비, 총비 = 비C
        유기, 성기, 총기 = 기C
        if 총기:
            목록.append("  총 CapEx(8번 31) — 비관 %s · 기준 %s (비관이 기준의 %.0f%%)  [유지(17) %s / %s · 성장(11) %s / %s]"
                        % (_금액(총비), _금액(총기), 총비 / 총기 * 100,
                           _금액(유비), _금액(유기), _금액(성비), _금액(성기)))
        if 성기 and 작다:
            cr = 성비 / 성기
            if cr >= 0.98:
                이야기나 = True
                목록.append("    → **「프로젝트는 했는데 안 찬다」 판입니다** — 성장 CAPEX 는 기준의 %.0f%% 로 그대로이고 "
                            "매출이 덜 납니다. **착공·계약이 끝난 프로젝트면 이쪽이 옳습니다**" % (cr * 100))
            else:
                목록.append("    → **「프로젝트를 미룬다·줄인다」 판입니다**(성장 CAPEX 가 기준의 %.0f%%) — "
                            "**계획 발표 단계라 접을 수 있는 프로젝트면 이쪽이 옳습니다**" % (cr * 100))
        if 작다 and 총기 and 총비 >= 총기 * 0.98 and not 이야기나:
            경보.append(
                "  **비관 매출이 기준의 %.0f%% 인데 총 CapEx 는 기준의 %.0f%% 입니다.**\n"
                "    **돈이 없는데 투자를 그대로 하는 판**입니다. 회사는 물량이 빠지면\n"
                "    투자를 **미루거나 접습니다** — 유지보수 수준으로 내리는 것이 보통입니다.\n"
                "    실측(한화오션): CapEx 를 기준과 같이 둔 것이 비관 −12,137원의\n"
                "    가장 큰 몫이었습니다. 유지보수 수준으로 내리니 **+10,854원**이 됐습니다.\n"
                "    **착공이 끝나 정말 계속 쓰는 프로젝트면, 그 CAPEX 를 프로젝트(구조.투자.프로젝트)로 세우십시오** —\n"
                "    그때는 「프로젝트는 했는데 안 찬다」로 읽어 이 경보가 꺼집니다"
                % (비합 / 기합 * 100, 총비 / 총기 * 100))

    # ② 투입단가가 물량과 반대로
    if 작다:
        후보 = [("504", "임금상승률"), ("106", "소비자물가 변동률"),
              ("98", "원재료 가격 변동률"), ("102", "공공요금 변동률")]
        for k, x, 시트, 줄, 이름 in _원가줄들(가정):
            if "물량단위원가" in (x.get("산식"), x.get("보조산식")):
                후보.append(("%d" % (700 + 10 * k + 2), "%s 단위원가 변동률" % 이름))
        어긋 = []
        for 행, 이름 in 후보:
            b, k_ = 줄값(행, "비관"), 줄값(행, "기준")
            # 기준이 음수인 줄(단위원가 변동률 −5% 등)도 있다 — 곱셈 문턱(b > k × 1.005)은 그때 뒤집힌다. 차이를 |기준| 에 견준다
            if b is not None and k_ and (b - k_) > abs(k_) * 0.005:
                어긋.append((행, 이름, (b - k_) / abs(k_)))
        if 어긋:
            경보.append(
                "  **물량이 주는데 투입단가를 기준보다 올린 자리 %d곳.**\n"
                "%s\n"
                "    비관은 **물량이 빠지는 이야기**입니다. 물량이 빠지면 외주단가도\n"
                "    임금 상승도 **눌립니다** — 협상력이 회사 쪽으로 옵니다.\n"
                "    물량 하락과 단가 상승을 **동시에** 걸면 그것은 하나의 이야기가 아니라\n"
                "    **두 악재를 겹쳐 놓은 것**입니다.\n"
                "    단가가 오르는 비관을 정말 그리려면(공급망 충격·환율 급등)\n"
                "    **그때는 물량이 왜 같이 빠지는지**를 근거 칸에 적으십시오"
                % (len(어긋), "\n".join(
                    "      · %s행 %s — 기준 대비 %+.1f%%(|기준| 대비)" % (r, nm, d * 100)
                    for r, nm, d in 어긋)))

    # (3) driver — 다모다란: 시나리오는 **2~3개 driver** 위에 세운다
    #     매출 · 판매량 · 라인 생산능력은 「매출」, 판매단가 · 정상 수준은 「단가」 한 덩어리로 센다 — 행 수가 아니라
    #     **이야기 수**를 센다. 실측(한일시멘트): 이야기는 셋인데 스트림마다 둘씩 밀어 5개로 세어졌다
    묶음 = _드라이버묶음
    선언 = {str(k): v for k, v in (가정.get("방향선언") or {}).items()}
    민것 = set()
    for 행, d in 선언.items():
        if d not in ("비관높음", "비관낮음"):
            continue
        b, k_ = 줄값(행, "비관"), 줄값(행, "기준")
        if b is None or k_ is None or k_ == 0:
            continue
        if (d == "비관높음" and (b - k_) > abs(k_) * 0.001) or (d == "비관낮음" and (k_ - b) > abs(k_) * 0.001):
            민것.add(묶음(행))

    이야기 = ((가정.get("시나리오이야기") or {}).get("비관") or {})
    이야기, _안내 = _블록꼴(이야기, "한줄", "시나리오이야기.비관")
    if _안내:
        목록.append(_안내)
    한줄 = ("%s" % (이야기.get("한줄") or "")).strip()
    잰것 = [묶음(x) for x in (이야기.get("driver") or [])]

    # 낙관도 같은 병에 걸린다 — 「모든 다이얼을 최선으로」. 여기서는 driver 수만 잰다
    낙이야기, _안내2 = _블록꼴((가정.get("시나리오이야기") or {}).get("낙관"),
                          "한줄", "시나리오이야기.낙관")
    if _안내2:
        목록.append(_안내2)
    낙민것 = set()
    for 행, d in 선언.items():
        if d not in ("비관높음", "비관낮음"):
            continue
        b, k_ = 줄값(행, "낙관"), 줄값(행, "기준")
        if b is None or k_ is None or k_ == 0:
            continue
        if (d == "비관높음" and (k_ - b) > abs(k_) * 0.001) or (d == "비관낮음" and (b - k_) > abs(k_) * 0.001):
            낙민것.add(묶음(행))
    if 낙민것:
        목록.append("  낙관이 민 driver — **%d개** (%s)"
                    % (len(낙민것), " · ".join(sorted(낙민것))))
        if len(낙민것) > 3:
            경보.append(
                "  **낙관이 driver %d개를 밀었습니다 — 2~3개가 기준입니다.**\n"
                "    비관과 같은 병입니다 — 각 칸은 그럴듯한데 **동시에 다 잘될 확률**은\n"
                "    아무도 세지 않았습니다. 낙관의 이야기(`시나리오이야기.낙관`)가 미는\n"
                "    칸만 밀고 나머지는 기준 그대로 두십시오" % len(낙민것))

    if 민것:
        목록.append("  비관이 민 driver — **%d개** (%s)"
                    % (len(민것),
                       " · ".join((r if r in ("매출", "단가") else (_이름(라벨, r) or r))
                                  for r in sorted(민것))))

    # ③-a 이야기를 적었나
    if len(한줄) < 10:
        경보.append(
            "  **비관의 이야기가 `시나리오이야기.비관.한줄` 에 안 적혀 있습니다.**\n"
            "    **값을 넣고 나서 이야기를 붙이는 것이 아니라, 이야기를 먼저 적고 그 이야기가\n"
            "    미는 칸만 밉니다.** 「무엇이 어긋나서」 나빠지는지를 한 문장으로 적으십시오 —\n"
            "    예: 「수주가 안 들어오고 선가가 안 오른다」.\n"
            "    이야기 없이 다이얼만 돌리면 **각 칸은 그럴듯한데 동시에 일어날 확률은\n"
            "    아무도 안 센 조합**이 됩니다")
    elif 잰것 and 민것:
        # ③-b 선언과 실제가 같은가 — `딸린행`(축이 물고 움직이는 줄)으로 선언한 줄은 선언 안이다(③-e 와 같은 셈)
        딸린것 = {묶음(x) for x in (이야기.get("딸린행") or [])}
        더민것 = 민것 - set(잰것) - 딸린것
        안민것 = set(잰것) - 민것
        if 더민것 or 안민것:
            줄들 = []
            if 더민것:
                줄들.append("      · 선언에 없는데 민 칸 — %s" % " · ".join(sorted(더민것)))
            if 안민것:
                줄들.append("      · 선언했는데 안 민 칸 — %s" % " · ".join(sorted(안민것)))
            경보.append(
                "  **선언한 이야기와 실제로 민 칸이 다릅니다.**\n"
                "    이야기: 「%s」\n"
                "%s\n"
                "    이야기가 안 미는 칸을 밀었으면 **그 칸은 기준으로 되돌리십시오.**\n"
                "    정말 그 이야기가 그 칸을 민다면 **driver 목록에 넣으십시오** —\n"
                "    둘 중 하나이지, 그냥 둘 자리가 아닙니다"
                % (한줄[:60], "\n".join(줄들)))

    # ③-e **실제로 민 칸을 센다**(S9-07 — 선언을 믿지 않는다). 비관(낙관)이 기준과 다른 열별 · 한 값 · 표 줄을 이야기 묶음(엔진
    # `민감도.이야기묶음` — 매출물량 · 판매단가 · 능력 · 투입단가 · 원가 · 인건비 · 투자 · 운전자본 · 법인세 · 영구 · 할인)으로 묶는다.
    # driver · 딸린행(`시나리오이야기.<쪽>.딸린행` — 축이 물고 움직이는 줄, 「축과 딸린 것을 갈라 적는다」) 밖의 묶음은 「선언 밖 갈림」.
    # 할인(WACC) · 영구성장(212)이 시나리오마다 갈리면 따로 경보한다(「할인율은 시나리오 축에 넣지 않는다」 · g 는 무위험이자율에 묶인다)
    민엔 = importlib.import_module("엔진.민감도")
    실제 = {}
    for 쪽 in ("비관", "낙관"):
        try:
            실제[쪽] = 민엔.시나리오갈림(가정, (쪽,))
        except Exception as e:                                   # noqa: BLE001
            실제[쪽] = {}
            목록.append("  실제 갈림을 못 셌습니다(%s): %s" % (쪽, ("%s" % e)[:120]))
    수따로 = {"할인", "영구성장"}
    for 쪽 in ("비관", "낙관"):
        이 = ((가정.get("시나리오이야기") or {}).get(쪽) or {})
        이 = 이 if isinstance(이, dict) else {}
        선d = {민엔.이야기묶음(x) for x in (이.get("driver") or [])}
        선딸 = {민엔.이야기묶음(x) for x in (이.get("딸린행") or [])}
        묶 = {k: v for k, v in 실제[쪽].items() if k not in 수따로}
        if 묶:
            목록.append("  %s이 실제로 민 이야기 묶음 — %d개(%s) · driver %s · 딸린행 %s" % (
                쪽, len(묶), " · ".join("%s(%s)" % (k, " · ".join(sorted(v, key=lambda x: (len(x), x))[:4])) for k, v in sorted(묶.items())),
                " · ".join(sorted(선d)) or "없음", " · ".join(sorted(선딸)) or "없음"))
        if 묶 and not 선d:
            경보.append("  **%s의 driver 가 비었는데 기준과 다른 이야기 묶음이 %d개입니다(%s).** 선언이 없으면 무엇을 밀었는지 검사가 대 볼 것이 없습니다 — "
                        "`시나리오이야기.%s.driver`(축 2~3개)와 `딸린행`(축이 물고 움직이는 줄)을 갈라 적습니다" % (쪽, len(묶), " · ".join(sorted(묶)), 쪽))
        밖 = sorted(set(묶) - 선d - 선딸)
        if 선d and 밖:
            경보.append("  **%s — driver · 딸린행 밖에서 갈린 묶음 %d개: %s.** 축이 물고 움직이는 줄이면 `딸린행` 에 적고, 아니면 기준으로 되돌립니다(「축과 딸린 것」)"
                        % (쪽, len(밖), " · ".join("%s(%s)" % (k, " · ".join(sorted(묶[k], key=lambda x: (len(x), x))[:4])) for k in 밖)))
        따 = sorted(set(실제[쪽]) & 수따로)
        if 따:
            경보.append("  **%s — %s 이 시나리오마다 갈립니다.** 할인율은 시나리오 축에 넣지 않고 민감도로 봅니다 · 영구성장률은 무위험이자율에 묶입니다 — "
                        "갈라야 하는 까닭이 있으면 근거 칸에 적습니다" % (쪽, " · ".join("%s(%s)" % (k, " · ".join(sorted(실제[쪽][k]))) for k in 따)))
    실수 = len({k for k in 실제.get("비관", {}) if k not in 수따로} - {민엔.이야기묶음(x) for x in ((((가정.get("시나리오이야기") or {}).get("비관") or {}) if isinstance((가정.get("시나리오이야기") or {}).get("비관"), dict) else {}).get("딸린행") or [])})

    # ③-c 몇 개인가 — 실제로 민 이야기 묶음 수(딸린행은 빼고 센다 · S9-07). 선언(방향선언 · driver)만 세던 옛 셈은 선언이 없으면 조용했다
    수 = max(len(민것 or set(잰것)), 실수)
    if 수 > 3:
        경보.append(
            "  **비관이 driver %d개를 밀었습니다 — 2~3개가 기준입니다.**\n"
            "    다모다란은 시나리오를 **가장 중요한 2~3개 factor 위에 세우고** 나머지는\n"
            "    그에 **정합적으로 맞추라**고 합니다(Strategic Risk Taking Ch.6).\n"
            "    입력변수는 서로 독립이 아니라서, 각각을 따로 최악으로 두면 **애초에\n"
            "    존재하지 않는 조합**이 됩니다.\n"
            "    그가 best/base/worst 3분할을 「가장 조잡한 형태」라 부른 이유도 같습니다 —\n"
            "    어떤 투자든 worst 는 통과 못 하고 best 는 실패하지 않아 **판별력이 0** 입니다.\n"
            "    실측(한화오션): driver 4개 → EV 스프레드 4.1배 · 비관 10,854원.\n"
            "    이야기가 미는 둘(수주 부진·선가 정체)만 남기니 **3.5배 · 16,003원**.\n"
            "    **성숙 기업의 bear↔bull 은 대체로 2~3배입니다**(그의 실제 밸류에이션 실측)"
            % 수)

    # ③-d **근거 글이 하는 말과 값이 어긋나나.**
    # 근거 칸에 「이 칸은 축이 아니다」·「세 시나리오에서 같은 값을 쓴다」고 적어 놓고
    # 실제로는 시나리오가 갈리는 자리가 있다. **레터가 그 문장을 그대로 실어 나르므로
    # 독자는 틀린 말을 읽는다** — driver 선언이 아니라 **글**이 값과 어긋나는 종류라
    # 위 ③-b 가 못 본다(선언에도 없고 글에만 있기 때문이다).
    # 실측(CJ프레시웨이): 30행 근거가 「이 칸은 축이 아니다 — 세 시나리오에서 같은 값을
    # 쓴다」인데 비관 1.0% / 기준 2.0% / 낙관 3.0% 로 갈렸고, 레터 부록 A 가 그 문장을
    # 그대로 인쇄했다. (공통 벌 · 값 하나로 적은 줄은 같을 수밖에 없어 보지 않는다)
    말버릇 = ("축이 아니", "같은 값을 쓴다", "같은 값을 쓴", "세 시나리오가 같", "고정이다")
    어긋 = []
    for 행, 칸 in sorted((가정.get("근거") or {}).items(),
                        key=lambda t: int(t[0]) if ("%s" % t[0]).isdigit() else 0):
        글 = " ".join(x for x in (칸 or []) if isinstance(x, str))
        if not any(w in 글 for w in 말버릇):
            continue
        if p.벌(행) is not None and not p.A공통(행):
            기 = p.A(행, "기준")
            for 시 in ("비관", "낙관"):
                시열 = p.A(행, 시)
                if any(기[i] != 시열[i] for i in p.예측영구 if not (기[i] is None and 시열[i] is None)):
                    어긋.append(행)
                    break
        elif str(행) in 시점 and not p.S공통(행):
            셋 = [p.S(행, s) for s in 시나리오목록]
            if not (셋[0] == 셋[1] == 셋[2]):
                어긋.append(행)
    if 어긋:
        오류.append(
            "  **근거 글이 「축이 아니다」라고 적은 칸이 실제로는 갈립니다 — %s행.**\n"
            "    글과 값 중 하나가 틀렸습니다. **레터가 그 문장을 그대로 싣기 때문에**\n"
            "    독자는 「이 칸은 세 시나리오가 같다」고 읽고 넘어갑니다.\n"
            "    값을 되돌리든 글을 고치든 하나로 맞추십시오 — 그냥 둘 자리가 아닙니다"
            % " · ".join(어긋))
    return 오류, 경보, 목록


def _판매량흔들기(가정, 시, 배=1.1, 구분만=None):
    """판매량(또는 생산능력)을 배만큼 올린 가정의 사본 · 흔든 자리 목록 — 예측 · 영구기간 열만(실적 열은 그대로).

      증가율 경로 구분 s(1~5)   첫 예측 열의 판매량 증가율(30 + 8(s − 1)) g → (1 + g) × 배 − 1 — 그 뒤 열의 수준이 다 배만큼
      수준 경로 · 직접          판매량(6s0 기간 평균 · 6s1 기말) × 배
      수준 경로 · 능력          그 구분의 라인 j 생산능력(668 + 2j 기간 평균 · 669 + 2j 기말) × 배
      수준 경로 · 저량          저량 유입(570 + s)과 기준일 저량(시점가정 590 + s · 공시면 13번 600 + s 의 평가기준일 열) × 배 —
                                굴림이 선형이라 예측 열의 저량 · 판매량이 꼭 배만큼 는다(S2-04)
    기타(구분 6)는 판매량이 없어 흔들지 않는다."""
    a = copy.deepcopy(가정)
    p = _판(가정)
    첫ID = p.ID[p.첫]
    예영ID = [p.ID[i] for i in p.예측영구]
    흔든 = []

    def 벌들(번호):
        벌 = (a.get("가정") or {}).get(str(번호))
        if not isinstance(벌, dict):
            return []
        if isinstance(벌.get(시), dict):
            return [벌[시]]
        return [벌["공통"]] if isinstance(벌.get("공통"), dict) else []

    def 곱(번호):
        n = 0
        for 칸 in 벌들(번호):
            for c in 예영ID:
                if _수(칸.get(c)) is not None:
                    칸[c] = _수(칸[c]) * 배
                    n += 1
        return n

    for x in p.구.목록("매출구분"):
        s = x.get("번호")
        if not s or s >= 6 or (구분만 is not None and s != 구분만):
            continue
        if x.get("경로") == "증가율":
            번 = 30 + 8 * (s - 1)
            for 칸 in 벌들(번):
                칸[첫ID] = (1 + (_수(칸.get(첫ID)) or 0.0)) * 배 - 1
                흔든.append("%s 판매량 증가율(%d행 첫 예측 열)" % (_구분이름(가정, s), 번))
        elif x.get("경로") == "수준" and x.get("판매량산정") == "능력":
            for j in [l.get("번호") for l in (x.get("라인") or []) if isinstance(l, dict) and l.get("번호")]:
                if 곱(668 + 2 * j) + 곱(669 + 2 * j):
                    흔든.append("%s 라인 %d 생산능력(%d · %d행)" % (_구분이름(가정, s), j, 668 + 2 * j, 669 + 2 * j))
        elif x.get("경로") == "수준" and x.get("판매량산정") == "저량":
            n = 곱(570 + s)
            if x.get("저량공시") == "예":
                원 = (a.get("원천") or {}).get(str(600 + s))
                기ID = p.ID[p.기준일]
                if isinstance(원, dict) and _수(원.get(기ID)) is not None:
                    원[기ID] = _수(원[기ID]) * 배
                    n += 1
            else:
                시점 = (a.get("시점가정") or {}).get(str(590 + s))
                if isinstance(시점, dict):
                    for k in list(시점):
                        if _수(시점[k]) is not None:
                            시점[k] = _수(시점[k]) * 배
                            n += 1
                elif _수(시점) is not None:
                    a["시점가정"][str(590 + s)] = _수(시점) * 배
                    n += 1
            if n:
                흔든.append("%s 저량 유입 · 기준일 저량(%d · %d)" % (_구분이름(가정, s), 570 + s, 590 + s))
        elif x.get("경로") == "수준":
            if 곱(600 + 10 * s) + 곱(601 + 10 * s):
                흔든.append("%s 판매량(%d · %d행)" % (_구분이름(가정, s), 600 + 10 * s, 601 + 10 * s))
    return a, 흔든


def _구분마다흔들기(가정, 시, R0, 오류, 경보, 목록):
    """S2-02 — 판매량을 **구분마다 하나씩** 10% 올려 그 구분의 물량이 4번 191 · 193 을 읽는 층(물량단위원가 원가 줄 · 판매량연동 유지 CAPEX ·
    물량연동 인원)에 닿는지 본다. 한 구분의 매출은 움직였는데 그 층이 한 자리도 안 움직이면 그 구분의 물량이 공짜로 는다는 뜻이다 —
    가중(표 6s7 원가가중 · 인원가중)이 0 이면 사람이 그렇게 적은 것이니 목록, 아니면 경보. 구분이 하나뿐이면 전 구분 흔들기와 같아 건너뛴다."""
    p = _판(가정)
    구 = p.구
    층 = []
    for k, x, 시트, 줄, 이름 in _원가줄들(가정):
        if "물량단위원가" in (x.get("산식"), x.get("보조산식")):
            층.append(("원가 줄 %d 「%s」" % (k, 이름), 시트, 줄, "원가가중"))
    if 구["투자"]["유지규칙"] == "판매량연동":
        층.append(("유지 CAPEX(8번 17)", "8.CapEx", "17", "원가가중"))
    if 구["인건비"]["산정방식"] == "인원" and 구["인건비"]["인원경로"] == "물량연동":
        층.append(("인원(7번 10)", "7.Payroll", "10", "인원가중"))
    세는 = [x["번호"] for x in 구.목록("매출구분") if x.get("번호", 6) < 6 and x.get("경로") != "합계"]
    if not 층 or len(세는) < 2:
        return

    def 합(R, 시트, 행):
        v = [x for x in (_줄(R, 시트, 행)[i] for i in p.예측) if x is not None]
        return sum(v) if v else None
    빠짐, 영가중, 붙음, 밑영 = [], [], [], []
    for s in 세는:
        흔든가정, 흔든 = _판매량흔들기(가정, 시, 구분만=s)
        if not 흔든:
            continue
        try:
            R1 = _결과(흔든가정, 시)
        except Exception:                                    # noqa: BLE001
            continue
        m0, m1 = 합(R0, "4.Sales", 금액줄행[s]), 합(R1, "4.Sales", 금액줄행[s])
        if not m0 or m1 is None or abs(m1 / m0 - 1) < 0.001:
            continue
        for 이름, 시트, 줄, 키 in 층:
            a, b = 합(R0, 시트, 줄), 합(R1, 시트, 줄)
            if not a or b is None:
                continue
            if abs(b / a - 1) < 1e-6:
                표 = (가정.get("표") or {}).get(str(600 + 10 * s + 7)) or {}
                w = _수(표.get(키)) if isinstance(표, dict) else None
                밑값 = (구.매출구분(s) or {}).get("밑값") == "판매단가" and (구.매출구분(s) or {}).get("경로") == "수준"
                (밑영 if (w == 0 and 밑값) else 영가중 if w == 0 else 빠짐).append(
                    "%s → %s(%s %s)" % (_구분이름(가정, s), 이름, 키, "0" if w == 0 else "빔 · 미배선"))
            else:
                붙음.append("%s → %s %+.2f%%" % (_구분이름(가정, s), 이름, (b / a - 1) * 100))
    if 붙음:
        목록.append("  구분마다 판매량 +10%% — 물량 층이 따라 움직입니다: %s" % " · ".join(붙음[:6]))
    if 영가중:
        목록.append("  구분마다 판매량 +10%% — 가중 0 이라 안 움직이는 층(사람이 그 구분에 물량 원가 · 인원이 없다고 적었다): %s" % " · ".join(영가중[:6]))
    if 밑영:
        경보.append("  **기준 기간 매출이 없는 새 구분(밑값 = 판매단가)의 가중이 0 이라 그 매출이 물량 원가 · 인원 없이 들어옵니다(S2R1-02)** — %s.\n"
                    "    새 구분의 가중은 합 1 에 들지 않고 **더하는 몫**입니다: 기준 물량(표 6s7 판매량) × 기준 단위원가(인원) ÷ 기존 구분의 기준 기간\n"
                    "    물량 원가(인원). 신제품 · 신작 · 신사업에도 원가가 있으면 그 값을, 정말 없으면(라이선스 · 로열티) 0 과 그 근거를 적습니다"
                    % " · ".join(밑영[:6]))
    if 빠짐:
        경보.append("  **구분마다 판매량을 10%% 올려 보니 그 구분의 물량이 닿지 않는 층이 있습니다(S2-02)** — %s.\n"
                    "    그 구분의 매출은 늘었는데 원가 · 인원 · 유지 CAPEX 는 한 자리도 안 움직였습니다 — 물량이 공짜로 늡니다. 표 6s7 의 원가가중 ·\n"
                    "    인원가중(증가율 경로 구분도 두 칸을 적는다)을 적거나, 그 구분에 물량 원가가 정말 없으면 0 을 적고 근거를 남깁니다"
                    % " · ".join(빠짐[:6]))


def 판매량연동값(가정, 시=None):
    """㉖ 판매량 연동의 셈 — 판매량을 10% 올린 가정(`_판매량흔들기`)을 엔진으로 다시 돌려 예측 열 합계의 변동률을 층마다 잰다.
    자체검사 ㉖ 과 레터 장부 키 「가:대조:<블록>:판매량연동:<층>」 이 이 한 함수를 쓴다(레터 v27 6단계 A).

    → {"시", "흔든": [자리 글], "엔진오류": None | 글, "R0", "매출": 매출액 변동률 | None,
       "층": [{"키", "이름", "시트", "줄", "동인", "합": 기준 예측 열 합, "변": 변동률 | None, "작음": 매출의 0.5% 도 안 되는 층}]}
    층 키 — 원가<k>(원가 줄 k) · 인원 · 인건비 · 유지CAPEX(8번 17) · 감가상각비(8번 34)."""
    p = _판(가정)
    구 = p.구
    시 = 시 or _적용시나리오(가정)
    흔든가정, 흔든 = _판매량흔들기(가정, 시)
    낸 = {"시": 시, "흔든": 흔든, "엔진오류": None, "R0": None, "매출": None, "층": []}
    if not 흔든:
        return 낸
    try:
        R0, R1 = _결과(가정, 시), _결과(흔든가정, 시)
    except Exception as e:                                   # noqa: BLE001
        낸["엔진오류"] = "%s" % e
        return 낸

    def 합(R, 시트, 행):
        v = [x for x in (_줄(R, 시트, 행)[i] for i in p.예측) if x is not None]
        return sum(v) if v else None

    def 변(시트, 행):
        a, b = 합(R0, 시트, 행), 합(R1, 시트, 행)
        return None if (a is None or b is None or abs(a) < 1e-9) else (b / a - 1)

    낸["R0"] = R0
    낸["매출"] = 변("4.Sales", "54")
    매합 = 합(R0, "4.Sales", "54") or 0.0
    층 = []
    for k, x, 시트, 줄, 이름 in _원가줄들(가정):
        식 = x.get("산식") + ("" if x.get("보조산식") in (None, "없음") else " + 보조 %s" % x.get("보조산식"))
        층.append(("원가%d" % k, "원가 줄 %d 「%s」" % (k, 이름), 시트, 줄, "산식 %s" % 식))
    if 구["인건비"]["산정방식"] == "인원":
        층.append(("인원", "인원(7번 10)", "7.Payroll", "10", "인원경로 %s" % 구["인건비"]["인원경로"]))
    if 구["인건비"]["산정방식"] != "미분리":
        층.append(("인건비", "인건비 합계(7번 14)", "7.Payroll", "14", "산정방식 %s" % 구["인건비"]["산정방식"]))
    층.append(("유지CAPEX", "유지 CAPEX(8번 17)", "8.CapEx", "17", "유지규칙 %s" % 구["투자"]["유지규칙"]))
    층.append(("감가상각비", "감가상각비(8번 34)", "8.CapEx", "34", "상각방식 %s — 투자를 따른다" % 구["투자"]["상각방식"]))
    for 키, 이름, 시트, 줄, 동인 in 층:
        a = 합(R0, 시트, 줄)
        작음 = (not a) or (줄 not in ("10",) and bool(매합) and abs(a) < abs(매합) * 0.005)
        낸["층"].append({"키": 키, "이름": 이름, "시트": 시트, "줄": 줄, "동인": 동인, "합": a, "변": None if 작음 else 변(시트, 줄),
                        "작음": 작음})
    return 낸


def _판매량연동(가정, 오류, 경보, 목록):
    """㉖ 의 판매량 연동(I-55 · R-65 · R-153) — 판매량 +10% 의 엔진 결과를 층마다 견줘 오류 · 경보 · 목록에 싣는다."""
    시 = _적용시나리오(가정)
    값 = 판매량연동값(가정, 시)                             # 레터 v27 6단계 A — 셈은 이 함수 하나(레터 장부 키 「가:대조:…:판매량연동:…」)
    흔든 = 값["흔든"]
    if not 흔든:
        목록.append("  판매량 연동(I-55 · R-153) — 판매량을 세운 매출 구분이 없어 흔들지 않았습니다(기타 · 매출 증가율만)")
        return
    if 값["엔진오류"] is not None:
        목록.append("  판매량 연동 — 흔든 가정을 엔진이 못 계산했습니다: %s" % 값["엔진오류"])
        return
    R0 = 값["R0"]
    매변 = 값["매출"]
    목록.append("  판매량 연동 — %s 시나리오에서 %s 을(를) 10%% 올렸을 때 예측 열 합계의 변동률(적용 시나리오 · 엔진 다시 계산)"
                % (시, " · ".join(흔든)))
    if 매변 is None or abs(매변) < 0.001:
        오류.append("  **판매량을 10%% 올려도 매출액(4번 54)이 움직이지 않습니다(I-55).** 매출 산식이 판매량에 안 닿습니다 — "
                    "흔든 자리: %s. 매출 구분의 경로 · 판매량 산정(직접 · 능력)과 그 줄의 값을 보십시오" % " · ".join(흔든))
        return
    목록.append("    매출액(4번 54)                예측 열 합계 %+.2f%%" % (매변 * 100))
    안움직임 = []
    for 층 in 값["층"]:
        이름, 동인, v = 층["이름"], 층["동인"], 층["변"]
        if 층["작음"] or v is None:
            continue                                         # 없거나 매출의 0.5% 도 안 되는 층은 묻지 않는다
        목록.append("    %-28s 예측 열 합계 %+.2f%%  (탄성 %.2f · %s)" % (이름, v * 100, v / 매변, 동인))
        if abs(v) < 0.005:
            안움직임.append("%s — %s" % (이름, 동인))
    _구분마다흔들기(가정, 시, R0, 오류, 경보, 목록)              # S2-02 — 구분마다 따로 흔든다(전 구분 동시는 한 구분이 빠진 것을 못 본다)
    if 안움직임:
        경보.append(
            "  **판매량을 10%% 올려도 움직이지 않는 층 %d개(R-153).**\n"
            "%s\n"
            "    매출이 판매량으로 늘어도 이 층은 그대로입니다 — 고정비 · 자산 기준으로 둔 것이면 그 사유를, 판매량에 매어야 할\n"
            "    층이면 동인(원가 줄 산식 · 인원경로 물량연동 · 유지규칙)을 고칩니다. 사유는 검토 의견(`검토의견.R-153`)에 적습니다"
            % (len(안움직임), "\n".join("      · " + x for x in 안움직임)))


def 볼륨배선검사(가정, 라벨):
    """㉖ — **판매량이 늘면 무엇이 따라 느는가**(가정 점검 I-55 · R-65 · 도구 점검 R-153). 층마다 함축 탄성을 엔진 결과로 잰다.

    **판매량 연동(I-55 · R-65 · R-153 — W7a)** — 판매량(능력 경로면 라인 생산능력)을 10% 올린 가정을 엔진으로 다시 돌려
    (적용 시나리오, `_판매량흔들기`) 예측 열 합계의 변동률을 층마다 잰다.
      매출액이 안 움직이면 **오류**(I-55 — 매출 산식이 판매량에 안 닿는다).
      원가 줄 · 인원 · 인건비 · 유지 CAPEX · 감가상각 가운데 안 움직이는 층이 있으면 **경보 하나**(R-153 — 그렇게 둔 사유를
      검토 의견 `검토의견.R-153` 에 적으면 닫힌다). 층마다 선언한 동인(산식 · 인원경로 · 유지규칙)을 함께 적는다.
    판매단가 쪽(R-65 의 판매단가 10%)은 아래 ① 스프레드가 본다 — 단가가 오를 때 따라 오르는 것은 매출액 연동 원가뿐이다.

    매출을 쪼개 세워 놓고도 **아래 시트가 그것을 안 따라가면 쪼갠 값이 없다.**
    첫 예측 열 ↔ 마지막 예측 열을 견줘 **함축 탄성**을 낸다(연환산 — 잔여 기간 열도 같은 자).

        함축 탄성 = (그 항목의 연환산 증가율) ÷ (매출의 연환산 증가율)

    층 — 원가 줄 k(5 · 6번 금액 줄 — 산식별) · 인원(7번 10) · 유지 CAPEX(8번 17) · 감가상각비(8번 34).
    v13 은 동인을 구조에 **선언**한다(원가 줄의 산식 · 연동기준, 인건비.인원경로, 투자.유지규칙). 그래서
    탄성이 0 이나 1 에 붙은 것만으로 「안 정한 값」이라 하지 않고, 선언한 동인과 결과가 어긋나는 자리만 묻는다.

    경로 쪽 경보 둘(첫 예측 열 ↔ 마지막 예측 열의 함축 탄성 — 목록 「함축 탄성」 줄은 레터가 읽는다)
      ① **스프레드가 빠진다** — 판매단가가 움직이는데(증가율 경로 단가 · 수준 경로 판매단가 지수) 매출액비율 원가 줄이
         연동기준 = 매출액이고 매출의 5% 를 넘는다. 판가가 오르면 재료비도 같은 비율로 늘어 마진이 그대로다
         (실측 시험판: 물량 +2% · 단가 +4% 에서 원가율 매출 기저 78.42% ↔ 물량 기저 61.02% — 주당가치 두 배)
      ② **반기 열에 연간 금액**(148 · 152)을 넣은 함정
    (옛 ② 인원 끊김 · ③ 유지 CAPEX 끊김의 경로 탄성 판정은 위 R-153 이 판매량을 직접 흔들어 본다 — 두 번 묻지 않는다.)
    """
    오류, 경보, 목록 = [], [], []
    try:
        R = _결과(가정, "기준")
    except Exception as e:                                   # noqa: BLE001
        목록.append("  재료 없음 — 엔진을 못 불러 배선을 재지 못했습니다: %s" % e)
        return 오류, 경보, 목록
    p = _판(가정)
    구 = p.구
    첫, 끝 = p.첫, p.끝
    if 끝 <= 첫:
        목록.append("  재료 없음 — 예측 열이 둘 미만입니다")
        return 오류, 경보, 목록
    목록.append("  동인 — 원가 줄 %s · 인건비 %s(인원경로 %s) · 유지 CAPEX %s"
                % (" · ".join("%d %s" % (k, x.get("산식")) for k, x, *_ in _원가줄들(가정)) or "없음",
                   구["인건비"]["산정방식"], 구["인건비"]["인원경로"], 구["투자"]["유지규칙"]))

    def 연(시트, 행, i):
        v = _줄(R, 시트, 행)[i]
        return (v / p.년[i]) if (v is not None and p.년[i]) else None

    def 증가율(a, b, 해수):
        if a is None or b is None or a <= 0 or b <= 0 or 해수 <= 0:
            return None
        return (b / a) ** (1.0 / 해수) - 1

    해수 = sum(p.년[i] for i in p.예측 if 첫 < i <= 끝)
    매증 = 증가율(연("4.Sales", "54", 첫), 연("4.Sales", "54", 끝), 해수)
    if not 매증:
        목록.append("  재료 없음 — 매출이 안 자라거나 0 입니다(탄성을 못 잽니다)")
        return 오류, 경보, 목록
    목록.append("  매출 연 %+.2f%% (첫 예측 열 %s → 마지막 예측 열 %s, %.1f년)"
                % (매증 * 100, p.열글(첫), p.열글(끝), 해수))

    # 층마다 탄성 — 목록(레터 「매출 연동 구조」 문단이 「함축 탄성」 줄을 읽는다)
    층 = []
    for k, x, 시트, 줄, 이름 in _원가줄들(가정):
        층.append(("원가 줄 %d %s(%s)" % (k, 이름, x.get("산식")), 연(시트, 줄, 첫), 연(시트, 줄, 끝), ("원가", k, x)))
    if 구["인건비"]["산정방식"] == "인원":
        인 = _줄(R, "7.Payroll", "10")                      # 인원은 저량이라 길이를 안 벗긴다
        층.append(("인원(7번 10)", 인[첫], 인[끝], ("인원",)))
    층.append(("유지 CAPEX(8번 17)", 연("8.CapEx", "17", 첫), 연("8.CapEx", "17", 끝), ("유지",)))
    층.append(("감가상각비(8번 34)", 연("8.CapEx", "34", 첫), 연("8.CapEx", "34", 끝), ("상각",)))
    탄 = {}
    for 이름, a, b, 꼬리 in 층:
        증 = 증가율(a, b, 해수)
        t = (증 / 매증) if 증 is not None else None
        탄[꼬리[0] if 꼬리[0] != "원가" else ("원가", 꼬리[1])] = t
        목록.append("    %-28s 연 %s  →  **함축 탄성 %s**"
                    % (이름, ("%+.2f%%" % (증 * 100)) if 증 is not None else "   n/a",
                       ("%.2f" % t) if t is not None else "n/a"))

    # ① 스프레드 — 판매단가가 움직이는데 매출액 연동 원가 줄이 크다
    움 = _단가움직임(가정)
    매첫 = _줄(R, "4.Sales", "54")[첫] or 0.0
    붙은 = []
    if 움 is not None and 움 > 0.0005 and 매첫:
        for k, x, 시트, 줄, 이름 in _원가줄들(가정):
            if x.get("산식") != "매출액비율" or x.get("연동기준") != "매출액":
                continue
            몫 = (_줄(R, 시트, 줄)[첫] or 0.0) / 매첫
            if 몫 > 0.05:
                근 = _근거적힘(가정, 원가비율가정[k])
                붙은.append((k, 이름, 몫, 근))
    if 붙은:
        글 = ("  **판매단가가 움직이는데(최대 %s) 매출액에 연동한 원가 줄이 있습니다 — 스프레드가 빠집니다.**\n"
              "%s\n"
              "    매출액비율 줄에 **매출액**을 곱하면, 단가가 올라 매출이 늘 때 그 원가도 같은 비율로 늡니다.\n"
              "    판가가 올라도 투입량은 그대로여야 하고 **마진이 개선되어야 합니다.**\n"
              "    **그 줄의 연동기준을 「판매량」(불변가격 매출액)으로 바꾸거나 산식을 물량단위원가로** 세우십시오.\n"
              "    실측(시험판): 물량 +2%% · 단가 +4%% 로 갈라 세우니 원가율이 매출 기저 78.42%% ↔ 물량 기저 61.02%%\n"
              "    (마지막 예측 해) — **주당가치가 122,191 → 244,402원. 이 한 칸이 값을 두 배로 가릅니다.**\n"
              "    투입 단가도 같이 오르는 사업(원자재를 사서 파는 유통 · 위탁 생산 등)이면 매출액 연동이 맞습니다 — **그렇다고 근거 칸에 적고\n"
              "    검토의견으로 이 경보를 겨눠 닫으십시오**: 검토의견.<아무 키> = {\"의견\": …, \"근거\": …(열 자 이상), "
              "\"닫을\": [\"스프레드가 빠집니다\"], \"검사\": \"㉖\"}(근거 칸만으로는 닫히지 않습니다 · 1.1.10)"
              % (_퍼(움), "\n".join("      · 원가 줄 %d 「%s」 — 첫 예측 열 매출의 %.1f%%%s"
                                     % (k, 이름, 몫 * 100, (" (근거: 「%s」)" % 근[0][:40]) if 근 else "")
                                     for k, 이름, 몫, 근 in 붙은)))
        경보.append(글)                      # 근거 글은 줄마다 병기만 한다 — 등급은 안 내린다(옛 ①-b 와 같은 결)

    # 판매량 연동(I-55 · R-65 · R-153) — 판매량(능력)을 10% 올린 엔진 결과와 견준다
    _판매량연동(가정, 오류, 경보, 목록)

    # S2-11 — 4번 193 · 194 는 능력 경로에서도 **산출**(능력 × 가동률 × 수율)을 센다. 인원이 물량연동이고 능력 구분의 가동률이 예측 열에서
    # 움직이면 그만큼 인원이 따라 움직인다(감산하면 인원이 준다 — 설비 집약 회사의 인원은 대개 능력을 따른다). 판정이 아니라 알림이다
    if 구["인건비"]["인원경로"] == "물량연동":
        움직인 = []
        for x in 구.목록("매출구분"):
            s = x.get("번호", 6)
            if s < 6 and x.get("경로") == "수준" and x.get("판매량산정") == "능력":
                for 시 in 시나리오목록:
                    가 = [v for v in (p.A(273 + 25 * (s - 1), 시)[i] for i in p.예측) if v is not None]
                    if 가 and max(가) - min(가) > 1e-9:
                        움직인.append("%s %s %.0f~%.0f%%" % (_구분이름(가정, s), 시, min(가) * 100, max(가) * 100))
                        break
        if 움직인:
            목록.append("  인원 물량연동 — 4번 193 · 194 는 산출 지수입니다(능력 × 가동률 × 수율). 가동률이 예측 열에서 움직이는 구분(%s)은 그만큼 "
                        "인원이 따라 움직입니다 — 인원이 능력(라인 수)을 따르는 회사면 감산 연도에 인원이 줄어 비관이 덜 아파집니다. 그렇게 둔 사유를 "
                        "인원 탄력성(A-521) 근거 칸에 적습니다" % " · ".join(움직인[:4]))

    # 반기 열에 연간 금액을 넣었나 — **금액 행만의 함정**
    # 12번의 금액 행(148 유지 CAPEX · 152 처분)은 **그 기간에 나가는 돈**이라 반기 열에는
    # 반년치가 들어가야 한다. 연간과 같은 값을 넣으면 **연환산하면 두 배**가 되어
    # 첫 해 투자가 부풀고, 그 뒤로 줄어드는 것처럼 보인다.
    # 실측(한화오션): 「2026 잔여」(반기)에 7,000억을 넣어 연환산 1.4조가 됐고,
    # 유지 CapEx 탄성이 **−9.46** 으로 나왔다 — 매출은 느는데 투자가 반토막.
    # **비율 행은 해당 없다** — 비율은 기간과 무관하다. 유지규칙이 직접이 아니면 148 은 읽지 않는다.
    금액행 = [("152", "유형자산 처분")]
    if 구["투자"]["유지규칙"] == "직접":
        금액행.insert(0, ("148", "유형자산의 취득(유지 CAPEX)"))
    의심 = []
    L첫 = p.년[첫]
    if L첫 and L첫 < 0.9 and 첫 + 1 < p.n:
        for 행, 이름 in 금액행:
            줄 = p.A(행, "기준")
            a, b = 줄[첫], 줄[첫 + 1]
            L다 = p.년[첫 + 1]
            if a and b and L다 and L다 >= 0.9 and abs(a / b - 1) < 0.10:
                의심.append((행, 이름, a, b, L첫))
    if 의심:
        경보.append(
            "  **반기 열(길이 %.1f)에 연간과 같은 금액이 들어 있습니다 — %d행.**\n"
            "%s\n"
            "    12번의 **금액 행은 「그 기간에 나가는 돈」**입니다. 반기 열에는 반년치가\n"
            "    들어가야 하는데 연간과 같은 값이면 **연환산하면 두 배**가 됩니다.\n"
            "    첫 해 투자가 부풀고, 그 뒤로는 줄어드는 것처럼 보여 **탄성이 음수로**\n"
            "    나옵니다. **비율 행은 해당 없습니다** — 비율은 기간과 무관합니다.\n"
            "    정말 반년에 연간치를 쓰는 계획이면 **그렇다고 근거 칸에 적으십시오**"
            % (의심[0][4], len(의심),
               "\n".join("      · %s행 %s — 반기 %s · 다음 연간 %s"
                         % (r, nm, _금액(a), _금액(b)) for r, nm, a, b, _L in 의심)))
    return 오류, 경보, 목록


def 손익경계값(가정, R=None):
    """㉗ 의 셈 — 마지막 실적 열 → 첫 예측 열의 영업이익률 · 원가율 · 판관율과 문턱(이 회사 실적 열 사이 최대 변동폭, 경계에 부분 연도가
    있으면 두 배). 자체검사 ㉗ 과 레터 장부 키 「가:대조:<블록>:손익경계:…」(`추정근거.대조풀기`)가 이 한 함수를 쓴다(레터 v27 6단계 A).
    R 은 적용 시나리오의 엔진 결과(없으면 돌린다).

    → {"재료": None | "원천" | "예측", "앞i", "뒤i", "앞열", "뒤열", "영업이익률": (앞, 뒤), "원가율": (앞 | None, 뒤), "판관율": (앞 | None, 뒤),
       "문턱": 최대 변동폭(부분 연도면 두 배) | None, "부분연도": 참 · 거짓, "쟀": [(i, 실적 영업이익률)], "매예"}"""
    p = _판(가정)
    첫 = p.첫
    R = R if R is not None else _결과(가정, _적용시나리오(가정))
    매실 = p.H(원천매출행)
    원실 = p.H(원천매출원가행)
    영실 = _영업이익줄(가정)
    쟀 = [(i, 영실[i] / 매실[i]) for i in p.실적 if 매실[i] and 영실[i] is not None]
    낸 = {"재료": None, "앞i": None, "뒤i": 첫, "앞열": None, "뒤열": p.ID[첫], "영업이익률": (None, None), "원가율": (None, None),
         "판관율": (None, None), "문턱": None, "부분연도": False, "쟀": 쟀, "매예": None}
    if not 쟀:
        낸["재료"] = "원천"
        return 낸
    끝열, 실마진 = 쟀[-1]
    낸["앞i"], 낸["앞열"] = 끝열, p.ID[끝열]
    매예 = _줄(R, "4.Sales", "54")[첫]
    원예 = _줄(R, "5.COGS", "17")[첫]
    판예 = _줄(R, "6.SG&A", "16")[첫]
    if not 매예 or 원예 is None or 판예 is None:
        낸["재료"] = "예측"
        return 낸
    예마진 = (매예 - 원예 - 판예) / 매예
    예원가율, 예판관율 = 원예 / 매예, 판예 / 매예
    실원가율 = (원실[끝열] / 매실[끝열]) if (원실[끝열] and 매실[끝열]) else None
    실판관율 = (1 - 실마진 - 실원가율) if 실원가율 is not None else None
    변동 = [abs(쟀[k][1] - 쟀[k - 1][1]) for k in range(1, len(쟀))]
    부분 = abs(p.년[끝열] - 1.0) > 0.05 or abs(p.년[첫] - 1.0) > 0.05
    자 = (max(변동) * (2 if 부분 else 1)) if 변동 else None
    낸.update({"영업이익률": (실마진, 예마진), "원가율": (실원가율, 예원가율), "판관율": (실판관율, 예판관율), "문턱": 자,
              "부분연도": 부분, "매예": 매예})
    return 낸


def 손익이음매검사(가정, 라벨):
    """㉗ — **첫 예측 열이 마지막 실적 열과 이어지나.** 원가·판관·마진을 각각 본다.

    운전자본 이음매는 ㉑ 이 본다. **손익 이음매는 아무도 안 봤다** — 그런데 이 프로젝트에서
    같은 자리를 **세 번** 손으로 잡았다.

      · 씨젠 — 원천 17·18행(유형·무형자산)이 비어 8번 CapEx 의 기초 자산이 0 이었다.
        총 상각이 매출의 **0.5%**(실측 12.40%)로 잡혀 **첫 예측 열 마진이 실적과 12%p** 어긋났다
      · 한일시멘트 ① — 인건비를 켜고 인원·급여를 안 채워 인건비 6.28%p 가 통째로 빠졌다.
        첫 예측 열 **17.74%** vs 실적 11.84%
      · 한일시멘트 ② — 원가 스택을 **2025 성격별 주석**으로 세웠는데 마지막 실적 열이
        **2026 반기**라 원가율이 이미 개선돼 있었다. 첫 예측 열 8.48% vs 실적 11.84%

    **합계 검산으로는 절대 안 잡힌다.** 스택의 합이 그 해 원가와 정확히 맞아도, 그 해가
    마지막 실적 열이 아니면 이음매가 벌어진다. **첫 예측 열이 어긋나면 그 아래 열 전부가
    어긋나고, 종착 마진도 거기서 나온 값이라 영구가치가 통째로 틀린다.**

    **문턱은 이 회사 자신의 실적 변동폭에서 만든다.** 고정 %를 안 쓴다 — 순환 산업은
    해마다 마진이 크게 움직이고(한일시멘트 실적 3열이 15.58 → 9.32 → 11.84%),
    성숙 산업은 거의 안 움직인다. **실적 열 사이의 최대 변동폭**이 그 회사의 자다
    (실적 열은 가정의 `기간` 이 정한다 — FY 실적 + 누계 실적).
        낙차 > 최대 변동폭        → 오류 (실적에서 겪은 적 없는 점프다)
        낙차 > 최대 변동폭 ÷ 2    → 경보
    실적 열이 둘 미만이면 자를 못 만드니 목록으로만 적는다.

    첫 예측 열 손익은 엔진 결과의 합계 줄로 읽는다 — 매출액(4번 54) · 매출원가 합계(5번 17 — 원가 줄 · 노무비 ·
    감가상각 · 재고 변동 · 판관비 배분을 다 쌓은 값) · 판매비와관리비 합계(6번 16).

    **막지 않는 경우가 있다** — 첫 예측 열이 반기이고 마지막 실적 열이 연간이면 계절성이
    섞인다. 그래도 마진은 비율이라 대개 이어진다. 안 이어지면 그 사실을 적는 자리다.
    """
    오류, 경보, 목록 = [], [], []
    try:
        R = _결과(가정, _적용시나리오(가정))
    except Exception as e:                                   # noqa: BLE001
        목록.append("  재료 없음 — 엔진을 못 불러 실적·추정 경계를 확인하지 못했습니다: %s" % e)
        return 오류, 경보, 목록
    p = _판(가정)
    첫 = p.첫

    값 = 손익경계값(가정, R)                                 # 레터 v27 6단계 A — 셈은 이 함수 하나(레터 장부 키 「가:대조:…:손익경계:…」 가 같이 읽는다)
    if 값["재료"] == "원천":
        목록.append("  재료 없음 — 원천 13번 %s·%s행으로 실적 마진을 못 냈습니다"
                    % (원천매출행, 원천영업이익행))
        return 오류, 경보, 목록
    if 값["재료"] == "예측":
        목록.append("  재료 없음 — 첫 예측 열 손익을 못 읽었습니다")
        return 오류, 경보, 목록
    끝열, 쟀 = 값["앞i"], 값["쟀"]
    실마진, 예마진 = 값["영업이익률"]
    매예 = 값["매예"]
    실원가율, 예원가율 = 값["원가율"]
    실판관율, 예판관율 = 값["판관율"]
    실이름, 예이름 = p.열글(끝열), p.열글(첫)

    목록.append("  %s → %s" % (실이름, 예이름))
    목록.append("    영업이익률  %7.2f%% → %7.2f%%   낙차 %+.2f%%p"
                % (실마진 * 100, 예마진 * 100, (예마진 - 실마진) * 100))
    if 실원가율 is not None:
        목록.append("    원가율      %7.2f%% → %7.2f%%   낙차 %+.2f%%p"
                    % (실원가율 * 100, 예원가율 * 100, (예원가율 - 실원가율) * 100))
        목록.append("    판관율      %7.2f%% → %7.2f%%   낙차 %+.2f%%p"
                    % (실판관율 * 100, 예판관율 * 100, (예판관율 - 실판관율) * 100))

    낙차 = abs(예마진 - 실마진)
    변동 = [abs(쟀[k][1] - 쟀[k - 1][1]) for k in range(1, len(쟀))]
    if not 변동:
        목록.append("    실적 열이 하나뿐이라 문턱을 못 만듭니다 — 낙차만 적습니다")
        return 오류, 경보, 목록
    자 = max(변동)
    # **경계의 어느 한쪽이 부분 연도면 문턱을 두 배로 늦춘다** — 실측(ABNB): 마지막
    # 실적 열이 1H(성수기 앞)이고 첫 예측 열이 2H(성수기)라, 계절성만으로 OPM 이
    # 7%p 벌어졌다. 실적 열들(대개 연간)의 변동폭은 계절 진폭을 모르는 자다.
    # 1H↔2H·반기↔연간 어느 쪽이든 달력의 병이지 스택의 병이 아니니 자를 늘려
    # 위양성을 줄인다 — 실제 스택 오류는 대개 문턱의 몇 배로 벌어져 그래도 잡힌다.
    if abs(p.년[끝열] - 1.0) > 0.05 or abs(p.년[첫] - 1.0) > 0.05:
        자 *= 2
        목록.append("    경계에 부분 연도가 있습니다(실적 열 길이 %.2f · 예측 열 길이 %.2f) — "
                    "계절성이 섞이므로 문턱을 두 배로 늦춥니다" % (p.년[끝열], p.년[첫]))
    목록.append("    문턱 — 이 회사 실적 열 사이의 최대 변동폭 %.2f%%p (그 절반 %.2f%%p)"
                % (자 * 100, 자 * 50))

    if 낙차 <= 자 / 2:
        return 오류, 경보, 목록

    # 원인 후보를 짚는다
    단서 = []
    if p.구["인건비"]["산정방식"] != "미분리" and not _줄(R, "5.COGS", "11")[첫]:
        # 매출원가 배분율(134 → 7번 19)이 0 이면 원가 인건을 일부러 원가 줄에 뭉친 판이다 — 오진하지 않는다.
        # 실측(씨젠): 연구개발비가 성격별에 흩어져 원가 인건을 못 갈라 134=0 으로 두었는데
        # 「인원·급여를 채웠는지 보라」는 엉뚱한 단서가 떴다.
        if _줄(R, "7.Payroll", "19")[첫] == 0:
            단서.append("5번 노무비(11)가 0 인 것은 **매출원가 배분율(134)이 0** 이라서다 — 원가 인건을 "
                        "원가 줄에 뭉친 판이면 의도한 것이다. 낙차의 원인은 다른 데 있다")
        else:
            단서.append("**5번 노무비(11)가 0 입니다** — 인건비 합계(7번 14)와 인원·급여 가정을 채웠는지 보십시오(㉔-b)")
    상각예 = (_줄(R, "5.COGS", "12")[첫] or 0) + (_줄(R, "6.SG&A", "13")[첫] or 0)
    if 매예 and 상각예 / 매예 < 0.005:
        단서.append("**상각이 매출의 %.2f%% 뿐입니다** — 원천 17·18행(유형·무형자산)이나 빈티지의 "
                    "기초 취득분(표 T4)이 비면 8번 CapEx 의 기초 자산이 0 이라 그 해 CapEx 에서만 상각이 나옵니다"
                    % (상각예 / 매예 * 100))
    if 실원가율 is not None and abs(예원가율 - 실원가율) > abs(예판관율 - 실판관율):
        단서.append("**낙차의 대부분이 원가율입니다** — 원가 줄을 어느 해 주석으로 세웠는지 "
                    "보십시오. 마지막 실적 열과 다른 해면 그 사이의 개선·악화가 통째로 빠집니다." + chr(10) +
                    "      흔한 원인 하나 — **실적 원가율(상각 포함)을 매출액비율 원가 줄(80 …)에 그대로 넣은 경우**입니다. "
                    "그 위에 8번의 감가상각이" + chr(10) +
                    "      따로 얹히므로 원가 줄은 **상각을 뺀** 원가율이어야 합니다. 실측(HMM): 상각 포함 "
                    "85% 를 그대로 넣어 상각이" + chr(10) +
                    "      두 번 실렸고 마지막 예측 해가 −11% 적자로 무너졌습니다")
    else:
        단서.append("**낙차의 대부분이 판관율입니다** — 판관 원가 줄(5~7)의 기준 해와 산식(물가연동 · 매출액비율)을 "
                    "보십시오")

    글 = (
        "  **실적과 추정치의 경계에서 OPM 이 %.2f%%p 불연속합니다** (%s %.2f%% → %s %.2f%%).PLACE_N"
        "%sPLACE_N"
        "    **첫 예측 열이 실적과 안 이어지면 그 아래 열 전부가 어긋난 것**이고,PLACE_N"
        "    종착 마진도 거기서 나온 값이라 **영구가치가 통째로 틀립니다.**PLACE_N"
        "    **합계 검산으로는 안 잡힙니다** — 스택의 합이 그 해 원가와 정확히 맞아도,PLACE_N"
        "    그 해가 마지막 실적 열이 아니면 경계에서 불연속이 생깁니다.PLACE_N"
        "    문턱은 이 회사 자신의 실적 변동폭(%.2f%%p)에서 만들었습니다.PLACE_N"
        "    **계절성이나 실제 구조 변화라면 그렇다고 근거 칸에 적으십시오**"
        % (낙차 * 100, 실이름, 실마진 * 100, 예이름, 예마진 * 100,
           "PLACE_N".join("      · " + x for x in 단서), 자 * 100)).replace("PLACE_N", chr(10))
    # 판정은 15번 R-104(적용 시나리오 · 10%p) — 이 회사의 자(실적 변동폭)로 잰 낙차와 원인 단서는 목록으로 싣는다(W7a 나눔)
    if 낙차 <= 0.10:
        글 += chr(10) + "    (이 회사의 자로는 큰 낙차지만 15번 R-104 의 문턱 10%p 안입니다)"
    목록.append(_넘김(글, "R-104"))
    return 오류, 경보, 목록


def 신규투자비중값(가정, R):
    """㉘ ③ (S5-17) 의 셈 — 예측 열마다 신규 편입(8번 17 취득 + 18 대체) ÷ 기초 유형자산(8번 16) ÷ 기간(년). 자체검사 ㉘ 과 레터 장부 키
    「가:대조:설비:신규비중:<열>」 이 이 한 함수를 쓴다(레터 v27 6단계 A). → [(열 자리 i, 비율)] — 기초 유형자산이 없는 열은 뺀다."""
    p = _판(가정)
    x16, x17, x18 = (_줄(R, "8.CapEx", k) for k in ("16", "17", "18"))
    return [(i, ((x17[i] or 0.0) + (x18[i] or 0.0)) / x16[i] / (p.년[i] or 1.0)) for i in p.예측 if x16[i]]


def 상각률검사(가정, 라벨):
    """㉘ — **156행에 `1 ÷ 내용연수` 를 넣었나.**

    엔진의 밑은 취득원가가 아니라 **기초 순장부금액**이다.
        감가상각 = −(기초 순장부 + 당해 취득/2) × 상각률 × 기간길이
    회사가 **정액법**을 써도 자산이 여러 빈티지로 섞여 순장부금액이 취득원가의 절반쯤이라,
    관측 상각률(감가상각비 ÷ 기초 순장부)은 **`1÷내용연수` 의 약 두 배**다.
        내용연수 5년 → 33.3% · 10년 → 18.2% · 20년 → 9.5%  (꾸준히 투자하는 정상상태)

    **`1÷내용연수` 를 넣으면 상각이 절반만 잡히고 영업이익이 그만큼 부푼다.**
    조문이 오래도록 「누적 CAPEX ÷ 내용연수」로 적혀 있어 그대로 따르면 반드시 이 사고가 난다.

    **자를 이 회사 자신에게서 만든다.** 원천 77(유형 감가상각비)·80(유형 취득)·17(유형자산)로
    실적 열의 관측 상각률을 엔진과 **같은 산식**으로 재고, 156행과 견준다.
        관측_i = 원천77_i ÷ (원천17_(i−1) + 원천80_i ÷ 2)
    실적 열이 둘 미만이거나 재료가 비면 목록으로만 적는다 — 없는 값을 지어내지 않는다.

    무형(164행 ↔ 원천 78·81·18)도 같은 자로 본다.
    """
    오류, 경보, 목록 = [], [], []
    p = _판(가정)
    첫 = p.첫
    실 = list(p.실적)                     # 실적 열의 자리 — 가정의 기간이 정한다(FY 실적 + 누계 실적)

    def L(k):
        v = p.년[실[k]]
        return v if v and v > 0 else 1.0

    def 줄(행):
        """실적 열만 — 실적 열 차례(0 = 가장 오래된 실적 열)의 목록."""
        v = p.H(행)
        return [v[i] for i in 실]

    def 한벌(자산행, 상각행, 취득행, 가정행, 이름, 보탤자산행=None):
        # **엔진이 곱하는 밑값과 같은 분모로 잰다.** 리스를 금융으로 본 회차
        # (`리스부채포함="포함"`)에서 엔진의 상각 밑값은 **유형 + 사용권**이다 —
        # 여기서 유형만 재면 검사가 엔진과 다른 자를 들고 있게 된다.
        # 실측(CJ프레시웨이): 검사는 「관측 6.30%」라 하고 156행은 11.52%(유형+사용권
        # 분모로 잰 값)라 경보가 울었는데, **둘 다 자기 자로는 맞았다.**
        자산, 상각, 취득 = 줄(자산행), 줄(상각행), 줄(취득행)
        덜잰다 = False
        if 보탤자산행 and any(줄(보탤자산행)):
            보 = 줄(보탤자산행)
            자산 = [((_수(a) or 0.0) + (_수(b) or 0.0)) if (a is not None or b is not None)
                   else None for a, b in zip(자산, 보)]
            # S10-14 — 분자(원천 77)에 사용권 상각이 들었는지는 성격별 감가상각비(원천 579 — 유형 · 사용권 · 무형 모두)와 대사해 가린다:
            #   77 ≈ 579 − 78(무형) (±5%) 이면 사용권 상각이 들었다(그때는 같은 자 — 판정한다). 안 맞으면 분모만 사용권을 더해 관측률이 아래로
            #   치우친다 — 그 사실을 밝히고 판정을 목록으로 낮춘다(원천근거 문구로 가리지 않는다)
            상579, 무78 = 줄(579), 줄(78)
            든 = [i for i, (a, b, m) in enumerate(zip(상각, 상579, 무78))
                 if _수(a) and _수(b) and b > 0 and abs(abs(a) - (abs(b) - abs(_수(m) or 0.0))) <= 0.05 * abs(b)]
            덜잰다 = not 든
            이름 = "%s+사용권자산" % 이름
            if 든:
                목록.append("  %s — 원천 77 이 579 − 78 과 맞는다(%d개 실적 열 — 사용권 상각 포함 · 같은 자로 판정)" % (이름, len(든)))
        관측 = []
        for i in range(1, len(실)):
            기초 = 자산[i - 1]
            if not 기초 or 기초 <= 0 or 상각[i] is None:
                continue
            밑 = 기초 + (_수(취득[i]) or 0.0) / 2
            if 밑 <= 0:
                continue
            # **연환산한다.** 마지막 실적 열이 반기면 상각도 반년치라 그대로 재면 반토막이 난다.
            # 156행은 「연 상각률」이므로 같은 자로 만들어 견줘야 한다.
            관측.append((i, abs(상각[i]) / 밑 / L(i)))
        if not 관측:
            목록.append("  %s — 재료 없음(원천 %s·%s·%s). 관측 상각률을 못 쟀습니다"
                        % (이름, 자산행, 상각행, 취득행))
            return
        # **밑이 급증한 직후에는 절반꼴 판정을 하지 않는다** — 실측(LLY): 무형이
        # 6.5B→18.1B(인수)로 뛴 직후라 관측 분모가 옛 밑이었고, 새 밑 기준의 낮은
        # 상각률이 「1/내용연수 꼴」로 오판됐다. 최근 밑 ÷ 직전 밑 > 1.5 면 관측만
        # 적고 판정은 보류한다.
        급증보류 = False
        _n = len(자산)
        _마지막밑 = next((자산[i] for i in (_n - 1, _n - 2) if 0 <= i < _n and 자산[i]), None)
        _직전밑 = next((자산[i] for i in (_n - 2, _n - 3) if 0 <= i < _n and 자산[i]), None)
        if (_마지막밑 and _직전밑 and _직전밑 > 0 and _마지막밑 / _직전밑 > 1.5):
            목록.append("  %s — **밑이 급증했습니다**(%.1f배 — 인수·대규모 취득). "
                        "관측 분모가 옛 밑이라 절반꼴 판정을 보류합니다. 새 자산의 "
                        "상각 개시를 근거 칸에 적으십시오" % (이름, _마지막밑 / _직전밑))
            급증보류 = True
        적은것 = []
        for 시 in 시나리오목록:
            v = p.A(가정행, 시)[첫]
            if v is not None:
                적은것.append((시, v))
        평균 = sum(x[1] for x in 관측) / len(관측)
        목록.append("  %s — 관측 상각률(연환산) %s (평균 %.2f%%)"
                    % (이름, " · ".join("%s %.2f%%" % (p.열글(실[i]), r * 100) for i, r in 관측),
                       평균 * 100))
        if not 적은것:
            목록.append("    %s행이 비어 있습니다 — 상각이 0 으로 들어갑니다" % 가정행)
            return
        목록.append("    %s행 %s"
                    % (가정행, " · ".join("%s %.2f%%" % (s, v * 100) for s, v in 적은것)))
        if 덜잰다:
            목록.append(
                "    **위 관측률은 아래로 치우쳐 있습니다** — 리스를 금융으로 보아 밑값에 "
                "사용권자산을 더했는데(엔진도 같은 밑값을 씁니다), 분자인 상각(원천 %s행)이 "
                "성격별 감가상각비(원천 579) − 무형상각(78)과 맞지 않아 **사용권 상각이 빠진 것으로 봅니다**(579 ↔ 77 대사 — S10-14). "
                "%s행이 위 값보다 높은 것은 정상일 수 있으니 **그 값을 어느 분모로 쟀는지 "
                "근거 칸에 적어 두십시오** — 여기서는 판정하지 않습니다"
                % (상각행, 가정행))
            return
        if 급증보류:
            return
        if not 평균 or 평균 <= 0:
            # **관측 상각비가 0 이면 잴 자가 없다.** 옛 판은 배수를 0 으로 두고 그대로
            # 내려가 `1/배` 에서 죽었다(ZeroDivisionError). 실측(마이크론): 10-Q 현금흐름표가
            # 감가와 무형상각을 한 줄로 주어 78행(무형상각)이 0 이었다 — 미국 회차의 흔한 꼴이다.
            # **통과가 아니라 「확인 못 함」으로 적는다.**
            목록.append("  %s행(%s 상각률) — 관측 상각비가 0 이라 판정하지 않습니다. "
                        "**통과가 아니라 확인 못 함입니다** — 원천 %d행이 비었는지, "
                        "아니면 다른 행에 합산돼 있는지 근거 칸에 적으십시오"
                        % (가정행, 이름, 상각행))
            return
        for 시, v in 적은것:
            if v <= 0:
                continue
            배 = v / 평균 if 평균 > 0 else 0.0
            if 0.35 <= 배 <= 0.65:
                오류.append(
                    "  **%s %s행(%s 상각률)이 관측의 %.0f%% 입니다 — `1÷내용연수` 를 넣은 꼴입니다.**PLACE_N"
                    "    적은 값 **%.2f%%** vs 이 회사 실적에서 관측된 **%.2f%%**.PLACE_N"
                    "    **엔진의 밑은 취득원가가 아니라 기초 순장부금액입니다.**PLACE_N"
                    "    회사가 정액법을 써도 자산이 여러 빈티지로 섞여 순장부가 취득원가의 절반쯤이라,PLACE_N"
                    "    관측 상각률은 `1÷내용연수` 의 **약 두 배**입니다(10년 → 18.2%%).PLACE_N"
                    "    이대로 두면 **상각이 절반만 잡히고 영업이익이 그만큼 부풉니다.**PLACE_N"
                    "    주석의 내용연수는 값을 정하는 데가 아니라 **관측값이 말이 되는지 대 보는 데** 씁니다"
                    % (시, 가정행, 이름, 배 * 100, v * 100, 평균 * 100))
            elif 배 < 0.35 or 배 > 2.2:
                경보.append(
                    "  **%s %s행(%s 상각률) %.2f%% 가 관측 %.2f%% 와 %.1f 배 벌어집니다.**PLACE_N"
                    "    자산 나이가 한쪽으로 몰렸거나 상각 정책이 바뀐 것이면 그렇다고 적으십시오"
                    % (시, 가정행, 이름, v * 100, 평균 * 100, 배 if 배 > 1 else 1 / 배))

    _리스 = ((가정.get("스위치") or {}).get("리스부채포함", "포함") != "제외")
    # 156 · 164 는 상각률 갈래에서만 읽는다 — 빈티지(구조.투자.상각방식)는 기초 취득분 · 편입분을 내용연수로 상각하고
    # (표 T4 — 순장부금액 검산은 R-123), 무형상각 = 금액은 연 금액(856)을 쓴다
    if p.구["투자"]["상각방식"] == "상각률":
        한벌(17, 77, 80, "156", "유형자산", 보탤자산행=(19 if _리스 else None))
    else:
        목록.append("  유형자산 — 상각방식 = %s 이라 156행(상각률)을 읽지 않습니다(기초 취득분 · 편입분 감가상각 — 표 T4 · "
                    "내용연수 80g)" % p.구["투자"]["상각방식"])
    if p.구["투자"]["무형상각"] == "상각률":
        한벌(18, 78, 81, "164", "무형자산")
    else:
        목록.append("  무형자산 — 무형상각 = %s 이라 164행(상각률)을 읽지 않습니다(연 금액 856)" % p.구["투자"]["무형상각"])

    # S5-17 — ③ 상각률 판은 신규 투자에도 혼합 관측률을 바로 건다: 예측 열의 편입(17 + 18) ÷ 기초 유형자산(16)이 30% 를 넘으면 상각을 앞당긴다 — 빈티지
    #          ④ 영구상각 = 추세(정상유지투자가 아닌 판)는 영구기간 상각(19)과 유지 투자(17)를 다른 칸에서 따로 정한다 — 유지 CAPEX ÷ 상각이 0.9 아래면
    #             영구기간 상각이 유지 투자보다 커 이익이 영구히 깎인다(R-112 는 정상유지투자 판만 본다)
    try:
        R8 = _결과(가정, "기준")
        x16, x17, x18, x19 = (_줄(R8, "8.CapEx", k) for k in ("16", "17", "18", "19"))
        if p.구["투자"]["상각방식"] == "상각률":
            큰 = 신규투자비중값(가정, R8)                       # 레터 v27 6단계 A — 셈은 이 함수 하나(레터 장부 키 「가:대조:설비:신규비중:<열>」)
            큰 = [(i, r) for i, r in 큰 if r > 0.30]
            if 큰:
                경보.append("  **상각률 판인데 신규 투자가 기초 유형자산의 30%% 를 넘는 열이 있습니다** — %s.PLACE_N"
                            "    상각률(156)은 새 투자에도 혼합 관측률을 바로 걸어 상각을 앞당기고(정상상태의 두 배 근사), 성장 회사는 그 값이 영구기간 이익을PLACE_N"
                            "    깎습니다. 빈티지(자산군 기초 취득분 + 신규 편입 정액 — 내용연수 80g)를 보십시오(S5-17)"
                            % " · ".join("%s %.0f%%" % (p.열글(i), r * 100) for i, r in 큰[:4]))
        if p.구["영구가치"]["영구상각"] != "정상유지투자" and p.영구 is not None and x19[p.영구]:
            비 = (x17[p.영구] or 0.0) / x19[p.영구]
            if 비 < 0.9:
                경보.append("  **영구기간 열의 유지 CAPEX(8번 17) %s 가 감가상각비(19) %s 의 %.0f%% 입니다** — 영구상각 = 추세라 둘을 다른 칸에서 따로 정했고,PLACE_N"
                            "    상각이 유지 투자보다 커 영구기간 이익이 영구히 깎입니다. 영구상각 = 정상유지투자로 묶거나(601) 156 · 유지 규칙을 맞추십시오(S5-17)"
                            % (_금액(x17[p.영구]), _금액(x19[p.영구]), 비 * 100))
            else:
                목록.append("  영구기간 유지 CAPEX ÷ 감가상각비 = %.2f(추세 판 — 0.9 이상)" % 비)
    except Exception as e:                                   # noqa: BLE001
        목록.append("  상각 판 · 영구기간 대조 — 계산 실패: %s" % e)

    목록.append("  **투자를 크게 줄인 판에서는 자산이 영원히 안 닳습니다** — 밑이 순장부금액이라")
    목록.append("    CapEx 를 유지투자 아래로 내리면 상각이 기하급수로 줄 뿐 0 이 안 됩니다.")
    목록.append("    비관에서 CapEx 를 크게 깎았으면 **마진이 그만큼 좋게 나온다**는 것을 적으십시오")
    글 = [x.replace("PLACE_N", chr(10)) for x in 오류]
    경 = [x.replace("PLACE_N", chr(10)) for x in 경보]
    return 글, 경, 목록


def 상각배분검사(가정, 라벨):
    """㉙ — **상각이 손익에 실렸나.** 168·172 가 비면 전액이 사라진다.

    엔진 배선은 이렇다.
        x29 = 기존자산 상각 (총 상각 x28 에서 증설 몫을 뺀 것)
        x36 = x29 × **168행**  → 5번 12행 (COGS 감가상각)
        x37 = x29 × **172행**  → 6번 13행 (SG&A 감가상각)
    **둘이 비면 `_n(None)=0` 이라 x36 = x37 = 0** — 상각이 손익 어디에도 안 실린다.
    영업이익이 그만큼 부푼다.

    거기서 끝이 아니다. FCFF 의 D&A 가산(2번 16행)은 **총 상각 x28 그대로**다.
    **빼지도 않은 것을 도로 더해 준다.** 이득이 두 번 난다.

    실측(IREN): 168·172 를 비워 감가상각 14.1억이 사라졌고, 주당가치가
    **+$17.89 → −$9.48** 로 **부호가 갈렸다.** 합계 검산으로는 안 잡혔다 —
    사라진 것이지 틀린 곳으로 간 것이 아니어서 어디도 안 어긋났기 때문이다.

    ④(인건비 배분)은 `세 칸이 모두 비면` 검사 자체를 건너뛴다. 그 구멍을 막는다.
    """
    오류, 경보, 목록 = [], [], []
    try:
        R = _결과(가정, _적용시나리오(가정))
    except Exception as e:                                   # noqa: BLE001
        목록.append("  재료 없음 — 엔진을 못 불러 상각 배분을 못 봅니다: %s" % e)
        return 오류, 경보, 목록
    p = _판(가정)
    첫 = p.첫

    def col(키):
        return _줄(R, "8.CapEx", 키)

    # 8번 34 감가상각비 및 무형자산상각비 합계 · 41 배분율 합계 · 42 · 43 배분액(매출원가 · 판관) · 39 · 40 배분율(168 · 172)
    x28, x35, x36, x37 = col("34"), col("41"), col("42"), col("43")
    x33, x34 = col("39"), col("40")
    g22 = _줄(R, "6.SG&A", "22")

    열들 = list(p.예측영구)
    if not 열들:
        목록.append("  재료 없음 — 예측 열이 없습니다")
        return 오류, 경보, 목록

    def 나(i, v):
        return "%s 열" % p.열글(i)

    빈칸열, 모자란열, 넘치는열 = [], [], []
    사라진최대, 사라진열, 사라진비 = 0.0, None, None

    for i in 열들:
        합 = x35[i]
        합 = 0.0 if 합 is None else float(합)
        총 = x28[i]
        총 = 0.0 if 총 is None else float(총)
        실림 = (x36[i] or 0.0) + (x37[i] or 0.0)
        if 총 <= 0:
            continue
        # 사라진 금액 — 배분합이 0 이면 총 상각을 상한으로 쓴다(증설 몫만큼 과대)
        if 합 > 0.0005:
            기존 = 실림 / 합
            사라짐 = 기존 * (1.0 - 합)
        else:
            기존 = 총
            사라짐 = 총
        영 = g22[i]
        비 = (abs(사라짐) / abs(영)) if (영 and abs(영) > 0) else None
        if 합 <= 0.0005:
            빈칸열.append(i)
        elif 합 < 0.995:
            모자란열.append(i)
        elif 합 > 1.005:
            넘치는열.append(i)
        if 합 < 0.995 and abs(사라짐) > abs(사라진최대):
            사라진최대, 사라진열, 사라진비 = 사라짐, i, 비

    목록.append("  상각 배분 — 168행(제조) %s · 172행(판관) %s (첫 예측 열)"
                % ("%.0f%%" % ((x33[첫] or 0.0) * 100), "%.0f%%" % ((x34[첫] or 0.0) * 100)))

    꼬리 = ("\n      **합계 검산으로는 안 잡힙니다** — 틀린 곳으로 간 것이 아니라 "
          "사라진 것이라 어디도 안 어긋납니다.\n"
          "      실측(IREN): 이 두 칸을 비워 감가상각 14.1억이 사라졌고 "
          "주당가치가 **+$17.89 → −$9.48** 로 **부호가 갈렸습니다.**")

    if 빈칸열:
        오류.append(_넘김오류(
            "  **168·172(상각 배분)가 비어 있습니다 — 예측 열 %d개.** "
            "상각이 손익 어디에도 안 실립니다.\n"
            "      %s에서 **%s** 이 사라집니다%s.\n"
            "      엔진은 `5번 12행 = 기존자산상각 × 168행` · `6번 13행 = × 172행` 입니다. "
            "**둘이 비면 0 을 곱한 것이라 영업이익이 그만큼 부풉니다.**\n"
            "      게다가 FCFF 의 D&A 가산(2번 16행)은 **총 상각 그대로**입니다 — "
            "**빼지도 않은 것을 도로 더해 줍니다. 이득이 두 번 납니다.**\n"
            "      **168 + 172 = 1** 로 채우십시오. 실적의 제조/판관 감가상각 비율을 "
            "그대로 쓰면 됩니다.%s"
            % (len(빈칸열), 나(사라진열 if 사라진열 is not None else 빈칸열[0], None),
               _금액(사라진최대, 가정),
               ("(그 열 영업이익의 **%.1f%%**)" % (사라진비 * 100)) if 사라진비 else "",
               꼬리.replace("\n", "\n")), "C-02", "I-14"))

    if 모자란열:
        목록.append(_넘김(
            "  **168 + 172 의 합이 1 에 못 미치는 예측 열이 %d개 있습니다.** "
            "그 차이만큼 상각이 **손익에서 사라집니다.**\n"
            "      %s에서 **%s**%s.\n"
            "      168 + 172 = 1 로 맞추십시오.%s"
            % (len(모자란열), 나(사라진열, None), _금액(사라진최대, 가정),
               ("(그 열 영업이익의 **%.1f%%**)" % (사라진비 * 100)) if 사라진비 else "",
               꼬리), "I-14"))

    if 넘치는열:
        목록.append(_넘김(
            "  **168 + 172 의 합이 1 을 넘는 예측 열이 %d개 있습니다.** "
            "상각이 **두 번 실립니다** — 영업이익이 그만큼 깎입니다.\n"
            "      168 + 172 = 1 로 맞추십시오"
            % len(넘치는열), "I-14"))

    # 15번 I-14 는 적용 시나리오만 본다 — 그 밖 시나리오의 168 + 172(입력 — 8번 39 · 40 이 그대로 받는다)는 여기서 본다
    적용 = _적용시나리오(가정)
    for 시 in 시나리오목록:
        if 시 == 적용:
            continue
        a, b = p.A("168", 시), p.A("172", 시)
        어긋 = [p.열글(i) for i in 열들 if (a[i] is not None or b[i] is not None)
              and abs((a[i] or 0.0) + (b[i] or 0.0) - 1.0) > 0.005]
        if 어긋:
            오류.append("  **[%s] 168 + 172 의 합이 1 이 아닌 예측 열 %d개(%s)** — 그 시나리오에서 상각이 사라지거나 두 번 "
                        "실립니다. 168 + 172 = 1 로 맞추십시오(15번 I-14 는 적용 시나리오만 봅니다)"
                        % (시, len(어긋), "·".join(어긋[:4])))

    if not (빈칸열 or 모자란열 or 넘치는열):
        목록.append("  예측 열 %d개 모두 168 + 172 = 1 — 상각이 온전히 손익에 실립니다"
                    % len(열들))
    return 오류, 경보, 목록



def _선언된사이클계단(가정, 영구마진):
    """㉝ 의 예외 — **의도한 정규화 계단인가**(S8-02 · S8-06 — 2026-10-17 다시 씀).

    셋을 다 만족해야 참이다.
      ㉮ `구조.영구가치.정상화계단 = 예` 로 선언했거나, 사이클 판정(`_사이클` — A3 국면 · 덧표지 · 관측 시계열 S6 신호 · 옛 부호 전환 자)이
         참이다. 옛 판은 「관측 영업이익률 부호 전환 2회」 하나로만 재서 흑자를 유지하는 사이클 회사가 늘 「사이클 아님」이었다
      ㉯ 종착 마진이 관측 [최저, 최고] **안**이다(관측 = 관측 키 → 앵커 → A3 → 원천 13번) — 밖이면 관측에 없는 수준을 세운 것이라
         계단이 아니라 선언이고, ⑥ 이 따로 묻는다
      ㉰ 12번 **213행 근거 칸이 차 있다** — 「어느 쪽인지 적으면 된다」(집대성 4단계 ⑦)
    참이면 ㉝ 는 그 계단을 절벽으로 세지 않고 ⑥(영구 OPM 대 종착 마진 — 213 · 운영 동종 · 사이클 평균)으로 넘긴다.
    """
    if 영구마진 is None:
        return False
    선언 = ((가정.get("구조") or {}).get("영구가치") or {}).get("정상화계단") == "예"
    if not (선언 or _사이클(가정).get("사이클")):
        return False
    관측, _출 = _대상관측마진(가정)
    수 = [v for _, v in 관측 if v is not None]
    if len(수) >= 2 and not (min(수) <= 영구마진 <= max(수)):
        return False
    if len(수) < 2 and not 선언:
        return False
    근 = (가정.get("근거") or {}).get("213") or []
    return bool([x for x in 근 if ("%s" % (x or "")).strip()])


def 종착절벽검사(가정, 라벨):
    """㉝ — **마지막 예측 해와 영구가 이어지나 + 창이 회수를 담았나.** 셋을 함께 잰다(v13 줄로 다시 씀 — W7a).

    2026-09-08 신설(LG엔솔 실측 — 외부 DCF 대조 계기). 5년 창에서 ① 마지막 예측 해
    실효 OPM 7.8% → 영구 4.5% 절벽 ② 예측 FCF 전열 음수인데 TV비중 596% ③ 마지막
    투자(2030)의 램프업 완성이 2035 — 셋 다 「창과 종착」의 병인데 아무 검사도 안
    울었다. 10년 연장 + 213 재정렬로 기준이 −74,353 → +19,358원. 값을 이만큼 가르는
    자리를 사람 눈에만 맡길 수 없다.

      · 절벽 — 영구기간 지표 − 마지막 예측 해 지표. |스프레드| > 5%p 오류, > 2%p 경보.
        지표는 영업이익률이다. 다만 **영구상각 = 정상유지투자**면 영구기간의 감가상각을 정상 유지 투자로
        다시 세우므로 EBITDA 이익률로 잰다(설계서 R-107). 재고자산 변동을 원가에 반영하면(원가.재고변동반영 = 예)
        영구기간 열에는 재고 변동이 없으므로 마지막 예측 해에서도 그 몫(5번 153)을 빼고 견준다.
        영구 쪽은 가치에 쓴 값 — 영구이익기준 = 영구열이면 영구기간 열 손익(2번 42 · 영구기간 열 15 · 16 · 11),
        입력이면 213(2번 42). ㉗ 이 실적↔추정 경계를 재는 것의 영구판이다(집대성 4단계 ⑦)
      · 창 부족 — 마지막 예측 해 FCFF(2번 23)가 음수인데 영구가치 비중이 100% 를 넘으면
        「투자만 창 안, 회수는 전부 창 밖」 신호. 경보로 창 확대를 지시한다
      · 수렴 미완 — 수준 경로 구분의 정상 수준 도달 연도(6s9)가 최종 예측 연도 뒤면 영구기간 열은 정상 수준
        판매단가 지수로 서는데 창은 거기에 닿지 못했다 — 경보(옛 램프업 미완의 자리 · T2 세는 기준, 집대성 4단계 ①)
    """
    오류, 경보, 목록 = [], [], []
    p = _판(가정)
    끝, 영 = p.끝, p.영구
    영구열 = _영구이익기준(가정) == "영구열"
    정상유지 = p.구["영구가치"]["영구상각"] == "정상유지투자"
    재고반영 = p.구["원가"]["재고변동반영"] == "예"
    EBITDA로 = 정상유지 and 영구열                       # 입력(213)은 영업이익률이라 EBITDA 로 바꿀 수 없다
    지표이름 = "EBITDA 이익률" if EBITDA로 else "OPM"
    목록.append("  지표 — %s (영구이익기준 %s · 영구상각 %s%s)"
                % (지표이름, _영구이익기준(가정), p.구["영구가치"]["영구상각"],
                   " · 마지막 예측 해의 재고 변동(5번 153)을 빼고 견줌" if 재고반영 else ""))

    적용 = _적용시나리오(가정)
    for 시 in 시나리오목록:
        try:
            R = _결과(가정, 시)
        except Exception as e:                               # noqa: BLE001
            목록.append("  %s — 계산 실패: %s" % (시, e))
            continue
        매, ebit, da = _줄(R, "2.DCF", "11"), _줄(R, "2.DCF", "15"), _줄(R, "2.DCF", "16")
        재고 = _줄(R, "5.COGS", "153") if 재고반영 else [None] * p.n
        if not 매[끝] or ebit[끝] is None:
            목록.append("  %s — 마지막 예측 해 손익 재료 부족(2번 11 · 15)" % 시)
            continue
        끝ebit = ebit[끝] - (재고[끝] or 0.0)               # 재고 증가(153 양수)가 원가를 줄인 몫을 뺀다
        if EBITDA로:
            끝지표 = (끝ebit + (da[끝] or 0.0)) / 매[끝]
            영구지표 = ((ebit[영] + (da[영] or 0.0)) / 매[영]) if (매[영] and ebit[영] is not None) else None
        else:
            끝지표 = 끝ebit / 매[끝]
            영구지표 = _영구이익률값(가정, R)
        if 영구지표 is None:
            목록.append("  %s — 영구기간 지표를 읽지 못했습니다(2번 42 · 영구기간 열)" % 시)
            continue
        스프레드 = 영구지표 - 끝지표
        목록.append("  %s — 마지막 예측 해 %s %.2f%% → 영구 %.2f%% (스프레드 %+.2f%%p)"
                    % (시, 지표이름, 끝지표 * 100, 영구지표 * 100, 스프레드 * 100))
        if abs(스프레드) > 0.05 and _선언된사이클계단(가정, _영구이익률값(가정, R)):
            # **영구가치 규칙이 요구한 계단이다 — 절벽이 아니다.** (2026-09-10 신설, SK하이닉스 회차)
            # 절벽 금지와 사이클 종착은 **방향이 반대인 두 조문**이고,
            # 집대성 4단계 ⑦ 이 「어느 쪽인지 적으면 된다」고 적어 두었다.
            # 셋을 다 만족해야 내린다: ㉮ 부호 전환 2회 이상 ㉯ 종착이 관측 [최저,최고] 안 ㉰ 213 근거 칸이 차 있다.
            목록.append(
                "  **[%s] 정규화 계단 %+.2f%%p** (마지막 예측 해 %.2f%% → 영구 %.2f%%) — "
                "사이클 판정(또는 구조.영구가치.정상화계단 = 예)이고 종착이 관측 범위 안이며 213 근거가 "
                "차 있어 **영구가치 규칙이 요구한 계단**으로 읽습니다. 절벽이 아닙니다 — 정상 수준과의 거리는 ⑥ 이 잽니다"
                % (시, 스프레드 * 100, 끝지표 * 100, 영구지표 * 100))
        elif abs(스프레드) > 0.05:
            (목록 if 시 == 적용 else 경보).append((lambda x: _넘김(x, "R-107") if 시 == 적용 else x)(
                "  **[%s] 종착 절벽 — 마지막 예측 해 %s %.2f%% 가 영구에서 %.2f%% 로 "
                "꺾입니다(%+.2f%%p).**PLACE_N"
                "    %sPLACE_N"
                "    **종착을 마지막 예측 해의 안정화된 수준과 재정렬하고 근거 칸에 적으십시오** (집대성 4단계 ⑦)"
                % (시, 지표이름, 끝지표 * 100, 영구지표 * 100, 스프레드 * 100,
                   ("영구기간 열의 가정(영구기간 열 값 · 정상 수준 판매단가 · 정상 유지 투자)이 마지막 예측 해와 다른 세계를 그리면 "
                    "경로가 회복을 그려도 영구만 따로 섭니다." if 영구열 else
                    "과거 침체기 마진이나 옛 선언값(213)을 영구에 기계적으로 두면 경로가 회복을 그려도 "
                    "영구만 옛 값에 묶입니다."))))
        elif abs(스프레드) > 0.02:
            목록.append(
                "  [%s] 종착 스프레드 %+.2f%%p (마지막 예측 해 %s %.2f%% → 영구 %.2f%%) — 15번 R-107 의 문턱(5%%p) 안이라 "
                "판정하지 않습니다. 구조 변화(전환·수명 종료)가 이유면 근거 칸에 적어 둡니다"
                % (시, 스프레드 * 100, 지표이름, 끝지표 * 100, 영구지표 * 100))
        if 시 == 적용 and 재고반영 and 재고[끝]:
            원지표 = ((ebit[끝] + (da[끝] or 0.0)) / 매[끝]) if EBITDA로 else ebit[끝] / 매[끝]
            목록.append("  %s — 15번 R-107 은 마지막 예측 해의 재고 변동(5번 153 %s)을 빼지 않고 잽니다 — 그 자로는 스프레드 "
                        "%+.2f%%p (이 검사 %+.2f%%p)" % (시, "{:,.0f}".format(재고[끝]), (영구지표 - 원지표) * 100, 스프레드 * 100))

        if 시 == _적용시나리오(가정):
            비중 = _수((R.get("요약") or {}).get("영구가치비중"))
            끝fcf = _줄(R, "2.DCF", "23")[끝]
            if 비중 is not None and 끝fcf is not None:
                목록.append("  %s — 마지막 예측 해 FCFF %s · 영구가치 비중 %.0f%%"
                            % (시, "{:,.0f}".format(끝fcf), 비중 * 100))
                # 기준은 「FCFF 가 양(+)으로 전환된 채 창이 닫혔는가」다 — 누적 합이
                # 아니라 마지막 해의 부호. 투자기 회사는 연장해도 초기 유출 탓에 누적이
                # 음수일 수 있는데(LG엔솔 10년: 합 −6.0조·마지막 해 +3.8조) 그건 창의 병이 아니다.
                if 끝fcf <= 0 and 비중 > 1.0:
                    목록.append(_넘김(
                        "  **[%s] 창 부족 신호 — 마지막 예측 해 FCFF 가 아직 음수인데 영구가치 "
                        "비중이 %.0f%% 입니다.**PLACE_N"
                        "    투자만 창 안이고 회수는 전부 창 밖이라는 뜻입니다. T2(투자–회수 "
                        "시차)를 대 보고,PLACE_N"
                        "    **FCFF 가 양(+)으로 전환될 때까지 창을 넓히십시오**(기간.상세추정연수 · 수렴연수) — 회수 완성 "
                        "열은 마지막 프로젝트PLACE_N"
                        "    CapEx 열 + 리드타임 + 라인 생산능력의 램프업 길이입니다 (집대성 4단계 ①·LG엔솔 "
                        "실측: 5년 창 596%% → 10년 135%%)"
                        % (시, 비중 * 100), "R-01", "R-02"))

    # 수렴 미완 — 정상 수준 도달 연도(6s9)가 최종 예측 연도 뒤
    끝연도 = p.회계연도[끝]
    for x in p.구.목록("매출구분"):
        s = x.get("번호")
        if not s or s >= 6 or x.get("경로") not in ("수준", "증가율") or x.get("단가경로") != "수렴":      # S8-06 — 증가율 경로도
            continue
        for 시 in 시나리오목록:
            도달 = p.S(600 + 10 * s + 9, 시)
            if 도달 is None or 끝연도 is None:
                continue
            if 도달 > 끝연도:
                (목록 if 시 == 적용 else 경보).append((lambda x: _넘김(x, "I-112") if 시 == 적용 else x)(
                    "  **[%s] 수렴 미완 — %s 의 정상 수준 도달 연도 %d 가 최종 예측 연도 %d 뒤입니다.**PLACE_N"
                    "    영구기간 열은 정상 수준 판매단가 지수(%d행)로 서는데 창은 거기에 닿지 못했습니다 —PLACE_N"
                    "    **도달 연도까지 창을 늘리거나**(기간.상세추정연수 · 수렴연수) 도달 연도를 창 안으로 당긴 근거를 적으십시오"
                    % (시, _구분이름(가정, s), int(도달), int(끝연도), 600 + 10 * s + 6)))
            else:
                목록.append("  %s — %s 정상 수준 도달 %d ≤ 최종 예측 연도 %d (창이 수렴을 담았습니다)"
                            % (시, _구분이름(가정, s), int(도달), int(끝연도)))

    # S8-06 — 원가 줄의 목표 마진 수렴(구조.원가줄[].수렴): 도달 연도가 창 밖이면 「수렴 미완」, 창 안인데 그 해 값이 목표와 다르면 경보
    _원가수렴(가정, p, 경보, 목록)
    # S8-01 — T1 명시적 수명(구조.매출구분[].수명): 만료가 창 밖이면 T1 경보, 창 안이면 영구기간 열이 잔존으로 섰는지
    _수명대조(가정, p, 경보, 목록)
    # S8-05 — 영구 FCFF 절벽: 영구기간 FCFF ÷ (마지막 해 FCFF 연환산 × (1 + g)) 가 ±20% 밖이면 경보(재투자 절벽 · 재투자 급증)
    _영구FCFF절벽(가정, p, 경보, 목록)

    # R-67 증설 완료 시점과 예측기간(가정 점검) — 마지막 성장 투자의 능력 · 매출이 창 뒤에 서는가
    _증설완료(가정, p, 경보, 목록)

    for 표 in (오류, 경보, 목록):
        for i, 글 in enumerate(표):
            표[i] = 글.replace("PLACE_N", chr(10))
    return 오류, 경보, 목록


_원가비율번호 = {1: 80, 2: 84, 3: 88, 4: 92, 5: 112, 6: 116, 7: 120}


def _원가수렴(가정, p, 경보, 목록):
    """S8-06 — `구조.원가줄[].수렴`(목표 · 도달연도) 대조. 매출액비율 줄(80 꼴) · 설비계수(7k1) · 지표계수(7k8)만 받는다."""
    끝연도 = p.회계연도[p.끝]
    적용 = _적용시나리오(가정)
    for x in p.구.목록("원가줄"):
        수 = x.get("수렴") if isinstance(x.get("수렴"), dict) else None
        if not 수 or _수(수.get("목표")) is None or _수(수.get("도달연도")) is None:
            continue
        k, 산식 = x.get("번호"), x.get("산식")
        번 = {"매출액비율": _원가비율번호.get(k), "설비계수": 700 + 10 * k + 1, "지표계수": 700 + 10 * k + 8}.get(산식)
        이름 = "원가 줄 %s%s" % (k, ("(%s)" % x.get("이름")) if x.get("이름") else "")
        if 번 is None:
            경보.append("  %s — 수렴 선언이 있는데 산식 %s 는 수렴 키를 받지 않습니다(매출액비율 · 설비계수 · 지표계수)" % (이름, 산식))
            continue
        도달, 목표 = int(수["도달연도"]), 수["목표"]
        if 도달 > 끝연도:
            경보.append(_넘김("  **수렴 미완 — %s 의 목표(%s) 도달 연도 %d 가 최종 예측 연도 %d 뒤입니다.** 영구기간 열은 그 목표로 서는데 창은 거기 닿지 "
                            "못했습니다 — 창을 늘리거나(`연장.py`) 도달 연도를 창 안으로 당긴 근거를 적으십시오(T3)" % (이름, 목표, 도달, 끝연도), "I-112"))
            continue
        for 시 in 시나리오목록:
            v = p.A(번, 시)
            칸 = [i for i in p.예측 if p.회계연도[i] is not None and p.회계연도[i] >= 도달]
            어긋 = [p.열글(i) for i in 칸 if v[i] is not None and abs(v[i] - 목표) > 1e-9 * max(1.0, abs(목표))]
            if 어긋:
                (경보 if 시 == 적용 else 목록).append("  %s %s — 수렴 선언(목표 %s · 도달 %d)과 12번 %d 의 값이 %s 에서 다릅니다 — "
                                                   "`연장.py --수렴채움` 으로 채우거나 선언을 고칩니다" % (이름, 시, 목표, 도달, 번, " · ".join(어긋[:3])))
            else:
                목록.append("  %s %s — 목표 %s 를 %d 에 닿았습니다(창 안)" % (이름, 시, 목표, 도달))


def _수명대조(가정, p, 경보, 목록):
    """S8-01 — T1 명시적 수명(`구조.매출구분[].수명` — 만료연도 · 잔존비율 · 침식연수). 만료가 창 밖이면 T1 경보(수명 끝 매출이 영구 열에서
    (1 + g)로 영원히 팔린다 — 연장하거나 영구기간 열의 판매량 증가율에 침식을 싣는다). 창 안에서 침식이 끝났으면 영구기간 열 매출 ÷ 만료 직전 해
    매출이 잔존 비율 × (1 + g) 근처(±25%)인지 본다. F 의 `계약시한[]`(`_raw/투자능력.json` — A3 `계약시한후보` 를 옮긴 것)이 매출 구분 수명의
    재료다 — 수명 선언이 하나도 없는데 끝나는 날이 창 밖인 계약이 있으면 목록에 적는다(매출에 걸린 수명이면 `구조.매출구분[].수명` 으로 옮긴다)."""
    끝연도 = p.회계연도[p.끝]
    적용 = _적용시나리오(가정)
    선언 = 0
    for x in p.구.목록("매출구분"):
        수 = x.get("수명") if isinstance(x.get("수명"), dict) else None
        if not 수 or _수(수.get("만료연도")) is None:
            continue
        선언 += 1
        M, s = int(수["만료연도"]), x.get("번호")
        ρ, n = _수(수.get("잔존비율")) or 0.0, int(_수(수.get("침식연수")) or 1)
        이름 = _구분이름(가정, s)
        if M + n > 끝연도:
            경보.append(_넘김("  **T1 — %s 의 수명(%s 만료 %d · 침식 %d해 → 잔존 %.0f%%)이 창(최종 예측 연도 %d) 밖에서 끝납니다.**PLACE_N"
                            "    영구기간 열은 최종 예측 연도를 (1 + g) 로 한 해 더 민 것이라 그 매출을 영원히 팝니다. `python 스크립트/연장.py <가정.json> "
                            "--사유 T1` 로PLACE_N    만료 + 침식까지 늘린 후보(상한 10년)를 보거나, 10년 밖이면 5년을 유지하고 영구기간 열의 판매량 증가율에 "
                            "남은 침식을 싣습니다(「길이 결정」)"
                            % (이름, 수.get("종류") or "수명", M, n, ρ * 100, 끝연도), "R-01"))
            continue
        try:
            R = _결과(가정, 적용)
            금 = _줄(R, "4.Sales", {1: "13", 2: "21", 3: "27", 4: "33", 5: "39"}.get(s, "13"))
            M열 = [i for i in p.예측 if p.회계연도[i] == M]
            if M열 and 금[M열[0]] and 금[p.영구] is not None:
                g = _수(p.S(212, 적용)) or 0.0
                비 = 금[p.영구] / 금[M열[0]]
                기대 = ρ * (1 + g) ** (끝연도 + 1 - M)
                (목록 if abs(비 - 기대) <= 0.25 * max(기대, 0.05) else 경보).append(
                    "  %s — 수명 %d 만료 · 침식 %d해: 영구기간 열 매출 ÷ 만료 해 매출 = %.2f배(잔존 %.0f%% × 성장 = %.2f배%s)"
                    % (이름, M, n, 비, ρ * 100, 기대, "" if abs(비 - 기대) <= 0.25 * max(기대, 0.05) else " — 영구 열이 잔존으로 서지 않았습니다"))
        except Exception as e:                                               # noqa: BLE001
            목록.append("  %s — 수명 대조를 못 했습니다: %s" % (이름, e))
    제, _곳 = _갈래파일("투자능력.json")
    시한 = (제 or {}).get("계약시한") if isinstance(제, dict) else None
    if isinstance(시한, list) and 시한 and not 선언:
        import re as _re
        def _끝해(x):
            m = _re.search(r"(19|20)\d{2}", "%s" % (x.get("끝나는날") or x.get("만료연도") or ""))
            return int(m.group(0)) if m else None
        밖 = [x for x in 시한 if isinstance(x, dict) and _끝해(x) and 끝연도 and _끝해(x) > 끝연도]
        if 밖:
            목록.append("  F 계약시한 %d건이 창(%s) 밖에서 끝납니다(%s) — 매출에 걸린 수명이면 `구조.매출구분[].수명` 으로 옮깁니다(T1)"
                        % (len(밖), 끝연도, " · ".join("%s %s" % ((x.get("이름") or "?")[:20], _끝해(x)) for x in 밖[:3])))


def 영구FCFF이음값(가정, R=None, 시=None):
    """㉝ 영구 FCFF 절벽의 셈 — 영구기간 FCFF(2번 23 의 영구 칸) ÷ (마지막 예측 열 FCFF 연환산 × (1 + g)). 자체검사 ㉝ 과 레터 장부 키
    「가:대조:영구가치:FCFF이음:<칸>」 이 이 한 함수를 쓴다(레터 v27 6단계 A). 마지막 해 FCFF 가 0 이하면 None.
    → {"배율", "영구FCFF", "끝FCFF연환산", "g", "재투자율", "RONIC"}"""
    p = _판(가정)
    시 = 시 or _적용시나리오(가정)
    R = R if R is not None else _결과(가정, 시)
    f = _줄(R, "2.DCF", "23")
    끝, 영 = p.끝, p.영구
    g = _수(p.S(212, 시)) or 0.0
    년 = p.년[끝] or 1.0
    if f[끝] is None or f[영] is None or not f[끝] or f[끝] <= 0:
        return None
    요 = R.get("요약") or {}
    return {"배율": f[영] / (f[끝] / 년 * (1 + g)), "영구FCFF": f[영], "끝FCFF연환산": f[끝] / 년, "g": g,
            "재투자율": _수(요.get("재투자율")), "RONIC": _수(요.get("영구ROIC"))}


def _영구FCFF절벽(가정, p, 경보, 목록):
    """S8-05 — 영구기간 FCFF(2번 23 의 영구 칸 = NOPLAT × (1 − g ÷ RONIC)) ÷ (마지막 해 FCFF 연환산 × (1 + g)). ±20% 밖이면 경보 —
    예측 끝 성장이 재투자 없이 나왔는데 영구에서 RONIC 로 재투자가 되살아나거나(재투자 절벽 — 자산 경량 · 음의 운전자본 유형), 그 반대다."""
    시 = _적용시나리오(가정)
    try:
        R = _결과(가정, 시)
    except Exception:                                                        # noqa: BLE001
        return
    값 = 영구FCFF이음값(가정, R, 시)                        # 레터 v27 6단계 A — 셈은 이 함수 하나(레터 장부 키 「가:대조:영구가치:FCFF이음:…」)
    if 값 is None:
        목록.append("  영구 FCFF 절벽 — 마지막 해 FCFF 가 0 이하라 재지 않습니다(창 부족 신호는 위에서 봅니다)")
        return
    비 = 값["배율"]
    줄 = ("  %s — 영구 FCFF %s ÷ (마지막 해 FCFF 연환산 %s × (1 + g)) = %.2f배 · 영구 재투자율 %s(g ÷ RONIC %s)"
          % (시, "{:,.0f}".format(값["영구FCFF"]), "{:,.0f}".format(값["끝FCFF연환산"]), 비, _퍼(값["재투자율"]), _퍼(값["RONIC"])))
    if abs(비 - 1) > 영구FCFF절벽폭:
        # 1.1.2(HM28) — 근거 있는 검토의견(R-67)으로 닫을 수 있다. 닫을 길이 없으면 경보를 없애려고 투자 경로(판단)를 바꾸게 된다 — 검사가
        #   판단을 바꾸지 않게 한다(판단을 바꿨으면 판단대장에 검사 전 값 · 뒤 값을 둘 다 적는다)
        경보.append(_검토(줄, "R-67") + "PLACE_N    **영구 FCFF 가 마지막 해와 %.0f%% 갈립니다** — %s. 219(영구 RONIC)를 예측 끝의 증분 ROIC · 운영 동종 ROIC 와 견주고"
                    "PLACE_N    두 값(= WACC · = 증분 ROIC)의 주당가치를 레터 · 민감도(Ⅵ RONIC × g)에 병기합니다(안정성장 ④)"
                    % ((비 - 1) * 100, "영구 재투자(g ÷ RONIC × NOPLAT)가 마지막 해 재투자보다 무겁다 — 예측 끝의 성장이 재투자 없이 "
                       "났다면 영구에서 재투자가 되살아나는 재투자 절벽이다(자산 경량 · 음의 운전자본 유형)" if 비 < 1
                       else "영구 재투자가 마지막 해보다 가볍다(마지막 해에 큰 투자가 남았거나 RONIC 이 높다)"))
    else:
        목록.append(줄 + " — ±20% 안")


def _증설완료(가정, p, 경보, 목록):
    """R-67 — 프로젝트(구조.투자.프로젝트)의 성장 CAPEX(12번 86p)가 마지막 예측 연도에도 나가거나, 마지막 지출 연도 + 리드타임이
    최종 예측 연도 뒤면 그 투자의 능력 · 매출은 창 밖에서 선다 — 경보(사유는 `검토의견.R-67`). 능력 경로 라인의 마지막 해
    램프업(기말 669 + 2j > 평균 668 + 2j)은 목록으로 적는다(영구기간 열은 최종 예측 연도 말의 능력으로 선다)."""
    끝 = p.끝
    끝연도 = p.회계연도[끝]
    뒤 = []
    for x in (p.구["투자"].get("프로젝트") or []):
        n = x.get("번호")
        if not n:
            continue
        리드 = _수(x.get("리드타임")) or 0.0
        이름 = ("%s" % (x.get("이름") or "")).strip() or "프로젝트 %d" % n
        for 시 in 시나리오목록:
            줄 = p.A(str(860 + n), 시)
            쓴열 = [i for i in p.예측 if (_수(줄[i]) or 0.0) > 0]
            if not 쓴열 or 끝연도 is None:
                continue
            마지막 = 쓴열[-1]
            완공 = (p.회계연도[마지막] or 끝연도) + 리드
            if 마지막 == 끝 or 완공 > 끝연도:
                뒤.append("[%s] %s — 마지막 지출 %s %s · 리드타임 %g년%s"
                          % (시, 이름, p.열글(마지막), "{:,.0f}".format(_수(줄[마지막])), 리드,
                             " → 완공 %g년(최종 예측 연도 %d 뒤)" % (완공, 끝연도) if 완공 > 끝연도 else " (최종 예측 연도에도 지출)"))
    if 뒤:
        경보.append(
            "  **증설이 창 안에서 끝나지 않습니다(R-67) — 마지막 예측 연도(%s)에도 성장 투자가 나가거나 완공이 그 뒤입니다.**%s"
            "%s%s"
            "    그 투자의 능력 · 매출은 창 밖에서 섭니다 — 영구이익기준 = 영구열이면 영구기간 열은 최종 예측 연도 말의 능력으로 서므로%s"
            "    램프업이 남은 만큼 빠지고, 입력(213)이면 마지막 해 매출에 묶입니다. 창을 늘리거나(기간.상세추정연수) 그렇게 둔%s"
            "    사유를 검토 의견(`검토의견.R-67`)에 적습니다"
            % (p.열글(끝), "PLACE_N", "PLACE_N".join("      · " + x for x in 뒤[:6]), "PLACE_N", "PLACE_N", "PLACE_N"))
    적용 = _적용시나리오(가정)
    for x in p.구.목록("매출구분"):
        if x.get("경로") != "수준" or x.get("판매량산정") != "능력":
            continue
        for l in (x.get("라인") or []):
            j = l.get("번호") if isinstance(l, dict) else None
            if not j:
                continue
            평, 말 = _수(p.A(str(668 + 2 * j), 적용)[끝]), _수(p.A(str(669 + 2 * j), 적용)[끝])
            if 평 and 말 and 말 > 평 * 1.05:                   # S5-16 — 능력 램프 미완(마지막 해 평균이 기말보다 5% 넘게 낮다) — 수렴 미완과 같은 자리
                경보.append("  **%s — 라인 %d 「%s」 능력 램프가 창 안에서 끝나지 않습니다** — 최종 예측 연도 평균 %s → 기말 %s(%.0f%% 남음). "
                            "T2 창은 마지막 프로젝트 열 + 리드타임 + 램프업이다(집대성 4단계 ①) — 창을 늘리거나 그렇게 둔 근거를 적는다"
                            % (적용, j, ("%s" % (l.get("이름") or "")).strip(), "{:,.4g}".format(평), "{:,.4g}".format(말), (말 / 평 - 1) * 100))
            elif 평 and 말 and 말 > 평 * 1.02:
                목록.append("  %s — 라인 %d 「%s」 최종 예측 연도 평균 능력 %s → 기말 %s (마지막 해에도 램프업 — 영구기간 열은 "
                            "기말 능력으로 섭니다)" % (적용, j, ("%s" % (l.get("이름") or "")).strip(), "{:,.4g}".format(평),
                                                       "{:,.4g}".format(말)))



def 계속기업정합검사(가정, 라벨):
    """㉞ — **영구 가정이 계속기업과 같이 설 수 있나.** 하한과 임계를 잰다.

    2026-09-08 신설(다모다란 리서치 · 이차전지 4사 실측). 영구기간 영업이익률을 어디서 가져왔든
    (자기 정규화 · 직접 선언 · 목표 마진 수렴) 두 검산을 지나야 한다.

      · **하한 — 영구 이자보상.** 영구 EBIT(엔진이 가치에 쓴 2.DCF 43 = 41 × 42 − 유한
        제외. 2026-09-13 전에는 R열 15행을 읽었다)가 이자비용(총차입 ×
        (Rf+스프레드))을 못 덮으면 그 시나리오는 「영원히 이자를 못 갚으며 계속
        투자한다」는 내적 모순이다. 낮은 마진은 보수가 아니라 **다른 이야기**(수확·
        축소·구조조정)라 서사를 다시 짓는다. 실측: 삼성SDI 기준 0.91배가 첫 발화 —
        캐즘 관측 마진을 영구에 굳힌 판이 이 검사에 걸린다.
      · **임계 — 성장이 가치를 깎는 구간인가.** 영구 g 를 조금 흔들어 주당가치가
        **내려가면** 영구 ROIC < WACC 신호다(다모다란 월그린 매트릭스 — 자본비용을
        못 버는 마진에서는 성장할수록 값이 내려간다). 그 구간에서 성장·증설을 유지하는
        가정은 모순이니 g 를 낮추거나 영구기간 영업이익률을 재검토한다. 포스코퓨처엠 재회차의
        역단조(증설 NPV 음수)가 이 병의 다른 얼굴이었다.

    적용시나리오는 하한 위반이 절박하므로 이자보상 < 1.0 을 오류로, 1.0~1.5 를 경보로
    건다. 비관·낙관은 서사 재작성 지시(경보)까지만 — 비관이 일부러 낮은 마진인 것은
    정상이나, 1.0 아래면 「계속기업 서사가 아니다」라고 적어야 한다.
    """
    오류, 경보, 목록 = [], [], []
    p = _판(가정)
    적용 = _적용시나리오(가정)
    try:
        R0 = _결과(가정, 적용)
    except Exception as e:                                   # noqa: BLE001
        목록.append("  재료 없음 — 엔진을 못 불렀습니다: %s" % e)
        return 오류, 경보, 목록

    # 이자비용 — 총차입(평가기준일 열) × 영구기간 세전 타인자본비용(3번 Kd — 스프레드 · 관측수익률 어느 갈래든
    # 엔진이 낸 값). 37·38 이 같으면 태그 중복으로 하나만.
    def _잔액(r):
        return p.H기준일(r)

    차입 = sum(_잔액(r) or 0.0 for r in (37, 39, 45, 46, 47, 110, 111))      # 110 · 111 — S7-10 전환형 · 상환형 · 기타 이자부부채
    v37, v38 = _잔액(37), _잔액(38)
    if v38 and not (v37 and abs(v38 - v37) < 1e-6):
        차입 += v38
    금리 = _수(((R0.get("WACC") or {}).get("영구기간") or {}).get("Kd"))
    if 금리 is None:
        w = (가정.get("WACC") or {}).get("영구기간") or {}
        금리 = (_수(w.get("Rf")) or 0.0) + (_수(w.get("스프레드")) or 0.0)
    이자 = 차입 * 금리
    # **실측이 있으면 실측이 우선이다** — 근사 금리(Rf+스프레드)는 리스 내재이자가 낮은
    # 회사(항공·해운)에서 이자를 부풀려 위양성을 낸다(실측: 대한항공 근사 5.57% vs 실측
    # 4.3%). 원천 68(금융비용)의 최신 열을 연환산해 병기하되, 총액이라 외환손실 등이
    # 섞여 과대일 수 있으니(스캐폴드 D39 경고와 같은 결) 둘 다 재서 **둘 다 1 아래면
    # 오류, 근사만 아래면 경보**로 가른다.
    이자실측 = None
    # 13번 75행(이자비용 단독 — 외환·파생 제외)이 있으면 그것이 이자다. 68(금융비용 총액)은
    # 외환손실이 섞여 과대일 수 있다(LG엔솔 1H26: 68 연환산 3,153 vs 75 연환산 1,106).
    실측행 = "75" if any(p.H("75")[i] is not None for i in p.실적) else "68"
    실측이름 = "이자비용 단독(75" if 실측행 == "75" else "금융비용 총액(68"
    v68 = p.H(실측행)
    for i in reversed(p.실적):                    # 가장 최근 실적 열 — 연환산(반기 누계면 ÷ 0.5)
        if v68[i] is not None:
            L68 = p.년[i] or 1.0
            이자실측 = v68[i] / (L68 if L68 > 0 else 1.0)
            break
    if 이자 <= 0 and not 이자실측:
        목록.append("  무차입(총차입 0)이라 이자보상 하한이 걸릴 자리가 없습니다")
    R열어긋 = []

    for 시 in 시나리오목록:
        try:
            R = _결과(가정, 시)
        except Exception as e:                               # noqa: BLE001
            목록.append("  %s — 계산 실패: %s" % (시, e))
            continue
        # **영구 EBIT 은 엔진이 가치에 실제로 쓴 값으로 잰다** (2026-09-13 펄어비스 실측).
        # 영구가치는 2번 41(영구기간 매출액) × 42(영구기간 영업이익률) − 한시적 현금흐름 제외 = 43 으로 선다.
        # 영구이익기준 = 영구열이면 43 이 곧 영구기간 열(2번 15) 손익이고, 입력이면 213 으로 선 값이라
        # 영구기간 열 손익과 다를 수 있다 — 그 갈림은 따로 알린다. 43 이 없으면 영구기간 열로 떨어진다.
        _R15 = _줄(R, "2.DCF", "15")[p.영구]
        _R11 = _줄(R, "2.DCF", "11")[p.영구]
        _D43, _D41 = _한값(R, "2.DCF", "43"), _한값(R, "2.DCF", "41")
        영구EBIT = _D43 if _D43 is not None else _R15
        if 영구EBIT is None:
            목록.append("  %s — 영구 EBIT(2번 43 · 영구기간 열 15)를 못 읽었습니다" % 시)
            continue
        if _D43 is None:
            목록.append("  %s — 엔진 결과에 2번 43(가치에 쓴 영구 EBIT)이 없어 영구기간 열 손익으로 "
                        "잽니다" % 시)
        elif _R15 is not None:
            _차 = abs(_R15 - _D43)
            _갈림 = (_R15 < 0 <= _D43) or (_D43 < 0 <= _R15) or \
                (_차 > 0.25 * max(abs(_D43), abs(_R15), 1e-9))
            if _갈림:
                R열어긋.append((시, _R15, _D43, _R11, _D41))
            else:
                목록.append("  %s — 영구기간 열 EBIT %s ↔ 가치에 쓴 2번 43 %s (25%% 안)"
                            % (시, "{:,.0f}".format(_R15), "{:,.0f}".format(_D43)))
        # S8-09 — 영구 EBIT(N+1 해 크기)에 맞는 영구 차입으로 잰다. 목표 D/E(`WACC.영구기간.DE`)가 있으면 영구가치(2번 51) × D ÷ (D + E),
        # 없으면 기준일 차입 × (1 + g)^예측 길이(차입이 회사와 같이 자란다고 본다). 옛 판은 기준일 차입을 그대로 써 성장만큼 배율이 부풀었다
        _de영 = _수(((가정.get("WACC") or {}).get("영구기간") or {}).get("DE"))
        _g = _수(p.S(212, 시)) or 0.0
        if _de영 is not None and _수(_한값(R, "2.DCF", "51")):
            영차입 = _한값(R, "2.DCF", "51") * _de영 / (1 + _de영)
            영차입글 = "영구가치 × 목표 D/E %.2f 의 부채 몫" % _de영
        else:
            영차입 = 차입 * (1 + _g) ** sum(p.년[i] for i in p.예측)
            영차입글 = "기준일 차입 × (1 + g)^%.1f" % sum(p.년[i] for i in p.예측)
        이자 = 영차입 * 금리
        if 이자 > 0:
            배 = 영구EBIT / 이자
            실측배 = (영구EBIT / (이자실측 * (영차입 / 차입 if 차입 else 1.0))) if 이자실측 else None
            목록.append("  %s — 영구 EBIT(%s) %s ÷ 근사이자 %s(영구 차입 %s — %s × %.2f%%) = %.2f배%s"
                        % (시, "2번 43" if _D43 is not None else "영구기간 열",
                           "{:,.0f}".format(영구EBIT), "{:,.0f}".format(이자),
                           "{:,.0f}".format(영차입), 영차입글, 금리 * 100, 배,
                           (" · 실측 %s 연환산 %s) 기준 %.2f배"
                            % (실측이름, "{:,.0f}".format(이자실측), 실측배)) if 실측배 else ""))
            if 실측배 is not None and 실측행 == "75":
                배 = 실측배                      # 단독 이자 실측이 있으면 근사는 참고일 뿐이다
            elif 실측배 is not None and 배 >= 1.0 > 실측배:
                경보.append("  **[%s] 근사 이자로는 %.2f배인데 금융비용 총액(68)으로는 %.2f배입니다**"
                            " — 68 에는 외환·파생 손실이 섞일 수 있어 이것만으로 오류로 보지 않습니다."
                            " 13번 75행(이자비용 단독)을 주석에서 채우면 이 검사가 그 값을 씁니다"
                            % (시, 배, 실측배))
                continue
            if 실측배 is not None and 실측행 != "75" and 배 < 1.0 <= 실측배:
                경보.append("  **[%s] 이자보상이 근사(%.2f배)와 실측(%.2f배)에서 갈립니다**"
                            " — 근사 금리가 리스 내재이자를 부풀렸을 수 있습니다. 실측"
                            " 기준으로 하한은 넘겼으나 여유가 없으니 근거 칸에 적으십시오"
                            % (시, 배, 실측배))
                continue
            띠배 = 배
            if 실측배 is not None and 실측행 != "75":
                # 1 아래 판정은 둘 다 아래일 때만 오류(위에서 갈랐다) — 1.0~1.5 띠도 금융비용 총액(68)만 낮으면 걸지 않는다
                # (68 에는 외환 · 파생 손실이 섞여 이자보다 크다 — 하이닉스 1H26 연환산 13.3조 vs 근사이자 1.0조)
                띠배 = max(배, 실측배)
                배 = min(배, 실측배)
            if 배 < 1.0:
                글 = ("  **[%s] 영구 이자보상 %.2f배 — 이자를 못 갚는 마진이 영구에 "
                      "있습니다.**PLACE_N"
                      "    「영원히 이자를 못 갚으며 계속 투자한다」는 내적 모순입니다. 낮은 "
                      "마진은 보수가 아니라PLACE_N"
                      "    **다른 이야기**입니다 — 이 시나리오를 수확·축소·구조조정 서사로 "
                      "다시 짓거나, 영구기간 영업이익률의PLACE_N"
                      "    원천(목표 마진 수렴 — 집대성 4단계)을 다시 고르십시오" % (시, 배))
                (오류 if 시 == 적용 else 경보).append(글)
            elif 띠배 < 1.5 and 시 == 적용:
                경보.append("  **[%s] 영구 이자보상 %.2f배 — 하한(1.0) 언저리입니다.** "
                            "영구기간 영업이익률의 근거를 다시 보고, 유지되는 이유를 근거 칸에 적으십시오"
                            % (시, 띠배))
            elif 배 < 1.5 and 시 == 적용:
                목록.append("  %s — 금융비용 총액(68) 기준으로는 %.2f배이지만 근사 이자로는 %.2f배입니다 — 68 에 외환 · 파생 "
                            "손실이 섞였을 수 있어 하한 언저리로 보지 않습니다(13번 75 이자비용 단독을 채우면 그 값을 씁니다)"
                            % (시, 배, 띠배))

    if R열어긋:
        # 값은 2번 43 으로 섰으니 틀린 것은 아니다. 다만 워크북·레터가 영구기간 열을 표로 보여 주면
        # **읽는 사람이 보는 영구 손익과 값을 만든 영구 손익이 다르다** — 사람이 한 번 봐야 한다.
        경보.append((
            "  **영구기간 열의 손익이 영구가치 계산과 따로 놉니다 — %d개 시나리오.**PLACE_N"
            "%sPLACE_N"
            "    영구가치는 2번 41(영구기간 매출액) × 42(영구기간 영업이익률 — 213) − 한시적 현금흐름 제외 = **2번 43** 으로 섭니다.PLACE_N"
            "    영구기간 열은 영구이익기준 = 입력이면 가치에 안 들어가는 표시 열이라 값은 틀리지 않았지만, 표로 보면 다른 회사가PLACE_N"
            "    보입니다. 흔한 원인: 비율 가정의 영구기간 열(TV)을 비웠거나 예측 열과 다른 값을 둔 것.PLACE_N"
            "    **영구기간 열을 213 과 맞추거나(또는 영구이익기준을 영구열로), 다르게 둔 이유를 근거 칸에 적으십시오**")
            % (len(R열어긋),
               chr(10).join("      · %s — 영구기간 열 EBIT %s ↔ 2번 43 %s  (영구기간 열 매출 %s ↔ 2번 41 %s)"
                            % (시, "{:,.0f}".format(r15), "{:,.0f}".format(d43),
                               "-" if r11 is None else "{:,.0f}".format(r11),
                               "-" if d41 is None else "{:,.0f}".format(d41))
                            for 시, r15, d43, r11, d41 in R열어긋)))

    # 임계 —적용시나리오에서 영구 g 를 ±0.25%p 흔들어 방향을 잰다
    try:
        g기준 = p.S(212, 적용)
        if g기준 is not None:
            민 = importlib.import_module("엔진.민감도")
            h = 민.손잡이풀기("영구성장률", 가정)
            값들 = []
            for dg in (-0.0025, 0.0025):
                R2 = _결과(민.움직이기(가정, h, dg, 적용), 적용)
                값들.append(_수((R2.get("요약") or {}).get("주당가치")))
            _요 = R0.get("요약") or {}
            _roic, _w = _수(_요.get("영구ROIC")), _수(_요.get("영구기간WACC"))
            if None not in 값들 and abs(값들[1] - 값들[0]) <= 1e-6 * max(abs(값들[0]), 1.0):
                목록.append("  %s — 영구 g ±0.25%%p 에 주당가치가 거의 안 움직입니다(영구 ROIC %s = 영구 WACC %s — "
                            "초과수익 0 이라 성장이 값을 만들지도 깎지도 않습니다)" % (적용, _퍼(_roic), _퍼(_w)))
            elif None not in 값들:
                if 값들[1] < 값들[0]:
                    경보.append(
                        "  **[%s] 성장이 가치를 깎는 구간입니다** — 영구 g +0.25%%p 에 "
                        "주당가치가 %s → %s 로 내려갑니다.PLACE_N"
                        "    영구 ROIC < WACC 신호입니다(자본비용을 못 버는 마진에서는 "
                        "성장할수록 손해).PLACE_N"
                        "    이 구간에서 성장·증설을 유지하는 가정은 모순이니 **g 를 낮추거나 "
                        "영구기간 영업이익률을 재검토**하십시오"
                        % (적용, "{:,.0f}".format(값들[0]), "{:,.0f}".format(값들[1])))
                else:
                    목록.append("  %s — 영구 g ±0.25%%p 에 주당가치가 순방향으로 움직입니다"
                                " (성장이 가치를 만드는 구간)" % 적용)
    except Exception as e:
        목록.append("  임계 판정 실패: %s" % e)

    for 표 in (오류, 경보):
        for i, 글 in enumerate(표):
            표[i] = 글.replace("PLACE_N", chr(10))
    return 오류, 경보, 목록



def _문장자르기(x, n=28):
    t = ("%s" % (x or "")).strip()
    return t[:n]


def _한시적매출대조(가정, 경보, 목록):
    """S2-12 — **`손익반영 = s` 는 「그 돈이 구분 s 의 매출 안에 이미 들어 있다」는 뜻이다.** 엔진은 한시적 흐름을 매출에서 떼지 않는다 —
    사람이 구분 s 의 매출 경로에 그 돈을 넣고(단가 · 매출 조정 계수), 금액 줄(A-395 · 404 · 413)은 영구 EBIT 에서 뺄 몫(마지막 예측 열 연환산)을
    알려 줄 뿐이다. 그래서 둘이 어긋나면 끝난 돈이 영구화된다(법이 2030 에 끝났는데 매출 경로에는 2031 에도 남아 있으면 395 의 2031 = 0 →
    영구에서 뺄 것도 0). 세 시나리오에서 본다.
      (가) 흐름 금액 ≤ 구분 s 매출(같은 열) — 넘으면 경보(매출에 안 넣은 돈을 영구에서 빼는 것이다)
      (나) 흐름이 0 이 된 첫 열에 구분 s 의 연환산 매출이 앞 열 흐름(연환산)의 절반도 안 줄었으면 경보 — 끝난 돈이 매출에 남았다"""
    p = _판(가정)
    for f, 금액줄 in _한시적흐름(가정):
        s = f.get("손익반영")
        try:
            s = int(s)
        except (TypeError, ValueError):
            continue                                         # 손익반영 = 없음 — 매출 밖(FCFF 에 직접)
        이름 = ("%s" % (f.get("이름") or "흐름 %s" % f.get("번호"))).strip()
        넘, 남 = [], []
        for 시 in 시나리오목록:
            try:
                R = _결과(가정, 시)
            except Exception:                                # noqa: BLE001
                return
            m = _줄(R, "4.Sales", 금액줄행.get(s, ""))
            a = p.A(금액줄, 시)
            for i in p.예측:
                if (a[i] or 0) > (m[i] or 0) + 1e-6:
                    넘.append("%s %s 흐름 %s > 매출 %s" % (시, p.열글(i), _금액(a[i], 가정), _금액(m[i] or 0, 가정)))
            for i in p.예측[1:]:
                j = i - 1
                if (a[j] or 0) > 0 and not (a[i] or 0) and p.년[i] and p.년[j]:
                    줄음 = (m[j] or 0) / p.년[j] - (m[i] or 0) / p.년[i]
                    if 줄음 < 0.5 * a[j] / p.년[j]:
                        남.append("%s %s(흐름 %s → 0, 매출 연환산 %s → %s)" % (시, p.열글(i), _금액(a[j] / p.년[j], 가정),
                                                                      _금액((m[j] or 0) / p.년[j], 가정), _금액((m[i] or 0) / p.년[i], 가정)))
        if 넘:
            경보.append("  한시적 현금흐름 「%s」(손익반영 = 구분 %d, 금액 %s행)이 그 구분 매출보다 큽니다 — %s. 손익반영 = s 는 그 돈이 구분 s 매출 안에 "
                        "들어 있다는 뜻입니다. 매출 경로에 넣지 않았으면 손익반영 = 없음 으로 두고 FCFF 에 직접 더합니다"
                        % (이름[:30], s, 금액줄, " · ".join(넘[:3])))
        if 남:
            경보.append("  **한시적 현금흐름 「%s」가 끝났는데 구분 %d 의 매출이 그만큼 줄지 않았습니다 — 끝난 돈이 매출에 남아 영구화됩니다.** %s. "
                        "법 · 계약이 끝나는 열부터 그 구분의 매출 경로(단가 · 매출 조정 계수)에서 그 돈을 걷습니다"
                        % (이름[:30], s, " · ".join(남[:3])))
        if not 넘 and not 남:
            목록.append("  한시적 현금흐름 「%s」 — 구분 %d 매출 안에 있고(금액 ≤ 매출), 끝난 뒤 매출이 그만큼 줄었습니다" % (이름[:30], s))


def 모순장부검사(가정, 라벨):
    """㉟ — **모순 장부와 외부 제약 — 두 값이 갈린 자리를 고르지 않고 올렸고, 법령의 끝을 영구화하지 않았나.**

    2026-09-09 신설(아스트라 RBAE 대조). 경보는 흘러가고 장부는 남는다 — `_raw/모순장부.json` 을
    읽어 **승격 없는 critical 미해결**을 오류로, high 미해결을 경보로 낸다. 장부가 없으면 목록으로
    「만들라」고만 적는다(회귀 기준선 두 벌은 장부가 없어도 통과해야 한다).
    외부 제약(`가정.제약`)은 `영구화금지` 법령의 적용행 영구 열이 0 인지 직접 잰다 — 장부 M-08 과
    같은 검사를 장부 없이도 한 번 더 한다.
    """
    import os as _os
    오류, 경보, 목록 = [], [], []
    길 = _os.path.join(_os.getcwd(), "_raw", "모순장부.json")
    장부 = None
    if _os.path.exists(길):
        try:
            장부 = json.load(open(길, encoding="utf-8"))
        except Exception as e:
            경보.append("  모순장부.json 을 읽지 못했습니다: %s" % e)
    if not 장부:
        목록.append("  장부 없음 — `python 스크립트/모순장부.py 가정.json` 으로 만드십시오"
                    "(두 값이 갈린 자리를 고르지 않고 올리는 곳)")
    else:
        # **요약 칸을 믿지 않고 항목을 직접 센다** (2026-09-13 펄어비스 실측).
        # 옛 판은 `요약` 의 밑줄 키(`high_미해결`)만 읽었는데, 회차가 요약을 손으로 고치며
        # 띄어 쓴 키(`high 미해결`)로 적자 **항목 넷을 찍어 놓고 요약은 「high 미해결 0 ·
        # 장부 0건」**을 냈다. 셈은 `모순장부.py 요약()` 과 같은 규칙 — **「해소」가 아니면
        # 미해결로 센다**(부분해결 포함). 부분해결은 따로 몇 건인지 밝힌다.
        항목들 = [it for it in (장부.get("항목") or []) if isinstance(it, dict)]
        셈 = {"전체": len(항목들), "critical_미해결": 0, "승격없는_critical": 0,
             "high_미해결": 0, "해소": 0, "부분해결_critical": 0, "부분해결_high": 0}
        for it in 항목들:
            상 = ("%s" % (it.get("상태") or "")).strip()
            중 = ("%s" % (it.get("중요도") or "")).strip()
            if 상 == "해소":
                셈["해소"] += 1
                continue
            if 중 == "critical":
                셈["critical_미해결"] += 1
                if 상 == "부분해결":
                    셈["부분해결_critical"] += 1
                if not ("%s" % (it.get("승격") or "")).strip():
                    셈["승격없는_critical"] += 1
            elif 중 == "high":
                셈["high_미해결"] += 1
                if 상 == "부분해결":
                    셈["부분해결_high"] += 1

        # 상태별로 편다 — CLAUDE.md 레터 조문 「상태가 셋 이상이면 뭉치지 말고 상태별로 편다」.
        # 동결·오류 판정에 쓰는 「미해결」은 해소가 아닌 것 전부(미해결+부분해결)라 그 합도 함께 적는다.
        목록.append("  장부 %d건 — critical: 미해결 %d · 부분해결 %d (승격 없음 %d) · "
                    "high: 미해결 %d · 부분해결 %d · 해소 %d  ← 항목을 직접 센 값 "
                    "(판정의 「미해결」 = 해소 아닌 것 전부: critical %d · high %d)"
                    % (셈["전체"], 셈["critical_미해결"] - 셈["부분해결_critical"], 셈["부분해결_critical"],
                       셈["승격없는_critical"], 셈["high_미해결"] - 셈["부분해결_high"],
                       셈["부분해결_high"], 셈["해소"], 셈["critical_미해결"], 셈["high_미해결"]))
        # 장부 요약 칸과 맞대 본다 — 밑줄 키·띄어 쓴 키 둘 다 읽는다
        q = 장부.get("요약") or {}

        def _요(*키들):
            for 키 in 키들:
                if _수(q.get(키)) is not None:
                    return int(_수(q.get(키)))
            return None
        적힌 = {"critical_미해결": _요("critical_미해결", "critical 미해결"),
               "승격없는_critical": _요("승격없는_critical", "승격 없는 critical 미해결",
                                   "승격 없는 critical"),
               "high_미해결": _요("high_미해결", "high 미해결"),
               "해소": _요("해소"), "전체": _요("전체", "항목")}
        _쪼갬 = {"critical_미해결": 셈["부분해결_critical"], "high_미해결": 셈["부분해결_high"]}
        어긋 = ["%s 요약 %d ↔ 항목 셈 %d%s" % (k.replace("_", " "), v, 셈[k],
                                          ("(미해결 %d + 부분해결 %d)" % (셈[k] - _쪼갬[k], _쪼갬[k]))
                                          if _쪼갬.get(k) else "")
               for k, v in 적힌.items() if v is not None and v != 셈[k]]
        if 어긋:
            줄 = ("  **장부 요약 칸이 항목 셈과 다릅니다** — %s.\n"
                  "    요약 칸은 완주기록·레터가 그대로 옮기는 숫자입니다. 「부분해결」을 미해결에서"
                  " 뺐거나 요약을 손으로 고친 자리입니다 — `python 스크립트/모순장부.py` 로 요약을"
                  " 다시 내십시오" % " · ".join(어긋))
            # critical 쪽이 어긋나면 동결 조건(승격 없는 critical 0)을 잘못 읽게 하므로 경보
            (경보 if any(k in ("critical_미해결", "승격없는_critical") and v is not None and v != 셈[k]
                        for k, v in 적힌.items()) else 목록).append(줄)
        for it in 항목들:
            if it.get("상태") == "해소":
                continue
            _상 = ("%s" % (it.get("상태") or "")).strip()
            글 = "  **[%s · %s%s] %s** — 닿는 행 %s" % (
                it.get("ID"), it.get("중요도"), (" · " + _상) if _상 and _상 != "미해결" else "",
                it.get("충돌"), ",".join(it.get("닿는_행") or []) or "-")
            if it.get("중요도") == "critical":
                if (it.get("승격") or "").strip():
                    경보.append(글 + "PLACE_N    승격: %s" % it["승격"])
                else:
                    오류.append(글 + "PLACE_N    **승격이 없습니다** — 해소·시나리오·확인불가·모니터링 중 하나로 닫아야"
                               " 완주입니다(스킬 /모순장부)")
            elif it.get("중요도") == "high":
                경보.append(글)
            else:
                목록.append(글)
    # 법령과 원가 울타리(`제약.원가[]`)를 같은 방식으로 잰다(2026-10-16, S1 리뷰 — 기한이 정해진 의무 투자 · 한시 감면이
    # 영구 열에 남아도 울지 않던 자리). 원가 울타리에 적용행이 없으면 닿는 원가 줄만 적고 경보로 사람에게 넘긴다
    for 법 in [x for k in ("법령", "원가") for x in ((가정.get("제약") or {}).get(k) or []) if isinstance(x, dict)]:
        if not 법.get("영구화금지"):
            continue
        if 법 in ((가정.get("제약") or {}).get("원가") or []) and not str(법.get("적용행") or "").strip():
            경보.append("  **원가 울타리 %s — 영구화금지인데 적용행이 없습니다(닿는 원가 줄 %s).** 기한이 있는 돈이면 한시적 현금흐름으로"
                        " 담거나 적용행(가정 번호)을 적어 영구기간 열을 잴 수 있게 하십시오"
                        % (법.get("이름") or "(이름 없음)", 법.get("닿는_원가줄") or "?"))
            continue
        # 적용행이 빈 법령은 값에 안 실린 「제약의 기록」이다(반영=False, SK하이닉스 CHIPS 실측).
        # 빈 문자열에 .split()[0] 을 걸면 IndexError 로 검사가 통째로 죽는다 — 목록으로 적고 넘어간다.
        _적 = str(법.get("적용행") or "").strip()
        if not _적:
            목록.append("  %s — 적용행이 비어 있다(값 미반영 선언). 영구화금지는 볼 것이 없다"
                        % (법.get("이름") or "(이름 없음)"))
            continue
        if 법.get("반영") is False:                            # 1.1.8 — 값에 싣지 않은 법령은 적용행이 무엇이든(번호 · 설명 글) 영구 열에 그 돈이 없다
            목록.append("  %s — 값 미반영 선언(반영 false). 영구화금지는 볼 것이 없다 · 적용행 「%s」 은 참고로만"
                        % (법.get("이름") or "(이름 없음)", _적[:30]))
            continue
        행 = _적.split()[0].split("(")[0].strip()
        # **유한 흐름으로 담겼으면 그 흐름의 영구 열을 직접 본다.** 종전에는 「담겼다」는 사실만 보고
        # 넘어가서, 비병합(병합행 "") 흐름의 영구 열에 값이 남아 있어도 「0 확인」으로 적었다
        # (2026-09-09 _검사시험 ㉟ 픽스처가 잡음 — 확인하지 않은 것을 확인했다고 적던 자리).
        p = _판(가정)
        묶인 = [(f, 금액줄) for f, 금액줄 in _한시적흐름(가정)
              if ("%s" % (f.get("이름") or "")).strip() == ("%s" % (법.get("이름") or "")).strip()
              or ("%s" % (f.get("태그") or "")).strip() == ("%s" % (법.get("이름") or "")).strip()
              or 행 == 금액줄 or 행 in ("유한현금흐름", "유한", "P절", "한시적현금흐름", "한시적")]
        if 묶인:
            샌것 = []
            for f, 금액줄 in 묶인:
                for 시 in 시나리오목록:
                    v = p.A(금액줄, 시)[p.영구]
                    if (v or 0) != 0:
                        샌것.append("%s(%s 영구기간 %s)" % (_문장자르기(f.get("이름")), 시, v))
            if 샌것:
                오류.append("  **법령이 끝을 정한 돈(%s)이 한시적 현금흐름의 영구기간 열에 남아 있습니다 — %s.**PLACE_N"
                            "    한시적 흐름의 영구기간 열은 비어 있어야 합니다. 예측 열은 경로(잔존비율)대로 줄이고,"
                            " 창 뒤에 남는 회수는 잔여액 표(399 꼴)에 적어 별도 현가로 더하십시오"
                            % (법.get("이름", ""), " · ".join(샌것)))
            else:
                목록.append("  제약 %s — 한시적 현금흐름으로 담겼고 영구기간 열 0 확인(적용행 %s)"
                            % (법.get("이름", ""), 행))
            continue
        있다 = bool(행) and 행.isdigit() and p.벌(행) is not None
        v영 = p.A(행, _적용시나리오(가정))[p.영구] if 있다 else None
        if 있다 and _율행인가(행):
            # S6-13 — 변동률 행(단위원가 변동률 7k2 · 가격지수 98 · 102 · 106 · 판매단가 변동률 6s3 · 인원 501 · 임금 504)의 영구 열 0 은
            # 「변동 없음」이지 「한시 부담 끝」이 아니다. 경로 끝 해 뒤의 누적 수준이 경로 시작 전 수준(1)으로 돌아왔는지를 잰다
            경로 = 법.get("경로") if isinstance(법.get("경로"), dict) else {}
            해들 = sorted(int(k) for k in 경로 if "%s" % k and ("%s" % k).isdigit() and len("%s" % k) == 4)
            연도 = _예측연도(가정)
            창 = sorted(i for y in 연도 if 해들 and 해들[0] <= y <= 해들[-1] + 1 for i in 연도[y]) if 해들 else []
            시 = _적용시나리오(가정)
            율 = p.A(행, 시)
            수준 = 1.0
            for i in 창:
                수준 *= 1.0 + (율[i] or 0.0)
            근 = (가정.get("근거") or {}).get(행)
            근글 = " ".join("%s" % x for x in 근) if isinstance(근, (list, tuple)) else "%s" % (근 or "")
            글 = ("  제약 %s — 적용행 %s 은 변동률 행이다(영구 열 0 = 변동 없음 — 한시 부담의 끝을 영구 열로 잴 수 없다). 경로 %s 의 열에서 누적 수준 %.4f 배"
                 % (법.get("이름", ""), 행, ("%d~%d" % (해들[0], 해들[-1] + 1)) if 해들 else "(연도 없음)", 수준))
            if not 창:
                경보.append(글 + " — 경로 연도가 예측 열에 닿지 않아 되돌림을 재지 못했다. 한시 부담이면 그 수준이 경로 뒤 1 로 돌아오게 적고 근거에 쓴다")
            elif abs(수준 - 1.0) > 0.005 and not any(w in 근글 for w in ("되돌", "복귀", "원상", "회복")):
                경보.append(글 + " — 1 로 돌아오지 않았다. 한시 할증 · 감면이면 끝난 뒤 수준을 되돌리고(음의 변동률), 물가 · 추세가 섞였으면 그 몫을 근거 %s 에 가른다" % 행)
            else:
                목록.append(글 + " — 되돌림 확인(또는 근거에 적음)")
            continue
        if 있다 and (v영 or 0) != 0:
            오류.append("  **법령이 끝을 정한 돈(%s)이 %s행 영구기간 열에 %s 로 남아 있습니다.**PLACE_N"
                        "    예측 열은 경로(잔존비율)대로 줄이고 영구기간 열은 0 — 단계축소 구간 회수는 한시적 현금흐름으로"
                        " 따로 더하십시오" % (법.get("이름", ""), 행, v영))
        elif 있다:
            목록.append("  제약 %s — 영구기간 열 0 확인(적용행 %s)" % (법.get("이름", ""), 행 or "?"))
        else:
            경보.append("  **제약 %s — 영구화금지인데 적용행 %s 을 못 찾아 확인하지 못했습니다.**"
                        " 적용행에 가정 번호나 「한시적현금흐름」을 적으십시오"
                        % (법.get("이름", ""), 행 or "(빈칸)"))
    for 표 in (오류, 경보):
        for i, 글 in enumerate(표):
            표[i] = 글.replace("PLACE_N", chr(10))
    _한시적매출대조(가정, 경보, 목록)                       # S2-12 — 손익반영 = s 인 한시적 흐름과 그 구분 매출
    return 오류, 경보, 목록



def 사이클종착검사(가정, 라벨=None):
    """㊲ — **사이클 산업인데 정점 마진을 영구화하지 않았나.** (2026-09-09 신설 · 2026-10-17 S8-02 다시 씀)

    v13 에서 영구기간 영업이익률은 영구기간 열(최종 예측 연도 × (1 + g))의 결과다. 원가 줄 가정의 영구기간 열을 손대지 않으면 마지막 예측 해
    마진이 그대로 영구화된다 — 성장 뒤 안정화하는 회사에는 맞지만 **순환주기 산업에서는 금기**다(예측기간의 끝이 사이클의 어디였느냐가
    값 전체를 지배한다).

    사이클인지는 **사이클 판정 하나**(`_사이클` — A3 국면 · 덧표지 · 관측 시계열 S6 신호 · 옛 부호 전환 자)로 잰다. 사이클이면 두 가지를 본다.
      ① 정점 영구화 — 종착 마진이 마지막 예측 해와 같고(±0.2%p) 그 해가 창 안의 정점 부근(창 최고 − 2%p 위)이면 경보
      ② 정상 수준과의 거리 — 종착 마진이 정상 마진(213 → 운영 동종 정상 영업이익률 → 사이클 평균 — `_종착기준`)보다 2%p 넘게 높으면 경보
    막지 않는다(오류는 ⑥ 이 5%p 문턱으로 낸다). 처방은 v13 이다 — 영구기간 열의 원가 줄 가정(비율 · 계수 · 정상 수준 판매단가)을 사이클
    평균으로 되돌리고 그 계단의 크기와 이유를 213 근거 칸에 적는다(`구조.영구가치.정상화계단 = 예`). 213 에 적어 곱하는 길(영구이익기준 = 입력)은
    옛 파일을 옮길 때만 쓴다.
    """
    오류, 경보, 목록 = [], [], []
    판 = _사이클(가정)
    if 판.get("사이클") is None:
        목록.append("  재료 없음 — 사이클 판정 재료(A3 국면 · 덧표지 · 네 해 이상의 관측 영업이익률 — 관측 키 · 앵커 · A3 · 원천 13번)가 "
                    "없습니다%s" % ((" — " + " · ".join(판.get("근거"))) if 판.get("근거") else ""))
        return 오류, 경보, 목록
    시계 = 판.get("시계열") or {}
    목록.append("  사이클 판정 — %s (관측 %s · %d해%s)" % (
        "사이클" if 판["사이클"] else "사이클 아님", 시계.get("출처", "-"), len(시계.get("해") or []),
        (" · " + " · ".join(판["근거"])) if 판.get("근거") else ""))
    if not 판["사이클"]:
        목록.append("  사이클 신호가 없어 순환주기 판정을 하지 않습니다(성장 · 안정 회사 — 정상 수준 대조는 ⑥ 이 합니다)")
        return 오류, 경보, 목록
    p = _판(가정)
    끝 = p.끝
    처방 = ("PLACE_N    영구기간 열의 원가 줄 가정(비율 · 계수 · 정상 수준 판매단가 6s6)을 사이클 평균으로 되돌리고, 그 계단의 크기와 이유를"
          "PLACE_N    12번 213 근거 칸에 적은 뒤 `구조.영구가치.정상화계단 = 예` 로 선언합니다. 정상 마진 후보는"
          "PLACE_N    `python 스크립트/정상화.py <가정.json>` 이 냅니다(자기 사이클 매출가중 · 운영 동종 정상 마진 — 고르지 않습니다)")
    for 시 in ("비관", "기준", "낙관"):
        try:
            R = _결과(가정, 시)
        except Exception:                                    # noqa: BLE001
            continue
        매 = _줄(R, "4.Sales", "54")
        영 = _줄(R, "6.SG&A", "22")
        if not 매[끝] or 영[끝] is None:
            continue
        마지막 = 영[끝] / 매[끝]
        종착 = _영구이익률값(가정, R)                      # 영구기간 영업이익률(2번 42) — 영구열이면 영구기간 열의 결과
        if 종착 is None:
            continue
        # **이 검사가 무서워하는 것은 「같다」가 아니라 「정점을 영구화한다」이다.** 창 안에서 마진을 이미 걸어 내렸으면 마지막 해는
        # 정점이 아니라 평탄화의 끝이다(실측 마이크론 2026-05-28: 창 첫 열 81.0% → 마지막 열 26.0%).
        창 = [영[i] / 매[i] for i in p.예측 if 매[i] and 영[i] is not None]
        창최고 = max(창) if 창 else None
        정점부근 = 창최고 is None or 마지막 >= 창최고 - 0.02
        정상, 정상출 = _종착기준(가정, 시)
        if abs(종착 - 마지막) < 0.002 and 정점부근:
            경보.append(
                "  **%s — 사이클 회사인데 종착 마진(%.2f%%)이 마지막 예측 해(%.2f%%)와 같고, 그 해가 **창 안의 정점 부근**입니다"
                "(창 최고 %.2f%%).**PLACE_N    정점 부근 마진의 영구화는 순환주기 기업 평가에서 피하는 자리입니다%s%s"
                % (시, 종착 * 100, 마지막 * 100, (창최고 * 100) if 창최고 is not None else float("nan"),
                   ("PLACE_N    정상 마진 %s %.2f%% 대비 %+.2f%%p" % (정상출, 정상 * 100, (종착 - 정상) * 100)) if 정상 is not None else "",
                   처방))
        elif 정상 is not None and 종착 - 정상 > 0.02:
            경보.append(
                "  **%s — 사이클 회사의 종착 마진 %.2f%% 가 정상 마진(%s) %.2f%% 보다 %.2f%%p 높습니다.**PLACE_N"
                "    영구에 사이클 평균보다 높은 마진을 둔 것입니다(정점 이익의 영구화 의심)%s"
                % (시, 종착 * 100, 정상출, 정상 * 100, (종착 - 정상) * 100, 처방))
        elif abs(종착 - 마지막) < 0.002:
            목록.append("  %s — 종착 %.2f%% 가 마지막 예측 해와 같지만 **창 안에서 이미 평탄화를 마쳤습니다**(창 최고 %.2f%% → 마지막 %.2f%%)"
                        % (시, 종착 * 100, 창최고 * 100, 마지막 * 100))
        else:
            목록.append("  %s — 마지막 예측 해 %.2f%% → 종착 %.2f%% (정규화 계단 %+.2f%%p)%s"
                        % (시, 마지막 * 100, 종착 * 100, (종착 - 마지막) * 100,
                           (" · 정상 마진 %s %.2f%%" % (정상출, 정상 * 100)) if 정상 is not None else " · 정상 마진 재료 없음"))
    for 표 in (오류, 경보, 목록):
        for i, 글 in enumerate(표):
            표[i] = 글.replace("PLACE_N", chr(10))
    return 오류, 경보, 목록


def 수주운전자본검사(가정, 라벨=None):
    """㊳ — **수주업인데 순운전자본을 정률로 묶지 않았나.** (2026-09-09 신설)

    진행률 인식 회사는 운전자본이 매출채권·재고가 아니라 **계약자산·계약부채**에 있다.
    둘은 각각 **수주잔고**와 **신규수주**를 따라가지 계약자산이 매출을 따라가지 않는다.
    한 비율로 묶으면 수주가 꺾이는 세계에서 선수금이 마르는 효과가 통째로 소거된다.

    수주업 여부는 **원천 15·43행에 계약자산·계약부채가 크게 있는지**로 잰다(매출의 20% 이상).
    그때 190행이 열마다 같은 값이면 경보다.
    """
    오류, 경보, 목록 = [], [], []
    p = _판(가정)

    def 원(r):
        return p.H기준일(r)
    # 평가기준일 열의 매출 — 누계(반기) 열이면 연환산해 잔액과 같은 자로 견준다
    매출 = (원(62) / p.년[p.기준일]) if (원(62) and p.년[p.기준일]) else 원(62)
    유자, 유부 = 원(15), 원(43)
    if not 매출 or (유자 is None and 유부 is None):
        목록.append("  재료 없음 — 원천 15·43(기타유동자산·부채)이 없어 수주업 판정을 못 합니다")
        return 오류, 경보, 목록
    큰쪽 = max(abs(유자 or 0), abs(유부 or 0))
    비 = 큰쪽 / 매출
    목록.append("  기타유동자산 %s · 기타유동부채 %s · 연환산 매출 대비 최대 %.1f%%"
                % (_금액글(유자), _금액글(유부), 비 * 100))
    if 비 < 0.20:
        # 「20%」 뒤에 `%%` 를 두면 포맷을 안 거친 글이라 「20%%」로 찍힌다
        목록.append("  매출의 20% 미만이라 수주업 운전자본 판정을 하지 않습니다")
        return 오류, 경보, 목록

    # **구독 선수금은 수주 계약부채가 아니다** (2026-09-13 세일즈포스 실측).
    # 둘 다 「계약부채」 태그로 공시되지만 구독 이연수익은 **연 단위 청구**를 따라가고 청구는
    # 매출과 같이 움직인다 — 정률이 틀린 것이 아니다. 옛 판은 매출 대비 크기만 보고
    # 「수주잔고·신규수주」 문장을 냈고, 그 문장이 레터 부록 E 까지 갔다.
    # 신호는 둘에서 읽는다 — 원천 43 의 계정 이름(원천근거 첫 칸)과 190 근거 칸의 글.
    원근 = ((가정.get("원천근거") or {}).get("43") or [""])
    계정글 = ("%s" % (원근[0] if isinstance(원근, list) and 원근 else 원근 or "")).strip()
    근190 = " ".join("%s" % (x or "") for x in ((가정.get("근거") or {}).get("190") or [])).strip()
    구독말 = ("구독", "이연수익", "선수수익", "unearned", "deferred revenue", "subscription")
    수주말 = ("수주", "진행률", "미청구", "초과청구", "공사")
    구독신호 = any(k in (계정글 + " " + 근190).lower() for k in 구독말) and \
        not any(k in 계정글 for k in 수주말)
    구독사유 = 근190 if (구독신호 and len(근190) >= 40
                        and any(k in 근190.lower() for k in 구독말)) else ""
    if 구독사유:
        # 인용은 구독 말이 든 칸을 고른다 — 첫 칸은 대개 계산식이라 사유가 안 보인다
        _칸들 = [("%s" % (x or "")).strip() for x in ((가정.get("근거") or {}).get("190") or [])]
        _고른 = [x for x in _칸들 if any(k in x.lower() for k in 구독말)]
        구독사유 = (max(_고른, key=len) if _고른 else 근190)      # 가장 긴 칸이 대개 사유 문장이다

    # **플랫폼 · 핀테크의 예수금은 수주 계약부채가 아니다** (S10R1-N6 — 리뷰 1 3절 거짓 양성: 결제 · 중개 회사의 기타유동부채(이용자 · 가맹점
    # 예수금)에 「수주잔고 · 신규수주」 문장이 났다). 신호 — A3 유형 판정에 「플랫폼 · 중개」 · 「금융」이 있거나 원천 43 계정 · 190 근거에 예수 낱말.
    예수말 = ("예수", "예치", "고객 자금", "고객자금", "충전금", "선불", "deposit", "customer funds", "payable to merchants")
    _원, _ = _갈래파일("동인원천.json")
    _유형 = [("%s" % x) for x in ((((_원 or {}).get("유형") or {}).get("판정")) or [])] if isinstance(_원, dict) else []
    예수신호 = (any(("플랫폼" in t or t.startswith("금융")) for t in _유형) or
              any(k in (계정글 + " " + 근190).lower() for k in 예수말)) and not any(k in 계정글 for k in 수주말)
    if p.구["운전자본"]["기타"] != "사용":
        목록.append("  기타 순운전자본을 쓰지 않습니다(구조.운전자본.기타 = 미사용) — 190행을 읽지 않아 정률 판정을 하지 않습니다")
        return 오류, 경보, 목록
    for 시 in ("비관", "기준", "낙관"):
        if p.벌("190") is None:
            break
        v = p.A("190", 시)
        예측 = [v[i] for i in p.예측 if v[i] is not None]
        if len(예측) < 2:
            continue
        if max(예측) - min(예측) < 1e-9:
            if 구독사유:
                목록.append(
                    "  %s — 기타유동부채가 매출의 %.0f%% 이고 190행이 열마다 같습니다(%.2f%%). "
                    "구독 선수금 구조라는 사유가 190 근거 칸에 적혀 있어 수주업 판정을 하지 않습니다"
                    " (적힌 사유: 「%s」)" % (시, 비 * 100, 예측[0] * 100, 구독사유[:120]))
            elif 예수신호 and not 구독신호:
                경보.append(
                    "  **%s — 기타유동부채(%s)가 매출의 %.0f%% 인데 순운전자본 비율(190행)이 열마다 같습니다(%.2f%%).**\n"
                    "    유형이 플랫폼 · 핀테크(%s)이거나 계정이 예수금 꼴입니다 — **예수금은 운전자본인가 금융 부채인가**를 먼저 정합니다.\n"
                    "    이용자 · 가맹점에게서 받아 둔 돈(결제 · 충전 · 정산 대기)은 매출이 아니라 거래액 · 결제액을 따라가고, 같은 크기의\n"
                    "    현금(고객 자금 별도 보관)과 짝이면 순차입금 쪽(현금성과 함께 브리지에서 상계)이 맞을 수 있습니다. 운전자본으로 두면\n"
                    "    거래액 성장분의 예수금 증가가 해마다 FCFF 를 늘립니다. 어느 쪽으로 봤는지와 그 비율을 190 근거 칸에 적으십시오"
                    % (시, (계정글[:40] if (계정글 and not 계정글.startswith("[")) else "원천 43"), 비 * 100, 예측[0] * 100, " · ".join(_유형) or "계정 이름"))
            elif 구독신호:
                경보.append(
                    "  **%s — 계약부채(%s)가 매출의 %.0f%% 인데 순운전자본 비율(190행)이"
                    " 열마다 같습니다(%.2f%%).**\n"
                    "    계정 이름으로는 **구독 선수금**으로 보입니다 — 수주잔고가 아니라 청구 주기를\n"
                    "    따라가므로 정률이 맞을 수 있습니다. 다만 청구가 매출과 같이 가는지(갱신율·\n"
                    "    청구 주기 변화)는 사람이 정할 일이니 **그렇게 본 이유를 190 근거 칸에 적으십시오**"
                    % (시, 계정글[:40] or "원천 43", 비 * 100, 예측[0] * 100))
            else:
                경보.append(
                    "  **%s — 계약자산·계약부채가 매출의 %.0f%% 인데 순운전자본 비율(190행)이"
                    " 열마다 같습니다(%.2f%%).**\n"
                    "    수주업의 운전자본은 계약자산이 **수주잔고**를, 계약부채가 **신규수주**를\n"
                    "    따라갑니다 — 정률로 묶으면 수주가 꺾일 때 선수금이 마르는 효과가\n"
                    "    사라져 세 시나리오가 같은 비율을 갖게 됩니다. 190 은 열별 배열이니\n"
                    "    수준을 먼저 세우고 그 열의 연환산 매출로 나눠 넣으십시오.\n"
                    "    구독 선수금처럼 청구가 매출을 따라가는 회사면 **그렇다고 190 근거 칸에 적으십시오**"
                    % (시, 비 * 100, 예측[0] * 100))
        else:
            목록.append("  %s — 190행이 열마다 다릅니다 (%.2f%%~%.2f%%) — 동태로 세웠습니다"
                        % (시, min(예측) * 100, max(예측) * 100))
    return 오류, 경보, 목록


def _손잡이등급(가정, h):
    """손잡이가 움직이는 값의 근거 등급(근거 S칸 맨 앞의 딱지) — 대상 가운데 「판단」이 하나라도 있으면 판단.
    WACC(구간 · 입력)는 3번이 계산하는 값이라 「계산」, 영구이익률가감은 영구이익기준 = 입력이면 213 의 등급 · 영구열이면 「결과」."""
    등급 = []
    for 대상 in h.get("대상") or []:
        대상 = "%s" % 대상
        if 대상.startswith("WACC"):
            등급.append("계산")
            continue
        if 대상 == "영구이익률가감":
            if _영구이익기준(가정) != "입력":
                등급.append("결과")
                continue
            대상 = "213"
        넷 = (가정.get("근거") or {}).get(대상) or []
        등급.append(_딱지(넷[0] if 넷 and isinstance(넷[0], str) else "") or "딱지 없음")
    if "판단" in 등급:
        return "판단"
    return 등급[0] if 등급 else "딱지 없음"


def 손잡이무게검사(가정, 라벨):
    """㊴ — **손잡이의 무게(도구 점검 R-152).** 판단으로 정한 값이 주당가치를 크게 가르나.

    **거친 바퀴의 한 표와 같은 함수 · 같은 잣대(S9-01)** — `거친바퀴.한표` 가 축 후보 · 이름 손잡이 · 분해 파라미터 · 판단 칸을 근거 범위의 양 끝
    (판단 칸 → B1 · B2 근거범위 → 선언 손잡이 범위 · 근거 → 엔진 자 실적 → 운영 동종 · 관측 → 외부 제약 → RONIC 우위 소멸)으로 민다. 범위가 없는
    손잡이는 「범위 없음」(참고 — 엔진 기본 폭)으로 따로 잰다. 변동이 ±10% 를 넘는데 그 값의 근거 등급이 「판단」이면 **경보**(범위 없음이면
    「근거 범위가 없다」를 함께) — 사유는 검토 의견(`검토의견.R-152`)에 적으면 닫힌다. 표는 목록으로 싣는다(적용 시나리오).
    동인 지도 · 동인진단 · 투자능력 · 축배선 · 웹조사(갈래 산출물)가 가정 곁 `_raw/` 에 있으면 함께 읽는다."""
    오류, 경보, 목록 = [], [], []
    시 = _적용시나리오(가정)
    try:
        import 거친바퀴 as _바퀴                                  # noqa: PLC0415
        지도, _ = _갈래파일("동인지도.json")
        진단 = None if 지도 else _갈래파일("동인진단.json")[0]
        F, _ = _갈래파일("투자능력.json")
        웹, _ = _갈래파일("매출스트림_웹조사.json")
        배선곳 = _갈래파일("축배선.json")[1]
        결 = _바퀴.한표(가정, 시, 지도=(_copy.deepcopy(지도) if isinstance(지도, dict) else None), 진단=진단,
                     F=F if isinstance(F, dict) else None, 웹조사=웹 if isinstance(웹, dict) else None,
                     배선=_바퀴.축배선읽기(배선곳) if 배선곳 else None, 가정경로=_가정곳)
    except Exception as e:                                   # noqa: BLE001
        목록.append("  재료 없음 — 거친 바퀴의 한 표를 못 돌렸습니다: %s" % ("%s" % e)[:200])
        return 오류, 경보, 목록
    무거운 = []
    목록.append("  손잡이의 무게 — %s 시나리오 · 거친 바퀴 한 표(근거 범위의 양 끝 — S9-01) · 범위 없는 손잡이는 참고 폭" % 시)
    for 묶, 행들 in (("근거 범위", 결["표"]), ("범위 없음", 결["범위없음"])):
        for 행 in 행들:
            if 행.get("하변화") is None or 행.get("상변화") is None:
                continue
            h = {"대상": 행.get("대상") or []}
            if h["대상"] == ["영구ROIC"]:
                h = {"대상": ["219"]}
            등급 = _손잡이등급(가정, h)
            폭글 = ("[%s, %s]" % tuple("%.4g" % x for x in 행["범위"])) if 행.get("범위") else (행.get("참고폭") or "-")
            목록.append("    %-30s %s %s → %+.1f%% / %+.1f%% · 근거 등급 %s · %s"
                        % ((행.get("이름") or "")[:30], 묶, 폭글, 행["하변화"] * 100, 행["상변화"] * 100, 등급, (행.get("범위출처") or "")[:40]))
            if max(abs(행["하변화"]), abs(행["상변화"])) > 0.10 and 등급 == "판단":
                무거운.append("%s(대상 %s) %s %s → 주당가치 %+.1f%% / %+.1f%%%s"
                              % (행.get("이름"), "·".join("%s" % x for x in h["대상"]), 묶, 폭글, 행["하변화"] * 100, 행["상변화"] * 100,
                                 " — 근거 범위가 없다(참고 폭)" if 묶 == "범위 없음" else ""))
    if 무거운:
        경보.append(
            "  **판단으로 정한 값 %d개가 근거 범위 끝에서 주당가치를 10%% 넘게 움직입니다(R-152).**\n"
            "%s\n"
            "    값을 가르는 손잡이가 사람의 판단에 서 있습니다 — 범위를 좁힐 관측을 더 찾거나(범위가 없으면 E · B1 · C2 로 세웁니다), 그 범위를 고른 까닭과\n"
            "    어느 쪽 끝이 더 그럴듯한지를 검토 의견(`검토의견.R-152`)에 적습니다"
            % (len(무거운), "\n".join("      · " + x for x in 무거운)))
    쏠 = 결.get("쏠림") or {}
    if 쏠.get("신호"):
        경보.append(_검토("  **근거 범위 안 지금 값이 모두 같은 쪽 끝이다 — %s(「판단이 아니라 습관」).** 반대쪽 끝을 안 고른 까닭을 한 줄씩 적는다" % 쏠["글"], "R-152"))
    return 오류, 경보, 목록


def 보조시나리오검사(가정, 라벨):
    """㊾ — **보조 시나리오 정합**(R-163 · S9-09). 보조 시나리오(골 · 회복 · 수주 공백 · 증설 지연 · 출시 지연 류)는 세 시나리오와 같은 잣대로 본다.
    보조마다 (1) 영구가치 비중 문턱(5~6년 85% · 7년 이상 80%) (2) 영구기간 영업이익률 대 종착 마진(엔진 `종착기준읽기` — 5%p 넘으면 경보)
    (3) 마지막 예측 해 영업이익률 대 관측(`관측.대상영업이익률` 최근 일곱 해) — 최저보다 낮으면 경보(왜 과거 최악보다 나쁜가)
    (4) 덧이 민 이야기 묶음 수(엔진 `민감도.이야기묶음`) — 셋 넘으면 경보(보조도 한 이야기다) (5) 바탕 대비 방향 — `방향`(하방 · 상방)을 적었으면
    주당가치 차의 부호와 맞대고, 안 적었으면 목록에 차를 싣는다. 사유는 `검토의견.R-163`."""
    오류, 경보, 목록 = [], [], []
    보조들 = [x for x in (가정.get("보조시나리오") or []) if isinstance(x, dict)]
    if not 보조들:
        목록.append("  보조 시나리오 없음 — 건너뜀(사이클 골 · 회복, 수주 공백, 증설 지연 · 램프 실패, 신작 · 파이프라인 지연 따위가 이 회사에 있으면 세운다)")
        return 오류, 경보, 목록
    민엔 = importlib.import_module("엔진.민감도")
    부엔 = importlib.import_module("엔진.부수")
    계엔 = importlib.import_module("엔진.계산")
    p = _판(가정)
    연수 = len(list(p.예측)) if hasattr(p, "예측") else 5
    문턱 = 0.80 if 연수 >= 7 else 0.85
    관 = [x.get("값") for x in ((가정.get("관측") or {}).get("대상영업이익률") or []) if isinstance(x, dict) and isinstance(x.get("값"), (int, float))][-7:]
    for x in 보조들:
        이름 = x.get("이름") or "(이름 없음)"
        try:
            a, 바탕 = 민엔.보조덧씌우기(가정, x)
            R = 계엔.계산(a, 바탕)
            Rb = 계엔.계산(가정, 바탕)
        except Exception as e:                                  # noqa: BLE001
            오류.append("  보조 「%s」 — 엔진이 셈하지 못했다: %s" % (이름, ("%s" % e)[:160]))
            continue
        S, Sb = R["요약"], Rb["요약"]
        차 = (S["주당가치"] / Sb["주당가치"] - 1) if Sb["주당가치"] else None
        끝 = S.get("마지막예측열")
        매 = R["4.Sales"]["54"].get(끝) if 끝 else None
        끝마진 = (R["6.SG&A"]["22"][끝] / 매) if 매 else None
        묶 = sorted({민엔.이야기묶음(번) for 블 in ("가정", "시점가정", "표") for 번 in (((x.get("덧") or {}).get(블)) or {})})
        목록.append("  보조 「%s」(바탕 %s) — 주당 %s(바탕 대비 %s) · 영구가치 비중 %.1f%% · 영구기간 영업이익률 %.2f%% · 마지막 해 %s · 덧 묶음 %s"
                    % (이름, 바탕, "{:,.0f}".format(S["주당가치"]), ("%+.1f%%" % (차 * 100)) if 차 is not None else "-", S["영구가치비중"] * 100,
                       (S.get("영구기간영업이익률") or 0) * 100, ("%.2f%%" % (끝마진 * 100)) if 끝마진 is not None else "-", " · ".join(묶) or "없음"))
        if S["영구가치비중"] > 문턱:
            경보.append("  보조 「%s」 — 영구가치 비중 %.1f%% 가 문턱 %.0f%% 를 넘는다(네 줄 보고 — 보조도 세 시나리오와 같은 잣대)" % (이름, S["영구가치비중"] * 100, 문턱 * 100))
        try:
            기, 기출처 = 부엔.종착기준읽기(a, 바탕)
        except Exception:                                       # noqa: BLE001
            기, 기출처 = None, None
        if 기 is not None and S.get("영구기간영업이익률") is not None and abs(S["영구기간영업이익률"] - 기) > 0.05:
            경보.append("  보조 「%s」 — 영구기간 영업이익률 %.2f%% 가 종착 마진 %.2f%%(%s)에서 %+.1f%%p 떨어진다(⑥ 과 같은 자 — 보조의 덧이 영구기간 열을 건드렸나 본다)"
                        % (이름, S["영구기간영업이익률"] * 100, 기 * 100, 기출처, (S["영구기간영업이익률"] - 기) * 100))
        if len(관) >= 3 and 끝마진 is not None and 끝마진 < min(관) - 1e-9:
            경보.append("  보조 「%s」 — 마지막 예측 해 영업이익률 %.2f%% 가 관측 최저 %.2f%%(최근 %d해)보다 낮다 — 왜 과거 최악보다 나쁜지 근거에 적는다(⑱ 과 같은 자)"
                        % (이름, 끝마진 * 100, min(관) * 100, len(관)))
        if len([m for m in 묶 if m not in ("할인", "영구성장")]) > 3:
            경보.append("  보조 「%s」 — 덧이 이야기 묶음 %d개(%s)를 민다. 보조도 한 이야기다 — 그 사건이 미는 칸만 덧에 둔다(㉕ 와 같은 자)" % (이름, len(묶), " · ".join(묶)))
        방향 = ("%s" % (x.get("방향") or "")).strip()
        if 방향 in ("하방", "상방") and 차 is not None and ((방향 == "하방") != (차 < 0)):
            경보.append("  보조 「%s」 — 방향을 %s 이라 적었는데 바탕 대비 주당가치가 %+.1f%% — 덧이 이야기와 반대로 민다" % (이름, 방향, 차 * 100))
    return 오류, 경보, 목록


끝근처 = 0.05           # ㊿ — (옛 자 · 값 수준의 상대 5%) S10R1-N4 뒤로는 쓰지 않는다 — 끝 근처는 거친바퀴.범위끝허용(범위 폭 5% · 표시 4자리) 하나다
동종넓힘 = True         # ㊿ — 「관측」 = 자사 실적 ∪ C2 운영 동종(S10-11). 「관측」을 자사 실적만으로 읽으면 False


def 관측밖근거검사(가정, 라벨):
    """㊿ — **관측 밖으로 미는 근거는 외부 제약뿐이다 · 3P 초안 · 우위가 깨지는 지점**(R-164 · S9-08).
    (1) 시나리오 driver 줄(없으면 실제로 갈린 줄)의 비관 · 낙관 값을 엔진 자 관측 범위(거친 바퀴와 같은 자 — 가정 줄의 실적 열 · 엔진이 같은
        정의로 낸 실적 열 · 관측 블록)와 맞댄다. 범위 밖이면 그 줄에 닿는 `제약.원가[]` 항목(적용행 = 그 번호)이 있고 근거 칸이 그 항목(이름 · 조문)을
        가리켜야 한다 — 아니면 경보. 낙관이 관측 끝을 넘으면 같은 급의 근거가 없을 때 경보(「낙관은 관측 안에서 멈춘다」)
    (2) 3P 초안 — Possible = 엔진이 셈하고 영구기간 영업이익률 100% 미만 · 주당 0 이상, Plausible = driver 값이 관측 범위 안이거나 외부 제약 근거가 있다,
        Probable = 기준. 사람이 적은 `3P.시나리오` 와 견주어 도구 초안이 더 낮으면 경보
    (3) 우위가 깨지는 지점 — 비관의 영구 RONIC 이 기준과 같고 영구기간 WACC 보다 높으면(비관에도 초과수익이 영원) 목록에 적고, 비관 이야기에
        우위 · 경쟁 · 해자 낱말이 있으면 경보(그 이야기면 RONIC → 영구 WACC · 종착 마진 → 운영 동종 중앙). 사유는 `검토의견.R-164`."""
    오류, 경보, 목록 = [], [], []
    import 거친바퀴 as _바퀴                                    # noqa: PLC0415 — 같은 자(엔진 자 실적 · 관측 범위)
    민엔 = importlib.import_module("엔진.민감도")
    계엔 = importlib.import_module("엔진.계산")
    try:
        R = {s: 계엔.계산(가정, s) for s in ("비관", "기준", "낙관")}
    except Exception as e:                                      # noqa: BLE001
        목록.append("  재료 없음 — 엔진이 셈하지 못했다: %s" % ("%s" % e)[:120])
        return 오류, 경보, 목록
    제약 = [x for x in ((가정.get("제약") or {}).get("원가") or []) if isinstance(x, dict)]
    근거 = 가정.get("근거") or {}
    밖줄 = {"비관": [], "낙관": []}
    지도, _ = _갈래파일("동인지도.json")
    진단 = None if 지도 else _갈래파일("동인진단.json")[0]
    칸들 = _바퀴._판단칸모음(지도 if isinstance(지도, dict) else None, 진단 if isinstance(진단, dict) else None)
    잰 = {"비관": [], "낙관": []}
    못잰 = {"비관": [], "낙관": []}
    for 쪽 in ("비관", "낙관"):
        이 = ((가정.get("시나리오이야기") or {}).get(쪽) or {})
        이 = 이 if isinstance(이, dict) else {}
        줄들 = ["%s" % x for x in (이.get("driver") or [])]
        if not 줄들:
            줄들 = sorted({r for k, v in 민엔.시나리오갈림(가정, (쪽,)).items() if k not in ("할인", "영구성장") for r in v}, key=lambda x: (len(x), x))
        for r in 줄들:
            if not r.isdigit():
                continue
            if r == "213":                                         # S10-11 — 영구 마진은 종착 · 동종의 자(⑥ · ㊼)가 본다 — 자사 몇 해 범위에 묶지 않는다
                목록.append("  %s — A-213(영구기간 영업이익률)은 ⑥ 종착 마진 · ㊼ 운영 동종 띠가 본다(자사 관측 몇 해에 묶지 않는다 — 다모다란 목표 마진)" % 쪽)
                continue
            범, 출 = _바퀴.줄근거범위(가정, r, R["기준"], "기준", 칸들, 가정경로=_가정곳)  # 거친 바퀴 한 표와 같은 자(S9-01 · 통계 제안 2026-10-21)
            if 범 is None:
                못잰[쪽].append(r)
                continue
            값 = _바퀴._열값들(가정, r, 쪽) or [v for v in [_바퀴._시점값(가정, r, 쪽)] if isinstance(v, (int, float))]
            if not 값:
                continue
            잰[쪽].append(r)
            # S10-11 — 운영 동종 범위(C2 — 같은 지표가 있을 때)로 넓힌다: 「외부 제약만」은 자사 관측과 동종을 둘 다 넘을 때만
            동, 동출 = _바퀴._관측범위(가정, r)
            if 동종넓힘 and 동 and 동출 and 동출 != 출:
                범 = (min(범[0], 동[0]), max(범[1], 동[1]))
                출 = "%s ∪ %s" % (출, 동출)
            밖 = [v for v in 값 if v < 범[0] - 1e-9 or v > 범[1] + 1e-9]
            if not 밖:
                continue
            # S10R1-N4 — 끝 근처는 거친 바퀴와 같은 자(`범위끝허용` — 범위 폭의 5% · 표시 4자리)다. 값 수준의 상대 5% 는 원가율 0.8 에 ±4%p 를 주어
            # 영업이익률 몇 % 회사의 이익률을 절반 넘게 바꾸는 낙관을 「끝의 탐색」으로 넘겼다. S10R2-N1 — 표시 4자리 한 단위는 소수 눈금만(연도 · 정수 눈금은 폭 5% 만)
            허 = _바퀴.범위끝허용(범[0], 범[1], _바퀴.가정칸척도(r), 값)
            가까운 = [v for v in 밖 if min(abs(v - 범[0]), abs(v - 범[1])) <= 허]
            if len(가까운) == len(밖):                              # 범위 끝에서 허용폭 안 — 관측 끝의 탐색이다(목록)
                목록.append("  %s — A-%s 값 %s 이 관측 범위 [%.4g, %.4g](%s) 끝 근처(허용폭 %.4g — 범위 폭의 %.0f%% · 표시 4자리 안) — 관측 끝의 탐색으로 본다"
                            % (쪽, r, " · ".join("%.4g" % v for v in 밖[:3]), 범[0], 범[1], 출, 허, _바퀴.끝허용폭 * 100))
                continue
            _먼 = max(밖, key=lambda v: min(abs(v - 범[0]), abs(v - 범[1])))
            _차 = (_먼 - 범[1]) if _먼 > 범[1] else (_먼 - 범[0])
            _원 = _바퀴.원가율글(r, _차, _바퀴._실적영업이익률(가정))
            # S10R2-N4(2026-10-18 결정) — 값 영향 문턱: 원가율 줄은 끝 차 ÷ 영업이익률, 그 밖은 밖의 값을 범위 끝으로 옮겼을 때의 주당가치 차.
            # 문턱(`거친바퀴.값영향문턱` 5%) 미만이면 경보 · 3P 강등 대신 목록 — 진짜 이탈(실측 57%)이 0.1% 짜리와 섞여 묻히지 않게
            _영향, _영향글 = _값영향(가정, r, 쪽, 범, _차, R[쪽], 계엔, _바퀴)
            if _영향 is not None and _영향 < _바퀴.값영향문턱:
                목록.append("  %s — A-%s 값 %s 이 관측 범위 [%.4g, %.4g](%s) 밖이나 값 영향 %s(< %.0f%%) — 관측 끝의 탐색으로 본다(경보 · 3P 강등 아님 · S10R2-N4)"
                            % (쪽, r, " · ".join("%.4g" % v for v in 밖[:3]), 범[0], 범[1], 출, _영향글, _바퀴.값영향문턱 * 100))
                continue
            항 = [x for x in 제약 if ("%s" % x.get("적용행") or "").replace("A-", "").strip() == r]
            글 = " ".join("%s" % y for y in (근거.get(r) or []) if y)
            가리킴 = [x for x in 항 if (x.get("이름") and ("%s" % x["이름"]) in 글) or (x.get("조문") and ("%s" % x["조문"]) in 글)]
            밖줄[쪽].append(r)
            if not 가리킴:
                경보.append("  %s — A-%s 값 %s 이 관측 범위 [%.4g, %.4g](%s) 밖%s인데 근거가 외부 제약 항목(`제약.원가[]` — 적용행 %s · 이름 · 조문 · 경로 연도)을 "
                            "가리키지 않는다%s. 관측 밖으로 미는 근거는 끝나는 날이 조문에 있는 1차 자료뿐이다 — 근거가 없으면 관측 끝에서 멈춘다"
                            % (쪽, r, " · ".join("%.4g" % v for v in 밖[:3]), 범[0], 범[1], 출,
                               ("(끝에서 %s)" % _원) if _원 else ((" (값 영향 %s)" % _영향글) if _영향글 else ""), r,
                               "" if 항 else "(이 줄에 닿는 제약 항목이 없다)"))
            else:
                목록.append("  %s — A-%s 관측 밖 값을 외부 제약 「%s」(%s)이 받친다" % (쪽, r, 가리킴[0].get("이름"), 가리킴[0].get("조문") or "-"))
    # 3P 초안 — S9R1-N4: 잰 driver 가 하나도 없으면 「판정 불가」(재지 못한 것은 「관측 안」이 아니다), 일부만 쟀으면 잰 줄로만 판정하고 그 사실을 적는다
    사람 = ((가정.get("3P") or {}).get("시나리오") or {}) if isinstance(가정.get("3P"), dict) else {}
    순 = {"Possible": 1, "Plausible": 2, "Probable": 3}
    for 쪽 in ("비관", "기준", "낙관"):
        S = R[쪽]["요약"]
        가능 = (S.get("영구기간영업이익률") or 0) < 1.0 and S["주당가치"] >= 0
        초안 = "Probable" if 쪽 == "기준" else ("Plausible" if (가능 and not 밖줄.get(쪽)) else ("Possible" if 가능 else "Possible 아님"))
        덧 = ""
        if 쪽 != "기준" and 가능 and not 밖줄.get(쪽) and 못잰.get(쪽):
            if not 잰.get(쪽):
                초안 = "판정 불가"
                덧 = " — 범위 없는 driver %d개(%s)" % (len(못잰[쪽]), " · ".join("A-" + x for x in 못잰[쪽][:6]))
            else:
                덧 = " — 잰 driver %d개로만(범위 없는 driver %d개: %s)" % (len(잰[쪽]), len(못잰[쪽]), " · ".join("A-" + x for x in 못잰[쪽][:6]))
        사 = (사람.get(쪽) or {}).get("판정") if isinstance(사람.get(쪽), dict) else None
        목록.append("  3P 초안 — %s: %s%s%s" % (쪽, 초안, 덧, (" · 사람 판정 %s" % 사) if 사 else ""))
        if 사 and 초안 in 순 and 순.get(사, 0) > 순[초안]:
            경보.append("  3P — %s 를 사람은 %s 로 적었는데 도구 초안은 %s 다(%s). 관측 밖 driver 의 근거를 채우거나 판정을 내린다(레터 12절)"
                        % (쪽, 사, 초안, "관측 밖 driver %s" % " · ".join("A-" + x for x in 밖줄.get(쪽, [])) if 밖줄.get(쪽) else "영구기간 영업이익률 · 주당가치"))
        elif 사 and 초안 == "Possible 아님":
            경보.append("  3P — %s 는 산술로 성립하지 않는다(영구기간 영업이익률 ≥ 100%% 또는 주당 음수) — 사람 판정 %s" % (쪽, 사))
    # 우위가 깨지는 지점
    비, 기 = R["비관"]["요약"], R["기준"]["요약"]
    if (비.get("영구ROIC") is not None and 비.get("영구기간WACC") is not None and 비["영구ROIC"] > 비["영구기간WACC"] + 1e-6
            and abs(비["영구ROIC"] - (기.get("영구ROIC") or 0)) < 1e-9):
        한줄 = "%s" % ((((가정.get("시나리오이야기") or {}).get("비관") or {}) if isinstance((가정.get("시나리오이야기") or {}).get("비관"), dict) else {}).get("한줄") or "")
        말 = "  비관의 영구 RONIC %.2f%% 가 기준과 같고 영구기간 WACC %.2f%% 보다 높다 — 비관에서도 초과수익이 영원하다" % (비["영구ROIC"] * 100, 비["영구기간WACC"] * 100)
        if any(w in 한줄 for w in ("우위", "경쟁", "해자", "점유율", "가격 경쟁", "진입")):
            경보.append(말 + ". 비관 이야기가 우위가 깨지는 이야기면 RONIC → 영구 WACC · 종착 마진 → 운영 동종 중앙으로 가고, 그대로 두면 그 까닭을 적는다")
        else:
            목록.append(말 + " (비관이 우위가 깨지는 이야기가 아니면 그대로 둘 수 있다 — 그 까닭을 근거에 적는다)")
    return 오류, 경보, 목록


def 표본밖검사(가정, 라벨):
    """㊵ — **표본 밖 뒤돌려 맞추기(도구 점검 R-151).** 설비 계수 · 기준 단위원가를 직전 회계연도까지의 실적만으로 다시 재어
    가장 최근 실적 기간의 원가를 맞혀 본다 — 오차가 5% 를 넘으면 **경보**(사유는 `검토의견.R-151`).

    원가 줄 k 의 산식이 설비계수(실적 원가 ÷ (취득원가 13번 56g 의 기초 또는 평균 × 기간)) · 물량단위원가(실적 원가 ÷ (전사 판매량
    지수 4번 191 × 기간), 변동률 7k2 로 시험 열의 가운데 시점까지 민다)인 줄만 잰다. 보조 산식이 섞인 줄(비중 7k4 > 0)은 실적을
    산식별로 가를 수 없어 재지 않는다(목록). 엔진의 뒤돌려 맞추기(1k4 · 1k6 — 같은 계수를 실적 전부에 대는 표본 안)는 15번 몫이다."""
    오류, 경보, 목록 = [], [], []
    p = _판(가정)
    시 = _적용시나리오(가정)
    줄들 = [(k, x, 시트, 줄, 이름) for k, x, 시트, 줄, 이름 in _원가줄들(가정) if x.get("산식") in ("설비계수", "물량단위원가")]
    if not 줄들:
        목록.append("  재잴 원가 줄 없음 — 설비계수 · 물량단위원가 산식의 원가 줄이 없습니다")
        return 오류, 경보, 목록
    실 = list(p.실적)
    시험 = 실[-1]
    잴 = [i for i in 실[:-1] if p.회계연도[i] is not None and p.회계연도[시험] is not None and p.회계연도[i] < p.회계연도[시험]]
    if not 잴:
        목록.append("  재료 없음 — 시험 열(%s) 앞에 다른 회계연도의 실적 열이 없습니다" % p.열글(시험))
        return 오류, 경보, 목록
    try:
        R = _결과(가정, 시)
    except Exception as e:                                   # noqa: BLE001
        목록.append("  재료 없음 — 엔진을 못 불렀습니다: %s" % e)
        return 오류, 경보, 목록
    s191 = _줄(R, "4.Sales", "191")

    def 가운데(i):
        """그 열의 가운데 시점(연 — 종료일 − 기간 ÷ 2)."""
        import datetime
        끝날 = p.종료일[i]
        if not 끝날:
            return None
        날 = datetime.date(*(int(x) for x in str(끝날)[:10].split("-")))
        return 날.year + 날.timetuple().tm_yday / 365.25 - p.년[i] / 2.0

    넘은 = []
    for k, x, 시트, 줄, 이름 in 줄들:
        if x.get("보조산식") not in (None, "없음") and (_수(p.S(700 + 10 * k + 4, 시)) or 0.0) > 0:
            목록.append("  원가 줄 %d 「%s」 — 보조 산식(%s)이 섞여 실적을 산식별로 가를 수 없어 재지 않습니다"
                        % (k, 이름, x.get("보조산식")))
            continue
        원 = _줄(R, 시트, 줄)
        if x["산식"] == "설비계수":
            H = p.H(str(560 + int(x.get("자산군") or 1)))

            def 밑(i):
                if i < 1 or H[i - 1] is None:
                    return None
                b = H[i - 1] if x.get("설비기준") == "기초" else (
                    (H[i - 1] + H[i]) / 2.0 if H[i] is not None else None)
                return b * p.년[i] if b else None
            쓴 = [i for i in 잴 if 원[i] and 밑(i)]
            잰값 = (sum(원[i] / 밑(i) for i in 쓴) / len(쓴)) if 쓴 else None
            예측 = 잰값 * 밑(시험) if (잰값 is not None and 밑(시험)) else None
            무엇, 밑이름 = "설비 계수", "13번 %d(자산군 %s 취득원가)" % (560 + int(x.get("자산군") or 1), x.get("자산군") or 1)
        else:
            율 = _수(p.A(str(700 + 10 * k + 2), 시)[p.첫]) or 0.0

            def 밑(i):
                return s191[i] * p.년[i] if s191[i] else None
            가시 = 가운데(시험)
            쓴 = [i for i in 잴 if 원[i] and 밑(i)]
            잰값 = (sum(원[i] / 밑(i) * (1 + 율) ** ((가시 - 가운데(i)) if (가시 is not None and 가운데(i) is not None) else 0.0)
                       for i in 쓴) / len(쓴)) if 쓴 else None
            예측 = 잰값 * 밑(시험) if (잰값 is not None and 밑(시험)) else None
            무엇, 밑이름 = "기준 단위원가", "4번 191(전사 판매량 지수)"
        if 예측 is None or not 원[시험]:
            목록.append("  원가 줄 %d 「%s」 — 재료 부족: %s 의 실적 원가와 %s 이 함께 있는 열이 없습니다(잴 열 %s · 시험 열 %s) — "
                        "그 실적을 원천에 채우면 잽니다" % (k, 이름, 무엇, 밑이름, " · ".join(p.열글(i) for i in 잴), p.열글(시험)))
            continue
        오차 = 예측 / 원[시험] - 1
        목록.append("  원가 줄 %d 「%s」 — %s 실적으로 다시 잰 %s %.4g → %s 예측 %s vs 실적 %s (오차 %+.1f%%)"
                    % (k, 이름, " · ".join(p.열글(i) for i in 쓴), 무엇, 잰값, p.열글(시험), "{:,.0f}".format(예측),
                       "{:,.0f}".format(원[시험]), 오차 * 100))
        if abs(오차) > 0.05:
            넘은.append("원가 줄 %d 「%s」(%s) — 오차 %+.1f%%" % (k, 이름, 무엇, 오차 * 100))
    if 넘은:
        경보.append(
            "  **직전 회계연도까지로 다시 잰 계수가 최근 실적을 5%% 넘게 못 맞히는 원가 줄 %d개(R-151).**\n"
            "%s\n"
            "    표본 안에서만 맞는 계수일 수 있습니다 — 최근 기간에 원가 구조가 바뀌었는지(가동률 · 제품 구성 · 단가) 보고,\n"
            "    계수를 고른 기간과 그 까닭을 검토 의견(`검토의견.R-151`)에 적습니다"
            % (len(넘은), "\n".join("      · " + x for x in 넘은)))
    return 오류, 경보, 목록


# ────────────────────────────────────────────────────────────── 연결 검사 ㊶~㊽ (2026-10-16 — 키트 CLAUDE.md 「동인 지도 규칙」 표가 정본)
# 동인 지도가 선 뒤 매출 · 비용 · 투자가 같은 칸을 같은 뜻으로 읽는지 본다. **재료가 없거나 노드가 「해당 없음」이면 조용히 건너뛴다** —
# 경보가 아니라 「해당 없음 — 까닭」 목록 한 줄이다. 갈래 산출물(_raw/동인지도.json · 동인원천.json · 투자능력.json)은 가정 파일 곁의
# `_raw/` 를 먼저 보고(없으면 가정 파일 폴더 · 작업 폴더의 `_raw/`) 찾는다. 회사 · 업종 이름은 어디에도 없다.

_가정곳 = None           # main · 검사결과(가정경로=…)가 건다 — 갈래 산출물을 찾는 자리


def _갈래파일(이름):
    """갈래 산출물 하나(JSON) — (내용, 경로) 또는 (None, None)."""
    후보 = []
    if _가정곳:
        d = os.path.dirname(os.path.abspath(_가정곳))
        후보 += [os.path.join(d, "_raw", 이름), os.path.join(d, 이름), os.path.join(os.path.dirname(d), "_raw", 이름)]
    후보.append(os.path.join(os.getcwd(), "_raw", 이름))
    for p in 후보:
        if os.path.exists(p):
            try:
                return json.load(io.open(p, encoding="utf-8")), p
            except (OSError, ValueError):
                return None, p
    return None, None


def _검토(글, 번호):
    """자체검사에서 닫는 연결 검사의 경보 — 검토 번호를 글에 남긴다(`검토의견.<번호>` 로 닫는다 — 15번 줄은 없다)."""
    줄들 = ("%s" % 글).split("\n")
    줄들[0] = 줄들[0].rstrip() + "  (검토 %s — `검토의견.%s` 로 닫는다)" % (번호, 번호)
    return "\n".join(줄들)


def _해당없음(목록, 무엇, 까닭):
    목록.append("  해당 없음 — %s: %s" % (무엇, 까닭))


_필수노드 = (("연구개발", "연구개발"), ("인건비", "인건비"), ("유지CAPEX", "유지 CAPEX"), ("성장CAPEX", "성장 CAPEX"),
          ("감가상각", "감가상각"), ("운전자본", "운전자본"), ("법인세", "법인세"))
_강도 = ("명문", "실측", "유추", "추정")


def 동인지도완결성검사(가정, 라벨):
    """㊶ — **동인 지도의 노드마다 선택 · 근거 딱지 · 근거 강도가 있고, 지도와 `구조` 의 선택이 같은가** (R-155).

    빈 노드 = 오류(「해당 없음」 + `해당없음까닭` 은 빈 노드가 아니다 — `주의` 는 읽지 않는다). 강도가 「추정」뿐인 노드 = 경보.
    지도와 구조의 어긋남(원가 줄 산식 · 인건비 산정방식 · 유지규칙 · 상각방식) = 오류. 동인 지도 파일이 없는 옛 회차는 목록 한 줄."""
    오류, 경보, 목록 = [], [], []
    지도, 곳 = _갈래파일("동인지도.json")
    if not isinstance(지도, dict):
        # S10-04 — 옛 회차(v12 에서 옮긴 판 — `이전` 블록)와 새 회차를 가른다. E 가 돈 회차(_raw/동인진단.json)인데 지도가 없으면 v0 단계를 건너뛴 것이다
        진단, _진곳 = _갈래파일("동인진단.json")
        if isinstance(가정.get("이전"), dict):
            목록.append("  동인 지도 파일이 없다 — v12 에서 옮긴 옛 회차(`이전` 블록 · 건너뜀)")
        elif isinstance(진단, dict) or isinstance(곳, str):
            경보.append(_검토("  동인 지도 파일(_raw/동인지도.json)이 없다%s — E(동인진단)가 돈 회차인데 v0 를 짓지 않았다. "
                            "`python 스크립트/동인지도짓기.py 가정.json` 으로 v0 를 짓고(도구 판) 본선이 근거를 보탠다(결정 2 — 지도를 멈춤 앞에)"
                            % ((" · 읽지 못함: %s" % 곳) if 곳 else ""), "R-155"))
        else:
            목록.append("  동인 지도 · 동인진단 파일이 둘 다 없다 — 갈래 산출물 밖의 판(예시 · 시험 판 — 건너뜀)")
        return 오류, 경보, 목록
    노드들 = [x for x in (지도.get("노드") or []) if isinstance(x, dict)]
    p = _판(가정)
    필수 = list(_필수노드) + [("원가줄%d" % x["번호"], "원가 줄 %d" % x["번호"]) for x in p.구.목록("원가줄")]

    def 찾기(키):
        return [x for x in 노드들 if ("%s" % x.get("노드", "")).replace(" ", "").startswith(키)]
    for 키, 이름 in 필수:
        걸린 = 찾기(키)
        if not 걸린:
            오류.append("  %s 노드가 동인 지도에 없다 — 선택 · 근거를 적거나 「해당 없음」과 `해당없음까닭` 을 적는다" % 이름)
            continue
        for x in 걸린:
            선택 = ("%s" % (x.get("선택") or "")).strip()
            까닭 = ("%s" % (x.get("해당없음까닭") or "")).strip()
            if 선택 == "해당 없음" or (not 선택 and 까닭):
                if not 까닭:
                    오류.append("  %s — 선택이 「해당 없음」인데 `해당없음까닭` 이 비었다(빈 노드로 센다)" % x.get("노드"))
                continue
            if not 선택:
                오류.append("  %s — 선택이 비었다" % x.get("노드"))
                continue
            if not ("%s" % (x.get("근거") or "")).strip():
                오류.append("  %s — 근거(출처 딱지)가 비었다" % x.get("노드"))
            강도 = ("%s" % (x.get("근거강도") or "")).strip()
            if 강도 not in _강도:
                오류.append("  %s — 근거강도 「%s」 — 명문 · 실측 · 유추 · 추정 가운데 하나를 적는다" % (x.get("노드"), 강도))
            elif 강도 == "추정":
                경보.append(_검토("  %s — 근거강도가 「추정」뿐이다(판단 칸이면 멈춤 문항 후보 — 거친 민감도 상위 3 ∩ ±5%%)" % x.get("노드"), "R-155"))
    # 성격 확정(S4-C9 — 「변동 · 고정 판정은 사람이 한다」) — 원가 줄 노드마다 `성격확정` {"누가": "사람", "시각", "방식": 답 · 통지무응답}.
    # 도구(E)의 성격판정은 초안이다. E 가 「볼것」(사전과 갈림 · 분리 필요 · 근거 추정)을 단 노드는 통지 무응답이 아니라 답으로 확정한다
    진 = _동인진단읽기(가정)
    볼 = {y.get("노드"): y.get("볼것") for y in ((진 or {}).get("성격확인") or []) if isinstance(y, dict) and y.get("볼것")}
    미확정, 답없음 = [], []
    for x in p.구.목록("원가줄"):
        for y in 찾기("원가줄%d" % x["번호"]):
            확 = y.get("성격확정") if isinstance(y.get("성격확정"), dict) else {}
            if 확.get("누가") != "사람":
                미확정.append(y.get("노드"))
            elif 볼.get(y.get("노드")) and 확.get("방식") != "답":
                답없음.append("%s(%s)" % (y.get("노드"), 볼[y.get("노드")]))
    # S5-05 — 「판정은 사람이 한다」의 실질 집행: 방식 = 답 이면 멈춤 기록(`_raw/멈춤기록.json` 의 `답[]` — 시각 · 노드 · 답 원문)에 그 노드의 답이 있어야 하고,
    # 방식 = 통지무응답 이면 그 노드를 실은 통지(`통지[]` — 시각 · 노드들)가 확정 시각보다 앞서 있어야 한다. 기록이 없으면 자기 표시다
    기록, 기록곳 = _갈래파일("멈춤기록.json")
    답들 = [x for x in ((기록 or {}).get("답") or []) if isinstance(x, dict)] if isinstance(기록, dict) else []
    통지들 = [x for x in ((기록 or {}).get("통지") or []) if isinstance(x, dict)] if isinstance(기록, dict) else []
    무기록 = []
    for x in p.구.목록("원가줄"):
        for y in 찾기("원가줄%d" % x["번호"]):
            확 = y.get("성격확정") if isinstance(y.get("성격확정"), dict) else {}
            if 확.get("누가") != "사람":
                continue
            노 = "%s" % y.get("노드")
            if 확.get("방식") == "답":
                if not any(("%s" % a.get("노드", "")).replace(" ", "") == 노.replace(" ", "") and ("%s" % (a.get("답") or "")).strip() for a in 답들):
                    무기록.append("%s(답 — 멈춤 기록에 그 노드의 답 원문이 없다)" % 노)
            elif 확.get("방식") == "통지무응답":
                if not any(노.replace(" ", "") in [("%s" % n).replace(" ", "") for n in (u.get("노드들") or [])]
                           and ("%s" % u.get("시각", "")) <= ("%s" % 확.get("시각", "9999")) for u in 통지들):
                    무기록.append("%s(통지무응답 — 그 노드를 실은 통지 기록이 확정 시각 앞에 없다)" % 노)
    if 무기록:
        경보.append(_검토("  성격 확정이 멈춤 기록과 맞지 않는다 — %s. 사람의 답은 `_raw/멈춤기록.json` 의 `답[]`{시각, 노드, 물음, 답(원문), 누가}에, 통지는 `통지[]`{시각, 노드들}에 "
                        "본선이 그 자리에서 적는다(집대성 3단계 — 확정 표시만으로는 사람의 판정이 아니다)%s" % (" · ".join(무기록[:6]), (" · 기록 %s" % 기록곳) if 기록곳 else " · 기록 파일 없음"), "R-155"))
    if 미확정:
        경보.append(_검토("  원가 줄 노드의 성격 판정이 사람 확정 전이다 — %s. 도구(E)의 판정은 초안이다 — 멈춤 통지의 성격 확인 목록을 사람이 보고 지도 노드에 "
                        "`성격확정` {\"누가\": \"사람\", \"시각\", \"방식\"} 을 적는다" % " · ".join(미확정[:6]), "R-155"))
    if 답없음:
        경보.append(_검토("  사전과 갈린 · 분리 필요 · 근거 추정 노드가 통지 무응답으로 확정됐다 — %s. 이 노드는 사람의 답으로 확정한다(`방식: 답`)"
                        % " · ".join(답없음[:6]), "R-155"))
    # S9-10 — 답 ↔ 가정: 멈춤 기록의 답에 대상 · 값(판단 칸 · 축 값을 고른 답)이나 축(시나리오 driver 로 고른 줄)이 있으면 가정에 그대로 옮겼나 본다
    import 거친바퀴 as _바퀴                                    # noqa: PLC0415
    안옮김 = []
    for a in 답들:
        대 = a.get("대상")
        대 = [("%s" % y).replace("A-", "").strip() for y in (대 if isinstance(대, list) else ("%s" % 대).split("+"))] if 대 else []
        if 대 and isinstance(a.get("값"), (int, float)):
            for d in 대:
                if not d.isdigit():
                    continue
                # S10-10 — 「지금」은 거친 바퀴 · 멈춤 문항과 같은 함수(예측 열 평균 · 수준 물량 줄은 예측 연평균 증가율 · 답에 지금자가 있으면 그 자)
                if "%d" % int(d) in _바퀴.수준물량줄 and a.get("지금자", "누적") == "누적":
                    지금 = _바퀴._수준CAGR(가정, "%d" % int(d), "기준", importlib.import_module("엔진.민감도")._예측누적년(가정)[0])
                else:
                    지금 = _바퀴._지금값(가정, d, "기준", {"영구": "영구", "첫열": "첫열"}.get(a.get("지금자"), "예측"))
                if 지금 is None or abs(지금 - a["값"]) > 1e-9 * max(1.0, abs(a["값"])):
                    안옮김.append("A-%s 답 %s · 가정 %s" % (d, a["값"], 지금))
        축 = a.get("축")
        if isinstance(축, list) and 축:
            선 = {("%s" % y) for 쪽 in ("비관", "낙관") for y in (((가정.get("시나리오이야기") or {}).get(쪽) or {}).get("driver") or [])
                 if isinstance((가정.get("시나리오이야기") or {}).get(쪽), dict)}
            빠 = [("%s" % y) for y in 축 if ("%s" % y) not in 선]
            if 빠:
                안옮김.append("축 답 %s 가 시나리오이야기 driver 에 없다" % " · ".join(빠))
    if 안옮김:
        경보.append(_검토("  멈춤 답이 가정에 그대로 옮겨지지 않았다 — %s. 사람이 고른 값 · 축은 가정 파일에 그대로 옮긴다(옮기지 않을 까닭이 있으면 검토 의견에 적는다 — S9-10)"
                        % " · ".join(안옮김[:6]), "R-155"))

    # 지도 ↔ 구조
    for x in p.구.목록("원가줄"):
        for y in 찾기("원가줄%d" % x["번호"]):
            선택 = "%s" % (y.get("선택") or "")
            if 선택 and 선택 != "해당 없음" and x["산식"] not in 선택:
                오류.append("  원가 줄 %d — 지도의 선택 「%s」와 구조의 산식 「%s」가 다르다" % (x["번호"], 선택[:60], x["산식"]))
    for 키, 구키, 값 in (("인건비", "인건비", p.구["인건비"]["산정방식"]), ("유지CAPEX", "투자", p.구["투자"]["유지규칙"]),
                        ("감가상각", "투자", p.구["투자"]["상각방식"])):
        for y in 찾기(키):
            선택 = "%s" % (y.get("선택") or "")
            if 선택 and 선택 != "해당 없음" and 값 not in 선택:
                오류.append("  %s — 지도의 선택 「%s」에 구조의 값 「%s」가 없다" % (키, 선택[:60], 값))
    목록.append("  동인 지도 %s · 노드 %d" % (os.path.basename(곳), len(노드들)))
    return 오류, 경보, 목록


def 능력투자짝검사(가정, 라벨):
    """㊷ — **능력 증분과 프로젝트 투자가 값 · 시점으로 짝을 이루나** (R-156 — 2026-10-17 S5 판).

    ① 건설중인자산 · 기집행(S5-20) — Σ 기집행(표 1600 + j) ≤ 기준일 건설중인자산(567) + 최근 두 회계연도 편입(569, 없으면 현금 CAPEX 80) ·
       마지막 예측 열의 건설중인자산 잔액(8번 13) > 0 이면 그 투자의 상각 · 매출이 영구기간에 서지 않는다 · 프로젝트가 있는데 건설중인자산대체 =
       아니오이고 기준일 잔액이 있으면 그 잔액은 영원히 대체 · 상각되지 않는다
    ② 라인(능력 단위 — 생산설비 · 매장 · 서버 · 좌석) 값 짝(S5-13) — 시나리오마다 라인 j 의 능력 증분(A-668+2j 예측 최대 − 기준일)과 그 라인 투자
       (프로젝트 A-86p 합 + 기집행 표 1600 + j)로 단위 투자비를 내고 ⓐ 같은 회사 라인끼리(중앙값 ±허용) ⓑ F 투자능력의 명시 대응(`단위능력당투자비[].라인` ·
       `값짝[].능력단위` = 라인 이름)과 견준다. 회사 전체로 잰 F 실측(`라인` 없음)은 목록에 나란히 적는다(단위가 다를 수 있다)
    ③ 시점(S5-16) — 그 라인 프로젝트의 첫 투자 열 + 리드타임보다 능력이 먼저 서거나, 마지막 투자 열 + 리드타임 + 2년 안에 능력이 늘지 않으면 경보.
       능력이 없던 라인(기준일 능력 0 — 새 시설)의 프로젝트 리드타임이 0 인데 근거(가정 근거 86p)에 「리드타임」 까닭이 없으면 경보
    ④ 저량 구분(S5-18 — 매장 · 가입자 · 설치기반) — 유입(A-57s)이 느는데 그 구분의 투자(프로젝트 · 성장규칙 · 매출연동 · 판매량연동)가 없으면 경보
    허용 폭 = `관측.능력투자허용폭`(기본 ±30%). 능력 · 저량 구분이 없고 건설중인자산도 없으면 건너뛴다."""
    오류, 경보, 목록 = [], [], []
    p = _판(가정)
    투구 = p.구["투자"]
    허용 = _수(((가정.get("관측") or {}).get("능력투자허용폭"))) or 0.30
    표 = 가정.get("표") or {}
    프들 = [x for x in (투구.get("프로젝트") or []) if x.get("번호")]

    def 기집(j):
        t = 표.get(str(1600 + j)) or {}
        return sum(_수(v) or 0.0 for k, v in t.items() if str(k).startswith("기집행")) if isinstance(t, dict) else 0.0

    # ① 건설중인자산 · 기집행
    cip0 = _수(p.H기준일(567))
    기집합 = sum(기집(j) for j in range(1, 16))
    if 기집합 > 0:
        편 = [x for x in (p.H(569)[i] for i in p.FY실적[-2:]) if x is not None] or [x for x in (p.H(80)[i] for i in p.FY실적[-2:]) if x is not None]
        상한 = (cip0 or 0.0) + sum(편)
        if 상한 > 0 and 기집합 > 상한 * 1.05:
            경보.append(_검토("  기집행 합(표 1600 + j) %s 가 기준일 건설중인자산 %s + 최근 두 해 편입 %s 를 넘는다 — 기집행 어림(회사 발화 총액 − 예측기간 투자)이 "
                            "이미 가동 중인 자산까지 품었는지 본다(자본적지출 기집행 규칙 · 딱지 [판단 · 어림]과 식)"
                            % (_금액(기집합), _금액(cip0 or 0.0), _금액(sum(편))), "R-156"))
        else:
            목록.append("  기집행 합 %s ≤ 기준일 건설중인자산 + 최근 편입 %s" % (_금액(기집합), _금액(상한)))
    if cip0 and 프들 and 투구.get("건설중인자산대체") != "예":
        경보.append(_검토("  기준일 건설중인자산 %s 이 있고 프로젝트가 있는데 구조.투자.건설중인자산대체 = 아니오 — 엔진은 건설중인자산을 따로 굴리므로 기준일 잔액이 "
                        "영원히 본계정으로 대체 · 상각되지 않는다(853 으로 대체 일정을 적는다)" % _금액(cip0), "R-156"))
    try:
        R0 = _결과(가정, "기준")
        y13 = _줄(R0, "8.CapEx", "13")
        if y13[p.끝] is not None and (y13[p.끝] or 0.0) > max(1e-9, 0.02 * (_수(_줄(R0, "8.CapEx", "21")[p.끝]) or 0.0)):
            경보.append(_검토("  마지막 예측 열(%s)의 건설중인자산 잔액 %s — 완공되지 않은 투자가 창 밖에 남아 그 상각 · 매출이 영구기간에 서지 않는다(리드타임 · 창 길이를 본다)"
                            % (p.열글(p.끝), _금액(y13[p.끝])), "R-156"))
    except Exception:                                    # noqa: BLE001 — 엔진을 못 돌리면 다른 검사가 알린다
        pass

    # ② · ③ 라인(능력 단위)
    주인 = {라인["번호"]: (x["번호"], 라인.get("이름") or "라인 %d" % 라인["번호"]) for x in p.구.목록("매출구분")
          if x.get("판매량산정") == "능력" for 라인 in x["라인"]}
    저량 = [x for x in p.구.목록("매출구분") if x.get("판매량산정") == "저량" and x.get("번호", 9) < 6]
    if not 주인 and not 저량:
        _해당없음(목록, "능력–투자 값 짝", "판매량산정 = 능력 · 저량인 매출 구분이 없다(능력이 매출 상한이 아닌 꼴)")
        return 오류, 경보, 목록
    연, _ = _갈래파일("개체연결.json")                    # 2026-10-21 통계 기법 5 — 표기가 다른 짝 후보를 목록에만(판정은 글자 일치 그대로)
